/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200629-7","meetingId":"r02-cm06","date":"2020年6月29日","dateIso":"2020-06-29","committee":"厚生委員会","time":"午前１０時００分～午後 ２時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を87件抜き出しています。","topics":[{"id":"topic-01","title":"第４５号議案、品川区立在宅サービスセンター条例の一部を改正する条例","agenda":"第４５号議案、品川区立在宅サービスセンター条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"工事の一部完了ということですけれども、全て完了するのはいつなのかということと、居ながら工事をやられたということですが、荏原複合施設も居ながら工事のために一時移転ということを聞いておりますので、この戸越台複合施設の居ながら工事で、何か課題などありましたらお伺いできればと思います。以上２点、お願いいたします。","respondent":"宮尾高齢者福祉課長","answer":"全体の工期ですが、今回はまだ一部完了ということで、残る中学校の部分、こちらが夏の時点ではまだ終わっていないというふうに聞いております。中学校部分につきましては、令和３年３月に竣工予定というふうに聞いております。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"周辺症状というのですか、見当識であるとか、様々なところでますます混乱をしてしまうというような一般的な話があると思うのですが、場所を移られたことによって、何かそのようなご相談があったのかどうか、またこれから元に戻るというところで、途中から参加されている方がもしかしたらいらっしゃるかもしれないですし、趣旨とすれば。","respondent":"宮尾高齢者福祉課長","answer":"まさに委員がおっしゃるとおり、認知症の方に対するケアといいますか、対応というのはしっかりとした配慮が必要だというふうに我々も認識をしております。","id":"exchange-002"},{"speaker":"渡部委員","kind":"確認","question":"前の資料を見て分かるかもしれないですけれども、２点伺います。１点は、この８月に戻る、２年間で戻る意向というものが予定どおりだったのかどうなのか。１個は確認で、先ほど特養の定員数の話があったのですけれども、それというのは、３月の調整会議のときに十何人ドンと乗っかって、前の定員に戻すというようなイメージなのか、その辺を伺います。","respondent":"宮尾高齢者福祉課長","answer":"それと今回、定員が一気に元に戻るということになりますので、この点につきましては、今回の調整会議におきましても想定をしていくのですけれども、ただ、一気に減った分を戻すかどうかというところにつきましては、施設側の体制ですとか。","id":"exchange-003"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今、説明の中で、昨年８月締切りの申請者や入所者の数字は伺ったのですけれども、今年２月締切りの申請者数はいかほどだったのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"本年２月の特養の申請状況ですが、お申込みを頂いた方の総数は４７９人です。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"それで、もう入所が決まった方は、その中ではいらっしゃるのですか。","respondent":"宮尾高齢者福祉課長","answer":"ちょっと今、詳しい人数は手元に資料がございませんが、名簿自体は４月１日からの有効期間、登録期間ということになっておりますので、実際にもう入所されている方はいらっしゃいます。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"そうすると、その後土地取得や建設計画があるのではないかと。それをどのように考えていらっしゃるのかお聞きしたいということが１つ。それから東大井の都営住宅跡地、もちろんこの請願にもあるように、ここに特養ホームや障害者施設を作っていただきたいと思っているのですが、区としてはどう考えていらっしゃるかお聞きしたいと思います。いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"それから東大井の用地の件につきましても、先般ご答弁があったとおり、東京都からの意向調査があって、それに対して福祉施設等に活用したいという回答をしているというふうに聞いているところです。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"ですから、私が伺いたいのは、この８割の方が落ちるという状態、これは非常に改善が必要だと思いますけれども、改善が必要だとは思われませんかという点、それから不合理な点数制度、特に年齢に関して不合理だと思いますが、この、７５歳以上でないと点数がつかないという年齢の要件、これは外すべきではないかと思いますけれども、いかがでしょうか。お考えをお聞かせください。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"今後も適地が見つかれば、積極的に必要数を把握しながら、また今後の後期高齢者が増える中で、施設についてはまだ整備が若干必要であろうというところは認識しておりますので、計画の中でしっかり考えていきたい。やはり統計的に見ましても、これより上になっていきますと認定率、こういったものにも大きく影響してくる１つの大きな基準となるラインだと考えていますので、現時点では、ここの点数に関して改善をする。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問・要望","question":"だからこそ、５００全部が特養ではないのかもしれません。４０代、５０代、６０代の人は、この点数が必ず零点になってしまうわけですから、絶対入れなくなってしまうわけです。ですから、そのような意味で、もう適応していないことが現実によって証明されているわけですから、この年齢要件は既に現実に合っていないことが証明されている以上、外していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問・要望","question":"あまりにも足りないということがあるわけですから、そこのところはきちんと捉えて、その現実に対応するような増設計画、きちんと計画して増設をしていくという、この請願の趣旨どおりのことをやっていただきたいと私は非常に強く思います。これが区政の喫緊の課題の１つだと非常に強く思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"これが課題だと。小規模多機能が増えていないのであれば、誘致というか、小規模多機能を事業者にやってもらうのに何の課題があるのか、そこのところをちょっと、請願から若干ずれるかもしれませんけれども、今回大筋からいって、先ほどの答弁を聞いていて疑問に思ったのですが、教えていただければと思います。","respondent":"寺嶋福祉計画課長","answer":"そういう意味で、そういったＰＲはしっかりしていく必要があるということと、やはりご本人にとって一番いい介護、よりいい介護ができるように、我々もしっかり、周知も含めてサービス提供をしていく必要があるというふうに考えております。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"意見","question":"声はかけていただいているということです。それで、より看護小規模多機能のほうが望ましいということだったのですけれども、先ほどのご説明の中では、今後計画の中で、都市計画の中で考えていくというようなお話もあったのですが、今現在、ごめんなさい、私調べてこなかったのですけれども、区内にどれぐらいの小規模多機能、看護小規模多機能……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もちろんそうですね。今回の請願の趣旨が特養ホームや障害者施設の増設を求める請願となっておりますので、そのご説明の中で、このようなことを求められる請願の趣旨として、特養ホームばかり区内の中から声が上がっているということでしたので、そういったところの解消というところで、今質問させていただいているのですけれども、よろしいでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"現時点で区内に小規模多機能型居宅介護と呼ばれるものは、１０カ所あります。それとは別に看護小規模多機能型居宅介護は現時点で２カ所、区内に整備をしています。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのような点では、私はぜひ特養ホームに入れなかった方がその後どうされているのか、どのような思いなのか、それで小規模多機能など、そのような制度があるということを知っていれば、それを使いたかったのか、その辺のところも含めて、ぜひ区としてつかんでいただきたいと私は思うのですけれども、いかがでしょうか。そのようなことに対してはどう考えられているのか、その点についてもお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"そういったところをトータルに見て、お困りの度合いというものを決めているというふうに認識をしていますので、一律に年齢だけでというところで判断をしている、そのようなつもりはございません。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"年齢で排除しているということではなくても、年齢が４項目のうちの１つになっているわけです。それで、若い方で突然倒れて、最重度の、要介護５というような状況で、在宅では高齢のお父さん、お母さんでとても見られないという方が、ちょうど特養ホームの適用であるにもかかわらず、そのような方はどんなに待っても特養に入れないのです。そのような方に対しては本当に深刻です。その点はいかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"確かに我々も、年齢の点数のところでほかの方と比べて低くなっている方、これについて全くよしとしているわけではなく、例えば、現実的なご相談の中で、特養を前提に相談をお受けする中で、ではそのほかにどのような選択肢を取り得るのか。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だけれども、どうにもならないというように区のほうから言われているのです。特養ホームにはもうどうしても入れないということで言われているのです。９０歳だったら２０点つくところが、７０歳だったらゼロ点なのです。そこのところで、本当に年齢で優先度を決めるというようなことは、ぜひとも検討していただきたいと。改善に向けて検討していただきたいと強く要望をしておきたいと思います。","respondent":"松山障害者福祉課長","answer":"委員お尋ねの、現時点で不足する施設としましては、基礎調査結果でも出ているのですが、やはりグループホームというものが挙げられています。そのため、グループホームにつきまして、先ほど申し上げたような増設支援を行っているところです。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今のところでいえば、区の認識としてはグループホームだけという、就労Ｂなども他区のところにかなり行かれていたり、放課後等デイサービスなども足りないのではないかなどという声も伺っているのですけれども、そのような点では、取りあえず区ではグループホームが足りないというところでの認識ということでいいのでしょうか。","respondent":"松山障害者福祉課長","answer":"そのほかに放課後等デイサービスというお声もありますけれども、今後開催される策定委員会の中で、基礎調査の結果やヒアリング結果を踏まえまして、ニーズというものはきちんと把握をしていきたいと考えています。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当に障害者のサービスというものは、より充実をさせていっていただきたいと考えていますので、これからも様々な団体の皆さんからなど、お話を聴きながら、ぜひ充実の方向で取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いをいたします。今理事者からご説明がありましたとおり、施設整備や増設支援の調整を続け、一定の道筋が出ているものと思います。区のほうでも動いていただいていると理解しましたので、本件に関しましては不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"俺は品川区に今、８０年住んでいるのだ、７０年住んでいるのだということだって、場合によっては声が大きく上がってくる可能性だってあるわけで、ですからその辺というものはやはり総合的な判断の中で、今やっているやり方で私はいいのかなと思っています。ですからその必要な分、ほかにも頼りながら進めていかなければならないのかなと考えています。すみません。話が長くなりました。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。毎年５００人も申請があり、８割以上の方が入れない、それがずっと続いているという状況があります。これが解消されるまできちんと計画を立てて増設していくことが、特養ホームに求められている、区政に求められている喫緊の課題だと思います。障害者施設につきましても、自立支援協議会でも要求が出ていると伺っています。採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今日結論を出すということで、不採択です。ただ、先ほどもご説明にあったのですけれども、様々な細かいご相談があったときには、今後丁寧に対応していただきたいことと、就労Ｂのほうについては、現行の事業所での支援の充実というか、定員になかなか満たないところがあったりするところなどは改善して、今すぐにできることをまずやっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-03","title":"われているさなか「住居 特に食事」などに困難を来している多くの貧困下にある子どもたち","agenda":"われているさなか「住居 特に食事」などに困難を来している多くの貧困下にある子どもたち","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"税務課や国保医療年金課など、いろいろな窓口で生活困窮者の把握をなされていると思うのですけれども、庁内で暮らし・しごと応援センターに相談に行くようにといった案内が出されているのでしょうか。その点をお伺いしたいと思います。それからもう一つ、給付金をどうやったら受けられるかというような相談にも乗られているのでしょうか。その２点をお伺いしたいと思います。","respondent":"櫻木生活福祉課長","answer":"庁内の連携についてですが、生活困窮者自立支援制度の連携会議というものを庁内の関係部署を通じて行っておりまして、その中でそのような生活困窮者の方のご相談があったら、暮らし・しごと応援センターをご案内いただけるようご案内しています。","id":"exchange-022"},{"speaker":"おくの委員","kind":"意見","question":"給付金をどうやったら受けられるかの相談にも乗っているということなのですね。","respondent":"櫻木生活福祉課長","answer":"基本的に特別定額給付金の件のお尋ねですと、特にホームレス等の方々につきましては、まずこちらで一般的な生活困窮者の方へのご相談の対応という中で、このような方法を関係部署と連携しながらご案内をしています。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから前にもちょっとご要望したというか、お伺いしたのですが、「生活にお困りの方へ」という、ホームページなのですが、そもそもたどり着くのが大変ですし、生活に困窮している方の相談窓口はこちらというようにあるのですけれども、１ページだけあって、本当に目次でしかないのです。お願いします。","respondent":"櫻木生活福祉課長","answer":"制度の周知またはご案内方法につきましては、現在のところ、情報量として物足りないところがあることは承知しておりますので、機を見て適宜情報を付加していくような方向で考えております。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"陳情要旨にある、区内のホームレス状態にある人が食べ物を得られるように早急に調査し、備蓄している食料の提供を行ってくださいという内容なのですが、先ほどのご説明の中で、夜間宿直室でも食料を配布していますよということで、幾つかの種類の食べ物のご紹介がありましたけれども、私はちょっと情報を得ていないのですが、教えていただける範囲で、先ほど見回り。","respondent":"櫻木生活福祉課長","answer":"それと緊急事態宣言前後も含めて、食料を取りにいらっしゃった方について、実績はございませんでした。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"どのようにして周知を、そもそも周知をすべきものと考えているのかどうかというところについてお伺いしたいと思います。","respondent":"櫻木生活福祉課長","answer":"今、ご案内さしあげた食の提供というものは緊急対応という意味合いが強くて、翌日、または翌々日、もしくは休日が明けるまでの間、しかるべき対応が取れる体制までの間、食を提供することで対応していただくということが主眼ですので、積極的に周知するというよりは。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"この前文の渋谷区の例が、新型コロナウイルス感染症の感染防止のために自粛要請があって今炊き出しができないというような内容になっていますが、品川区に関してもホームレスの方が炊き出しを受けられているのかという状況を把握しているのか、また、そういったものが今自粛状態にあるのかどうか、それが解除されて再開をされたのかどうか。","respondent":"櫻木生活福祉課長","answer":"区のほうでホームレス状態の方々が実際に炊き出しに行かれているとか、どのような食の生活をされているかという詳細については把握できておりませんが、巡回時にお話しさせていただける状況のときに、生活状況等を伺って確認しているという状況です。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど、庁内の連携会議というものがあると伺ったのですけれども、何という連携会議かということを聞き逃してしまって、もう１回教えていただけますでしょうか。そのようなところで、ぜひこの食事というものは、住まいと食事とここにも書いていますけれども、一番の基本なので、その辺のところはぜひお願いしたいと思うのですが、いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"それとホームレスの方への食の周知ですが、先ほど申し上げたとおり、この制度自体は緊急対応という意味合いが強いものでして、常時食を提供するということを念頭に置いたものではございませんので、当然ホームレスの方々が食に困られたときはぜひお越しいただいて。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ちょっと連携会議の名前が長くて書き切れなかったのですけれども、これはどのようなメンバーでされているのかということを１点お聞かせいただきたいということと、庁内でそのような連携会議ができているというところでいえば、この厚生労働省が出している「新型コロナウイルスに関連した生活困窮者自立支援制度の活用について」というところでも、福祉、就労、教育、税務、住宅、その他の部局において。","respondent":"櫻木生活福祉課長","answer":"併せて生活福祉課のほうからは、このような支援ができますので該当する方がいらっしゃった場合はご案内くださいという依頼をしているというような会議です。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"先日も私が相談を受けたホームレスの方で給付金を何とか受けられないかと思って、給付金をもらいたいけれどもどうしたらいいかというふうなことで、生活福祉課にまず行ったと。その辺のところは少し改善が必要なのではないかと思うのですけれども、いかがでしょうか。","respondent":"櫻木生活福祉課長、寺嶋福祉計画課長","answer":"今ご指摘いただきましたお話としましては、電話を受けた者がホームレス状態にいらっしゃる方なのかどうかというところを把握し切れていなかったというところはあるのかと思いますが。そこの点についてはご説明させていただきたいと思います。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところを制度として改善して、国としても改善してほしいというような思いもしているのですけれども、そこのところはぜひセーフティーネットというところでお願いしておきたいと思います。改めて住居確保給付金がどれぐらいまでいっているのか、分かったら教えていただきたいのが１点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ありますよ。だって住まいと食事ですから。困窮者への支援というようなことですから、そのようなところで、私はそこのところのアクセスもしっかりとできるようにお願いしたいと思うのですけれども、その点もお聞かせください。","respondent":"寺嶋福祉計画課長、櫻木生活福祉課長","answer":"それから社会福祉協議会のほうも増員等を含めまして、今順調に対応が進んでいるというふうに聞いておりますので、ご報告します。住居確保給付金につきまして正確な数字が手元にはございませんが、３００を超えて４００に近い数字になっている状況かと感じております。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"緊急小口資金は、もちろん国のほうから見ていけば、社会福祉協議会でやっているということが分かりますので、社会福祉協議会のホームページにたどり着くと、そこから東京都のホームページに飛んで、東京都の申請書というものが出てきて、そこから申請書を印刷して、それで郵送できるというような仕組みになっているのは分かるのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"西村委員","kind":"確認","question":"本日結論を出すで、不採択でお願いをいたします。先ほどご説明いただきましたとおり、暮らし・しごと応援センターにて休日・夜間を含めて対応中だということ、あとは連携会議もあると確認が取れましたので、不採択でお願いしたいと思いますが、１点だけ、すみません。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"渡部委員","kind":"意見","question":"本日結論を出して、私も不採択でお願いいたします。周知を何とかだというよりも、困った人を助ける姿勢というものがあるわけで、相談に来られたらその相談に乗る。多分。もう本当に食べるものがなくなってしまった、どうしようというときに、今課長にご説明いただいたような仕組みがあるということが品川区のセーフティーネットなのだと思うので、引き続き続けていただければと思います。不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。先ほど質疑の中でも確認させていただきましたが、やはり特にホームレスという方に関しては、非常に難しい中で適切な対応をしていただいているのかなと思います。これについても、ご相談に来た方に対してのご案内をして、券を発行するというお話なのですけれども、基本的に丁寧に寄り添っていただきたいということは要望を申し上げまして、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"おくの委員","kind":"意見","question":"本日結論を出すで、採択をお願いいたします。ホームレス状態の方だけではなく、貧困、生活困窮者、子どもや外国人などということですので、生活困窮者の方全般に対してチラシやホームページなどで周知し、幅広く援助をという趣旨だと思います。それで、そのようなことは本当に必要だと思います。採択したいと思います。お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"本日結論を出すということで、不採択でお願いします。いろいろご説明いただきました緊急対応ということで、ホームレス状態の方を含めた方々に対応されているということですので、不採択といたしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-04","title":"令和２年陳情第３０号、「品川区障害福祉計画・障害児福祉計画策定委員会」等の委員委嘱・公募および開催に関する陳情","agenda":"令和２年陳情第３０号、「品川区障害福祉計画・障害児福祉計画策定委員会」等の委員委嘱・公募および開催に関する陳情","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"計画策定委員会ですけれども、これは何人の委員から構成されていて、どのような方が入るのでしょうか。決まっているのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"計画策定委員についてですけれども、委嘱のための手続きを進めているところです。メンバーについてですけれども、想定としましては、学識経験者や保健、福祉、教育関係の方々、それから障害者団体、公募の区民委員等が含まれております。","id":"exchange-039"},{"speaker":"おくの委員","kind":"質問","question":"前の厚生委員会で出されたスケジュール表なのですけれども、計画策定委員会のほかに庁内連絡会というものがあるのですが、これのメンバーは、何人いて、どのような方で構成されているのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"こちらのほうも今進めているところなのですけれども、保健、福祉、医療、教育等関係する部署、所管の方に参加していただく予定です。","id":"exchange-040"},{"speaker":"おくの委員","kind":"質問","question":"もう一つ、すみません。それからこの計画の策定は、業者に委託するというような予定はあるのでしょうか。もし委託されるなら、業者名を教えてほしいのですけれども。","respondent":"築山障害者施策推進担当課長","answer":"こちらについては策定の支援ということで、株式会社インテージリサーチというところに委託をしております。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうすると、７月下旬にこの５月分をされるということになるのかと思うのですけれども、７月下旬に５月分をされて、８月上旬に骨子案検討というようにはならないのではないかと思うのですが、その辺の、この委員会に出されたスケジュールが、おおよそ何月にどうなっていくというようにずれ込んでいくのか、そこのところをお聞かせいただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"それから８月上旬に計画骨子案検討を予定しておりましたが、こちらが８月末頃になる予定です。それ以降につきましては、おおむね当初のスケジュールどおりの予定となっております。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのアンケートのまとめの中身というものを、私も前の厚生委員会のときにいろいろ指摘させていただいたのですけれども、策定委員会だったり、自立支援協議会への報告のときには、もう１回作り直す形で報告しますということで、このままは出しませんというようなことで言われていたのですが、そのアンケートは今どうなったのかについてもお聞かせいただきたいと思います。その点をお願いします。","respondent":"築山障害者施策推進担当課長","answer":"１点目の基礎調査報告書につきましては、概要版を分かりやすいようにまとめましたので、そちらを用いたいと考えています。それから傍聴につきましては、先ほどもご説明させていただいたとおり、新型コロナウイルス感染症の状況を見ながら判断をさせていただきたいと考えています。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここのところでもかなり、自立支援協議会でも関心が高くて、いつもすごいたくさん、１０人以上の方が傍聴されていると思うのですけれども、多分計画策定のところも、自分たちのことですので、当事者の方も、それからご家族の方も、かなり関心を持っているので、十数名の傍聴希望者がぜひ入れるような形でお願いしたいというようなことでも書かれているのですが、そのような方向でぜひ。","respondent":"築山障害者施策推進担当課長","answer":"傍聴につきましては、受入れが可能かどうかも含めて、状況を見つつ判断をしたいと考えています。それから厚生労働省から出ております基本的な指針等は、委員が正式に決定いたしましたら、資料を事前送付する予定でおります。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"前の自立支援協議会のときも非公開になっていて、公開してほしいというところが当事者から何度も上がって公開になったというような経過があったと思うのですけれども、計画策定というのは、前は自立支援協議会で兼ねてやっていましたので、皆さんも傍聴できたと思うのですが、今回は計画策定委員会が別に作られるということですので、公開はぜひしていただきたい。その点だけ確認をお願いします。","respondent":"築山障害者施策推進担当課長","answer":"基本的には公開をするということで考えているのですけれども、新型コロナウイルス感染症の状況がありますので、そちらを踏まえて判断をしたいと考えています。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出して、不採択でお願いいたします。理由は両計画に関して、陳情の趣旨である早期開催に向けて準備を進めてくださいという、この理由について先ほど説明があり、全て粛々と進んでいるということが確認できましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"おくの委員","kind":"意見","question":"本日結論を出すで、採択でお願いします。傍聴に向けた公開の点や、それから十分な審議のために資料を事前に送るという点など、充実した審議のための充実した準備を進めてくださいという内容に非常に酌むべきものがあると思います。大事な陳情だと思います。採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"確認","question":"本日結論を出す、不採択でお願いします。ご説明いただいたとおり、年度当初の予定の形で進んでいるというご説明がありました。やや遅れてはいるということですが、予定どおりということが確認できましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-05","title":"令和２年陳情第３１号、「医療的ケア児等支援体制協議会」の委員委嘱に関する陳情","agenda":"令和２年陳情第３１号、「医療的ケア児等支援体制協議会」の委員委嘱に関する陳情","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この方はもちろん品川区の施設の方ですので、総合支援施設がこれから医療的ケア児者も受け入れていくということはずっと言われていて、児童学園ですから医療的ケア児ですけれども、医療的ケア児も受け入れていくことにこれからなっていくという方向は区としても出されていると思うのですが、そのような点では品川児童学園の施設長はなぜ入らないのかというような思いがするのです。","respondent":"松山障害者福祉課長","answer":"城南特別支援学校の教育コーディネーターやＰＴＡの方々のお名前も挙がっておりましたけれども、城南特別支援学校の代表として校長先生に出席を頂いております。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川児童学園のところがどうなのかということと、やはりこのような形で自立支援協議会に正式に出されたわけですので、これが変わるというところであれば、変わる理由というものがはっきりと必要かなという思いで陳情者の方も出されているので、お聞きしているのですけれども、品川児童学園も医療的ケア児をこれから受け入れていくよう進めていくということだと、総合支援施設の中ですから。","respondent":"松山障害者福祉課長","answer":"それから平成３０年度と委員構成が変わる理由なのですが、先ほども説明いたしましたけれども、当時と比べまして、医療的ケアが必要な障害児の受入れを行う事業所や学校が区内に増えたためです。","id":"exchange-050"},{"speaker":"渡部委員","kind":"意見","question":"本日結論を出して、不採択でお願いします。当時と状況が変わって、このような形でという中で、当事者の方々も入ったりということなので、会自体問題ないというように考えます。不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出すで、不採択でお願いします。陳情の趣旨のところについては先ほど説明があり、確認ができましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"おくの委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いいたします。実質的に充実した審議を求める趣旨、ならびに早急にそれをお願いしたいという体制を求める陳情ですので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本日結論を出すということで、不採択とさせていただきたいと思います。ただ、先ほど城南特別支援学校の校長先生が代表だということですので、校長先生から教育コーディネーターやＰＴＡの方々に、城南特別支援学校全体のご意見をこの準備会や、その後の連絡会で伺うような確認をしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"}]},{"id":"topic-06","title":"議案審査を再度行います。 (2)第３９号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"議案審査を再度行います。 (2)第３９号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"減額の補正ということで、積極的な質問というのもなかなか難しいのですが、一応聞きます。感染症予防費で、先ほど職員に対するワクチン接種ということでご説明があったのですけれども、これはいわゆる保健師さんなのか、全職員ということなのか。それからオリンピック・パラリンピックに関して何のワクチンを何種類ぐらい受ける予定だったのか。来年にもかかる話なので、確認をさせていただければと思います。","respondent":"鷹箸保健予防課長","answer":"こちらの経費は髄膜炎菌ワクチン、１人に対して２万２,３５２円かかるところの１０人分約２２万３,０００円ということで、対象は医師、保健師を想定して、計上させていただいたものになります。減額されたものはそれとなります。","id":"exchange-055"},{"speaker":"渡部委員","kind":"質問","question":"食品衛生のところで１つだけお伺いします。ということは、潮風公園や大井ふ頭の中央海浜公園は品川区内だから、そこで何かの販売や出店などをやるときは、直接品川区保健所がその管理をするというようなイメージでよろしいですか。","respondent":"鈴木（誠）生活衛生課長","answer":"ご質問のとおり、区内にあるオリンピック・パラリンピックの会場における食品提供の施設に関して、監視をするものです。","id":"exchange-056"},{"speaker":"おくの委員","kind":"質問","question":"それからこのホテルの図面を見ますと、２０m2、３０m2のところにぎっしり詰め込む形になっているのです。ベッドですから雑魚寝とは言わないですけれども、２０m2、３０m2のところに３人、５人と詰め込むような状態のわけです。例えば、見えるかどうか分からないですけれども、バス、トイレがあって３８m2です。この辺いかがなのか、どう考えているのかと、ちょっと伺いたいと思います。","respondent":"鈴木（誠）生活衛生課長","answer":"午前１０時から午後６時まではスタッフがいるということで、ここの陳情でもご指摘のありますガイドラインの具体的な項目ですが、何項目かありますけれども、例えばエレベーターの頻繁な消毒であったり、換気の要請。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"今のご説明からは、ガイドラインが十分守られるというお話にはならないと思うのですけれども、無症状感染者がいる可能性があることを踏まえて感染防止策を取るということが、やはりできないのではないですか。今の説明からはこのガイドラインを守っている、感染防止策がきちんと取られているということには全然ならない、全く納得できないのですけれども、いかがでしょうか。","respondent":"鈴木（誠）生活衛生課長","answer":"ご指摘のあったガイドライン自体は、ホテル旅館業の業界団体が作ったものですが、厚生労働省から詳細について出されたものが基になっているものですので、国の考え方からいって、今のご指摘のような、即危険な状態であるというふうには考えておりません。","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問","question":"やはり納得できる説明にはなっていないと思います。それから、このような狭いところに雑魚寝状態で詰め込む、あるいはそうでないにしても、このようなものを仮に認めたとしたら、新型コロナウイルス感染症のクラスターが発生しないようにするためにも、そのような接触感染のリスク評価や飛沫感染のリスク評価、これを区としても独自に行うべきではないですか。どうでしょう。","respondent":"鈴木（誠）生活衛生課長","answer":"これに沿って実際の対策を取っていただくということが法に則った仕組みですので、区のほうで独自に規制をかけたり、また特別な、このホテルに関しての検査をするような予定はございません。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"いや、独自にガイドラインをかけろとか、そのようなことではなくて、ガイドラインとしては非常に詳細なものが出ているわけですから、これを十分に守ればいいのだと思います。だから、このガイドラインに添えるかどうか、そのような新しい観点から考えて、区の制度も運営ができる制度への改善を求めるということをこのようにして労力を払われて、わざわざ陳情されているのだと思います。","respondent":"鈴木（誠）生活衛生課長","answer":"それに伴って、事業者は国やこのガイドラインに沿った対応をして、保健所にも連絡するですので、ホテルのもともとの設置の機能上、常に有人ではなくても事業者とは連絡が取れる状態ですので。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問","question":"常に事業者と連絡が取れる状態というのはどのようなことですか。","respondent":"鈴木（誠）生活衛生課長","answer":"事業者は無人になる時間帯があることを前提でチェックインから、また通常の管理もしておりますので、当然緊急時の連絡先、事業者の窓口に対応できる連絡先も周知をされておりますし、携帯電話等で連絡を取れば連絡はすぐつくということで考えております。","id":"exchange-061"},{"speaker":"おくの委員","kind":"質問","question":"しかし管理者がいないと、適切な連絡が保証されないわけでしょう。いかがでしょうか。","respondent":"鈴木（誠）生活衛生課長","answer":"これは管理人の有無ではなくて、チェックインの時等にしっかりとお話をしていただき、その情報を把握するということで対応すればよいものであって、２４時間常駐とは関係ないというふうに考えております。","id":"exchange-062"},{"speaker":"おくの委員","kind":"質問","question":"ですから、そのリスクを宿泊者なり、場合によっては周りの住民に負わせることになってしまうわけです。事業者が第一に責任を負うのではなくて、宿泊者が第一の責任を負う。そのようなことになるのですけれども、その点、やはり厚生労働省の通知なり、ガイドラインが十分に守られないということになるのではないでしょうか。","respondent":"鈴木（誠）生活衛生課長","answer":"国の制度です。このことをもって制度を変えるということは困難であるというふうに考えております。","id":"exchange-063"},{"speaker":"おくの委員","kind":"質問・要望","question":"区にはやはり住民の命や暮らしを守る責任はあるわけで、そのような要望が出ているわけですから、このような住民の命、暮らしを守っていく責任は十分にあるのではないでしょうか。伺います。","respondent":"鈴木（誠）生活衛生課長","answer":"事業者の方が責任を持って守るというようにおっしゃっていたので、そのことについてお答えしましたが、行政についてはご指摘のとおり、住民の方の意見を聞いて暮らしを守るという責務を持っているというふうに認識しております。","id":"exchange-064"},{"speaker":"おくの委員","kind":"質問","question":"ですので、事業者の常駐者を置かないというこのような態度を、特にコロナ以後にこのまま見過ごしておいては、そのような住民の命、暮らしを守るという責任を果たすことはできないのではないですかというふうにお伺いしているわけです。それで、このガイドラインや厚生労働省の通知を守ることができないのだということは、私にとっては非常に明らかなことではないかと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"渡部委員","kind":"確認","question":"あくまでもこれ自身はまだ動き出していないのですよね。ですから、それを今机上の空論でどうこうという話では全くなくて、やはり旅館業法があって、なおかつ先ほどから説明のある２月のガイドライン、これは宿泊業をなさる方が独自で、しっかりやっていきましょうねというものを作って、当然それはお客さんが入る段階から進めていくものであって、できるできないは私たちの判断ではない。","respondent":"鈴木（誠）生活衛生課長","answer":"ご質問いただきました、事業者へ区民の方の意見や要望を伝えたり、または区としてのできる範囲の指導ですが、先ほど申し上げましたように、昨年の委員会に前後して５回の説明会を開催してもらったのも区から指導した結果です。","id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですからそのような中で、要望として伝えるのであれば、これからも話の中でしっかりと地域の方々からの声がまた出ていますよというところ、開いていないですから。それで旅館業務のガイドラインは、これは当然独自の、自分たちの団体で作られたことですから守るのです。私たちは警察ではないですから、それは守ってしっかりやっていただくということでお伝えをしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"あくつ委員","kind":"確認","question":"ちょっと質問が前後してしまって申し訳ないのですが、先ほどのご説明の中で、予定では今週に保健所が立入りをして、これは許可になるのですか、されるというお話でしたけれども、行政手続法なのか、それともいわゆる要綱等に定めがあるのか、もしそれが適正であればいつぐらいに許可が下りる予定なのか、というところを１点確認したいということと、私も厚生委員会、今回久しぶりなので以前不採択になった。","respondent":"鈴木（誠）生活衛生課長","answer":"それから２点目の、法の範囲内で条例を定めながら、その中でいろいろな指導等を行っていくということに関しては、今後も保健所としてはしっかりと、特に今皆様から意見がありますように、新型コロナウイルス感染症の対応のほうも重ねてお願い、指導しなければなりませんので。","id":"exchange-068"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それからもう一つはこのガイドライン、私も本当に細かいところまで、すごい具体的なところまで書かれていると思ったのですけれども、このガイドラインを本当に守れるかどうか、守れるホテルなのかどうなのかということを区がチェックすることが必要だと思うのですが、ガイドラインに沿ってどうなのかということや。","respondent":"鈴木（誠）生活衛生課長","answer":"去年の陳情の頃から、新型コロナウイルス感染症が発生して状況が変わって、対応が変わるのではないか、変わるということについて区の認識はということですが、当然区、保健所が先頭に立って住民の方にいろいろお知らせをしたり、対応したりしておりますので。","id":"exchange-069"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"保健所ですから、やはり新型コロナウイルス感染症の感染をいかに抑えるか、第２波、第３波、これをいかに抑えるかという部署なわけです。そのようなことだったりとか、いろいろなところで２ｍを目安に距離を取れるようにしろということで書かれているのですけれども、ベッドの距離はとても２ｍ空けられない状況ではないかと思うのです。","respondent":"鈴木（誠）生活衛生課長","answer":"それとガイドラインのほうの、これを守れる施設になるかどうかというご質問ですが、このガイドラインはホテルの施設の基準等を定めるものではなくて、清掃や、声かけ、注意だったり、具体的な業務の内容の部分ですので。","id":"exchange-070"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"距離を２ｍを目安にできるだけ保つ、それから人と人とが対面する場所はアクリル板や透明ビニールカーテンなどで飛沫感染を防止するなど、そのようなところも出てきているのですけれど、このようなところも私はチェックが必要ではないかと思うのですが、そのようなことは保健所では、新型コロナウイルス感染症がこれだけの大問題になっている中で、ガイドラインについては施設としてチェックされないという。","respondent":"鈴木（誠）生活衛生課長","answer":"ただし、近隣の方への配慮や、それから衛生面の確保に関連する指導については、引き続き区と保健所として行っていますので、その中でこのガイドラインについてもお声かけをして、徹底を指導するということになるというふうに考えております。","id":"exchange-071"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、このガイドラインに沿って、保健所という立場で指導するということになるわけですよね。そうすると、このガイドラインが守られた施設にするというようなことにも当然なっていくのではないですか。どちらも。それは両方ともクリアしていくということが大事なのではないかと思うのですけれども、そこのところはどうなのでしょうか。","respondent":"鈴木（誠）生活衛生課長","answer":"先ほどから申し上げていますように、権限に基づく指導と、それから新型コロナウイルス感染症対策の上で必要な指導というのはものが違いますが、保健所としては、おっしゃるとおり１つの組織として、区民の安全や衛生を守る上で両方指導していくというように申し上げております。","id":"exchange-072"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そうすると、例えば３４m2に４人や３８m2に５人などというようなことは、このガイドラインからはみ出してしまうように思うのですけれども、その点はどうでしょうか。","respondent":"鈴木（誠）生活衛生課長","answer":"それと同室の中で感染の可能性が高くなるわけですが、基本的には通常宿泊の場合、家族もしくは知り合いの方が同室ということになりまして、ガイドラインの中でも、もし家族以外の方と同室で泊まる場合にはその同意を取ることや、注意事項を伝えるということもありますので。","id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから本当にこのガイドラインをしっかりと守らせる。最低そこのところはぜひとも業者のほうにしっかりと働きかけて、ここで新型コロナウイルス感染症のクラスターになるようなことになったら、地域の人だって本当に安心できないということになりますので、そこのところはぜひとも、このガイドラインと２４時間常駐というところは区としてもぜひ事業者にご指導いただきたいと思うのですが、最後お願いします。","respondent":"鈴木（誠）生活衛生課長","answer":"ただし、ご指摘のあった２点については、法制度、それから区の行政の権限などから考えて、対応はできないというふうに考えております。","id":"exchange-074"},{"speaker":"渡部委員","kind":"質問","question":"継続でお願いします。前回９月にやり取りがあって継続にして、地域の方のお声があるからということで、先ほどご説明もありましたけれども、区のほうは区としてできること、当然民間に対してですから、区としてできることをしっかりやってくださっているわけです。それはそれ、これはこれ。ですから区としてできることは、これからもまた続けていただけるということですので、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"継続でお願いしたいと思います。そのような意味で、ただ、先ほど渡部委員からもあったように、法律以上の上乗せ条例は、これははっきり言って憲法違反になってしまいますから、できないということ、これは間違いないことなので、ということまでを前回、この令和元年９月の陳情については求めているものではないので、継続とさせていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問・要望","question":"これは非常に住民の皆さんの一致した要望です。皆さんご存じでしょうけれども、地元の町会長さん１０名も賛成なさっていますし、保育園の方々４６名からも署名いただいているというように、３００名近くの方から署名をいただいているということも聞いていますので、地元の方々の一致した要望でもあります。常駐者を置いてきちんとやっていく、運営していくという要望はもう当然のことだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本日結論を出すということで、令和元年９月の陳情第３５号、令和２年陳情第２９号ともに継続にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"失礼しました。では令和元年陳情第３５号のほうで、継続ということでお願いします。今いろいろ議論がありましたけれども、行政のほうで国の法律、そして区の条例、それからガイドラインが出ていますので、その中でまだ開業までということがあるので、その開業までに、今までも指導していただきましたけれども、十分な指導をしていくという状況の中で、この審議に関しては継続していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"西村委員","kind":"意見","question":"本件に関しましても継続でお願いしたいと考えています。引き続き区民の方のご不安にならないようにしたく、継続でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど途中まで話しましたが、今回のこの陳情項目、制度への改善を求めますというところで、先ほども述べましたが、これが条例改正、上乗せ条例を作れというようなものであれば、これは残念ながら願意に沿い難いとは思うのですけれども、制度への改善を求めるという中で区民の方たちの不安も分かりますので、そのような意味で、先ほど保健所のこれからの方針をお伺いしたところ、公衆衛生に関しては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"継続でお願いしたいと思います。先ほどの区の行政ができる範囲の中での役割というものは大変重要だと思いますので、そちらの状況を今後続けていただくという観点で、継続にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"}]},{"id":"topic-07","title":"令和２年陳情第２７号、不要不急の「特定整備路線事業計画」を中止しその財源を新型コロナウイルス対策に活用するよう東京都に要請を求める陳情","agenda":"令和２年陳情第２７号、不要不急の「特定整備路線事業計画」を中止しその財源を新型コロナウイルス対策に活用するよう東京都に要請を求める陳情","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"すみません。そういって市街地再開発や街路整備などが挙げられているわけです。当然都市計画道路、特定整備路線は、この街路整備にあたるのではないかと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"おくの委員","kind":"質問","question":"それからもう一つ、医療・福祉施設、あと教育に関わる仕事の従事者にはＰＣＲ検査を定期的に実施してほしいという趣旨だと思うのですけれども、今は実施していないというご説明だったと思います。このような提言に対する区のご見解をお伺いしたいと思います。提言されているわけです。こういった専門家会議や１８道県知事の緊急提言といったものに対する区のご見解をお伺いしたいと思います。","respondent":"鷹箸保健予防課長、鈴木（博）委員長","answer":"当初は武漢から帰国された方、あるいは武漢から帰国して症状がある方と接触した方、加えて３７度５分以上、４日間と非常に狭い対象の方しかＰＣＲ検査の対象としないという方針があったところですけれども。おくの委員、明日の報告事項の７番目に新型コロナウイルス感染症に係る保健所・保健センターの対応についてということでレジュメも配られて、また詳しく論議することになると思うので。","id":"exchange-084"},{"speaker":"おくの委員","kind":"質問・要望","question":"私としてはやっていただきたいと思います。そのための財源として、不要不急の事業を取りやめてでも、そのようなところに回していくことは非常に大事だと思いますので、この陳情の提言は非常に大事だと私としては思っております。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからあと、ここにあります医療・介護施設や保育など、この現場に働く方々というのは、自分が実際に感染したらどうしようというような思いと、もしも自分が無症状で感染していて、またそこから感染をさせたらどうしようという、そのような不安な思いで日々仕事をされているというようなことを、現場の看護師さんだったり、保育士さんだったり、障害者施設で働く方々から伺ってきたのです。","respondent":"鷹箸保健予防課長","answer":"例えば抗原検査ですと割合数時間で結果が出るところですが、今実施しているＰＣＲ検査は、ＰＣＲ検査センターでも早くて翌日に検査結果が出るというような形で、あくまでもそれはその検査をしたときだけですので、検査をして安心というようにならないところが。","id":"exchange-086"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"本当に大きく変わってきたなという思いはしていますけれども、今度唾液でもＰＣＲ検査が可能になって、発症９日目とか、そのような起点というのもあるのですか、そのようなことで、唾液の検査というのもＰＣＲ検査でやるとすると、先ほどの課長のお話だと、これから医療機関でもできるようになるのではないかというようなことでご説明あったと思うのですが、今のＰＣＲ検査センターや帰国者・接触者外来など。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/334734?Template=document&Id=3570#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":58993,"voices":268}},{"id":"r02-20200629-8","meetingId":"r02-cm06","date":"2020年6月29日","dateIso":"2020-06-29","committee":"建設委員会","time":"午前１０時００分～午後 ３時２０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を120件抜き出しています。","topics":[{"id":"topic-01","title":"第３９号議案、令和２年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第３９号議案、令和２年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"なぜこの補正予算にそういった減額が含まれていないのか、伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"私が聞いたのは、この補正予算の中に不要不急の開発の見直し、減額というのが入ってくるべきではないかということで聞いたのです。補正予算の審議ですから、本来含まれているはずのものが含まれていないということの審議もやはり必要だと思いますので、なぜ含まれていないのか、ご答弁をいただきたいと思います。","respondent":"中村都市環境部長","answer":"こちらのほうは、区主導の、あるいは区主催のイベント、あるいは事業ということではなくて、民間の発意によって進めている事業でございまして、コロナ禍の中での進捗状況と民間事業に対する影響、この辺を踏まえた総合的な判断の中でこういった結論になったです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"住民の声を聞くというのは当然大事なことですが、こうした新型コロナウイルスの影響ですとかは、区が全体像を把握しておりますので、区の判断が必要なのではないかと思いますが、いかがでしょうかということで、そうしたことでやはり新型コロナウイルスの……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"私はこの補正予算に関わって重要なことだと思っているので質問しているのですが、簡潔にということですので、やはり開発事業の減額を行って、不要不急のものを減額して、新型コロナウイルスで苦しんでいる区民の皆さんに使っていくべきではないかと思います。最後に伺います。","respondent":"中村都市環境部長","answer":"これは民間事業の経済活動、こういったものをどの程度まで抑制するかというところの中では、やはりコロナ禍の中でも進んでいる経済活動というのはありますので、その辺を判断しての結果です。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"減額部分なのですが、中止になった分がということでの説明は分かりました。それから減額になったこの予算というのは、今後どういう扱いになってくるのか。来年は来年の予算立てになると思うのですけれども、今年の予算の立てたものについては、どういうところに入っていてどういうところに。転用ができるのかどうかも含めて教えていただきたいと思います。","respondent":"堤坂環境課長","answer":"今後の取り扱いということで、来年度のＥＣＯフェスティバルについてはまだどういう形になるかというのは、新型コロナウイルス感染症の動向をまだ見極められない部分ではありますけれども、今世間では新しい生活様式の形が少しずつ整いつつあるということで。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"転用とかできるのでしょうか。これは環境費のほうと、それから道路橋梁費のところもお聞きしたいのですけれども、一応“今年はありませんよ”と感覚的に言うと使わなくて済んだお金というふうに捉えるのですが、そのお金は結局かからなかったというところで、どういうお金の動きになってくるのか。","respondent":"鈴木都市計画課長","answer":"ただ、これは所管は違いますが、今全庁的にコロナの関係で事業の見直し、洗い出し等をやっていますから、その全庁の枠の中で予算をどう使っていくのかというのは、都市環境部あるいは防災まちづくり部ではない所管のほうで検討されていくのだという認識です。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"もちろん不用額になった場合に、全庁的にどう考えていくかというのは、これは企画部とかそちらのほうになると思うのです。土木関係は結構大きなお金が動く可能性もあるものですから、そうなるとほかのところで助かるみたいな状況があると思うのです。そういう考え方は、本来はここだけではないと思うのです。でも、そういう考え方はどうなのか、お聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"したがいまして、本当に部ごとで目の前のコロナ対応に対応しなければいけない場合というのは、原予算を補正で落とさずに使うかどうかというのは、その状況にもよるとは思うのですが、基本的には全庁的に緊急に。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"そうならば、自分たちが担当しているところが果たしてどうなのだ、本当に急に今年必要なものなのか、来年度に回してもいいのではないかとかというのは、ある程度整理をしながら全庁的に検討していくという話になってくると思うのです。だから、“全庁的にやりますよ”ではなくて。全庁的に動けるときにはぱっと動くという形にぜひしていただきたいと思います。これは意見ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"若林委員","kind":"確認","question":"今、不用額というお話が出まして、確認というか。会計上は議決を経て不用額になると。そうすると、そのお金の、不用額の取り扱いは、私の理解で言うと、いわゆる企画部の財政課のほうでお財布に入るというか、そこでまた今の意見も含めて差配をすると、そういう理解でいるのですけれども。ここで聞いて、はいとか、いいえとかと言う問題かどうか分かりませんけれども、確認できればお願いいたします。","respondent":"鈴木都市計画課長","answer":"第２回定例会で上程させていただいた減額については、委員ご指摘のとおり不用額という形で、その後の取り扱いについては、基本的にはご指摘いただいたとおり全庁的に財政課のほうで総括して判断をしていくという認識でおります。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"意見","question":"基本的に賛成なのですが、今の議論でこれからこういう不用額で、多分これは予備費に入ってもう一回その使い道を今年度中は考えていく。だけれども、今、３分の１とかいう基準で会場もオープンしたりして、密とはどういうふうにやるのだとか。これがすべて変わるような気がしてならないですね。会場も含めて何も。そうすると、皆さんがこれからどういうふうにしていくかというのが非常に問われる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"若林委員","kind":"確認","question":"先ほど確認もさせていただきました。賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"のだて委員","kind":"意見","question":"先ほども言いましたけれども、含まれるべき不要不急の再開発の減額というのがありませんが、今回は中止・延期となっているものを減額するということですので、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"賛成です。先ほども言いましたけれども、いろいろご意見が出ていますが、やはり事業の見直しというのはしっかりとしなければならない。この委員会は一番直接的な関わりがあるところだと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-02","title":"羽田新経路の固定化回避に係る技術的方策検討会の開催","agenda":"羽田新経路の固定化回避に係る技術的方策検討会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"検討会について伺います。今回この羽田新経路の固定化回避に係る技術的方策検討会ということで設置をされるということですけれども、区はどういった説明を受けているのか。スケジュール感ですとか期間、どのくらいやっていくとか、またこの検討の中に新ルートの変更も入っているのか、こういったことの国から説明をされていることや、ご存じのことがあればご説明ください。","respondent":"鈴木都市計画課長","answer":"令和２年６月１６日、このプレス資料にありますように、国土交通大臣が会見によってこの検討会の開催を公表したわけですが、それに先立ちまして、東京都の連絡会のほうでこの中身についての説明がございました。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"区も都の連絡会等でこの説明を受けていたということですが、この検討の中で、ルート変更も羽田新ルートの変更も入っているという区の認識でよいかという確認と、そういう認識をもっているのでしたら、ぜひ区として羽田新ルートの中止を求めていただきたいと思うのですけれども、いかがでしょうか。区としても公開にするよう求めていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"１点目のこの検討会の中で新ルートの変更もあり得るのかというご質問ですが、国は事前の東京都の連絡会の中でも、“そうした具体的な中身についてはこれからです”というところで回答してございません。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"この検討の中身ですね。ぜひ区としても中止を求めるということで要望をしていただきたいと思いますけれども、この検討が今年度デメリット・メリットを整理していくということで、その後、また次の年にどういう技術的検討ができるのかということになっていくのか。このスパンによって今年度は開催をしていくわけですから、中止にはしないということになっていくわけですね。","respondent":"鈴木都市計画課長","answer":"国のほうは、先ほどご説明しましたように、今年度中にということで、技術的選択肢についてその方策のメリット・デメリットを整理するということでございまして、５月２０日に区長が国土交通省に出向いて、国土交通大臣宛ての要望の中で。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"減便でも運用強行になぜ品川区は抗議をしないのか、伺いたいと思います。先ほどのご答弁でも、国策だから中止に賛成・反対ということは言わない、態度を明らかにしないということですが、今回の一般質問で国策になぜ中止を求めないのかという問いに区はまともに答えず、一定理解をしていると繰り返しました。伺います。","respondent":"鈴木都市計画課長","answer":"５月２０日の区の要望の中にも、そうした区民の声を添えて、このコロナに対する対応、減便の中での騒音軽減策について、区長が国のほうに文書、あるいは口頭でもって求めてきたです。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回の５月２０日の区長の要望にもそこが入っていないというのが一番のポイントなのです。やはりそこを求めていくということが、区民への希望にもなりますし、そして区としても区民の暮らしを守っていく、安心・安全を守っていくということでも必要なことだと思いますが、いかがでしょう。","respondent":"鈴木都市計画課長","answer":"そうした観点で、ただ区民の不安の声というのは日々区に届いているものでございまして、それは騒音あるいは落下物に対する不安、この不安の払拭に向けて、区としては、周辺関係自治体ともそうですが、一体となって国にその対策を求めてきている。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"不安払拭のためということでおっしゃるのなら、やはりこの羽田新ルート中止を求めるとして、海上ルートに変えることが一番の安全対策だと思いますけれども、そう思わないのか。国策だと中止を求めない。しかし、この被害を受ける当該自治体、品川区として、意見をしっかりと伝えていく、中止を求めていくということが必要だと思いますので、そういったことも求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"なおかつ、コロナの減便で増便のための羽田新ルートというのは必要ありませんので、ぜひ区としても中止を求めていただきたいと思います。次に、令和元年陳情第１７号、第３４号、令和２年陳情第１９号、第２５号については、住民に対して説明会を開いてほしいというものです。実機飛行確認の結果や減便中でも実施したことなど、説明会の開催を区としても求めるべきですが、いかがでしょう。","respondent":"鈴木都市計画課長","answer":"今ご質問をいただいた、地域への、区民への説明ですが、区は本格運用開始前、決定開始前から教室型を含めた様々な地域への説明を求めてまいりました。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"説明会の開催を求めていますので、丁寧な説明というのが説明会ということでいいのか。ぜひ説明会を求めていただきたいと思いますし、特に教室型の開催を求めています。やはりほかの人の意見も聞きながら議論できる教室型の説明会を要望すべきだと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区民の方、お住まいの方への周知というのは様々なやり方があると思います。今委員にご指摘いただいた教室型説明会もその一つだと思います。それを含めて、それに限定することなく、様々な手法を活用して丁寧な説明を求めていくです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"周知方法は様々といいますが、教室型説明会が求められているわけですから、ぜひ区としても求めていただきたいと思いますし、住民の理解が得られないままにこの羽田新ルートの運用が強行されましたので、議会としても教室型説明会の開催を求めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"検討会の開催について伺いたいのですけれども。議題に関して第２項目で、「固定化回避に向けた技術的検討の進め方についてなど」とあるのですけれども、この「など」についてご説明があったのか、「など」の中身を教えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"国からの事前のご説明では、この資料にあるとおりでございまして、「など」の中身について、こちらからも質問をしましたけれども、その中身について具体的な、この資料にある以上のものは回答としてはございませんでした。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"「など」の中身も、この資料以上のものはなかったということなのですけれども、その姿勢からもう既に。一番被害が多い品川区という自治体として、もっとより説明がされるべきだと思うのです。そこについて区として“もっときちんと説明をしてください”と求めることはなかったのですか。","respondent":"鈴木都市計画課長","answer":"開催は明日ですが、その具体的な中身についてもいろいろ国のほうで調整を行っている中でのこの資料、プレス発表ですから、これは会が実施された後の公開される資料についてしっかり注視して、内容は問い合わせ、あるいは求めていきたいです。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"いろいろな場面で求めてそれぞれ様々な要望をしているということだったのですけれども、今こうやってたくさんの請願・陳情が区民の方たちからも届けられていて、それ以外にも電話などでも問合わせが殺到しているという状況の中で、なぜ区としてもっと追及できないのかということと、非公開についてもなぜ非公開なのかということももっと強く言えると思うのです。","respondent":"鈴木都市計画課長","answer":"質問が、このプレス資料の「進め方についてなど」の「など」の中身についてもっと詳しく聞かないのかですから、この中身については、４の今後のスケジュールにもありますが、基本的に会が向かう方向としては、「固定化回避に向けて考えられる技術的選択肢」ということで。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、ぜひ逐語録というのですか、言葉がすべて載るような、品川区の議事録のような形にしてもらうように要望していただきたいと思うのですが、いかがでしょうか。スケジュールなのですけれども、この１回で終わってしまうのか、それとも年内に何度か、日程とかももう決まっているのかという、スケジュールについてもお知らせください。","respondent":"鈴木都市計画課長","answer":"この会の開催の予定ですが、今のところ国から聞いているのは、明日６月３０日に１回目が開かれるということですが、この議題にもありますように、「設置について」と「進め方について」ですから、これ１回で終わるという認識はございません。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"スケジュールなのですけれども、大体１か月に１回行われるとか、そういったこととかも報告はなかったのでしょうか。","respondent":"鈴木都市計画課長","answer":"どれぐらいの頻度というところも含めて、今後の開催回数については説明はございませんでした。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"検討会が実施されてから、その議事要旨を確認してから、あまりにも中身がひどかったらもっと中身が分かるように伝えるとか、スケジュールもまだ分からないとか、こんなに分からないことだらけで。一番被害を受けている自治体として、区民の声もたくさん上がってきている自治体として、もっと踏み込んでいいのではないかと思うのですけれども、その姿勢というのは変わらないのですか。","respondent":"鈴木都市計画課長","answer":"これは国のほうで大臣の指示のもと、今月末急遽立ち上がったという区としての認識ですので、今後この会で全体的な検討のスケジュールですとかが示されるのかどうか、そこも含めて、その状況を見て必要な要望をしていきたいです。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"何か月も開催されなかったら求めていくということだったのですけれども、今困っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"区として求めてほしいという趣旨で話しています。開催についても、スケジュール感についても、とにかく情報が少な過ぎるので、当該自治体としてもっと求めてほしいということで今求めているのですけれども。自治体として今これだけ大きな声が届いている状況の中で、何か月も開催されなかったら求めていくという姿勢では絶対に良くないと思うのです。そこに関して考え方をご説明いただければと思います。","respondent":"鈴木都市計画課長","answer":"国の説明が当初の説明と違ってきているですが、これは実機飛行確認、それから３月２９日の本格運用開始以降、特に騒音の結果については、国は公表するとは言っていますが、まだ公表されていないところもございまして、その結果が従前の予測値とどうだったかというのは。","id":"exchange-030"},{"speaker":"田中委員","kind":"意見","question":"羽田新ルートの目的が、最初は経済でしたよね。それが今回コロナの影響で減便などがされて、今回は都市部での騒音の共有といった新しい文言が出てきました。その国の説明の中で、そういった新しい文言が出てきたことに関して、羽田新ルートの目的が変わってきていると思うのですけれども、そこに関して区はどのように考えていますか。","respondent":"鈴木都市計画課長","answer":"そういう認識はあったものの、今委員にご指摘いただいたように、目的としましては、これまで説明を受けていたのは、やはり機能強化、国際線の増便ですので、これは先の第２回定例会の一般質問でご答弁差し上げたとおり、国にしっかり説明を求めていきたいです。","id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"前回の建設委員会でもご説明があったとおり、今まで区民への説明会の中で、「騒音を首都圏全体として共有するという説明はなかった」と課長もおっしゃっています。ないのです、なかったのです。新たな目的、目的が変わってきているので、これの国の区民に対する説明は必要だと思うのですが、そのところ。","respondent":"鈴木都市計画課長","answer":"私が都市計画課長に就く以前のオープンハウス型の説明会は存じ上げていないところはありますが、就任してからのオープンハウス型説明会、その後の区内１３地域での教室型説明会、冒頭の国の説明の中で、首都圏全体での騒音の共有化という説明はなかったと記憶しています。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ教室型の説明会を求めてほしいと思います。請願・陳情にあるように、やはり区としてもこの羽田新ルートにはぜひ、少なくとも今は必要がないといったことを、そういう立場に立ってほしいと思うのですが、そのことに関していかがでしょうか。","respondent":"鈴木都市計画課長","answer":"しかしながら、落下物ですとか、騒音環境の軽減ですとか、丁寧な説明については、委員ご指摘のとおり区としてしっかり求めていきたいです。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"これだけの声が上がっている中で、要望書でもこういった趣旨、例えば要望書の中には固定化しないという文言が、上空を飛ばさないという意味を含めてといったことだったりとか、明確に示さずに、趣旨としてというふうに要望書で出しているではないですか。では、まずそこで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"現在、このような声がいっぱい上がってきているわけではないですか。いつ区として態度を示すのかということをお知らせいただけますか。","respondent":"鈴木都市計画課長","answer":"いつ区としての立場をというところでございましたが、繰り返しになりますが、決定前、決定後も、一貫してこれは区として求めるべきことは、落下物、騒音環境の軽減、それから丁寧な説明を求めていく、固定化しない取り組みを求めていくというところは変わらないです。","id":"exchange-035"},{"speaker":"田中委員","kind":"意見","question":"私が、品川・生活者ネットワークが言っている責任放棄の意味は、品川区として、自治体として区民の声を届ける、区民の命、生活を守るといった意味での責任放棄が今されているのではないかということを言っています。そのことについて。","respondent":"鈴木都市計画課長","answer":"区民の不安、落下物に対する危険性、それから日々上空を通ることによって起こる飛行騒音、この軽減については、区としてもしっかり求めてきているし、これからも求めていくです。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"固定化ということは、前提として、首都圏上空を、東京都上空ありきで固定化しないということを考えているのですか。どういう連携をとろうとしているのでしょうか。この令和２年陳情第２８号の中で、大田区長と川崎市長が連名で提出している要望書があるということで、この内容が品川区と同じ趣旨のものが入っているのか、全く分からないものなのか、その２点目をお聞きします。とりあえず３つお願いします。","respondent":"鈴木都市計画課長","answer":"３点ご質問いただきました。１点目の固定化の意味合いですが、先ほどもご答弁申し上げたとおり、現在新ルート計画が本格運用されて実施されているわけです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"この固定化という意味です。ないなんてあるわけないではないですか。そういった場合には、やはり毎回要望書を出すぐらいの気持ちで追及していかなければいけないことなのではないかと思っています。確認はやはりしていかなければいけないと思います。それが一つ。それを国へ届けていくという、これは大きな役目だと私は思いますので、その方法についてお考えをお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"固定化につきましては、当然ながら“品川区上空を外してほかの自治体の上を飛んでくださいね”ということではなくて、私どもは品川区民の不安払拭のために、この固定化に向けた取り組みを国に求めているわけですので。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"最後にします。意見も含めて、地域の状況を品川区自ら知ってほしいと思います。“毎日こうなのよ”ということもいっぱい聞いています。それを含めて国のほうに伝えていくという義務は私はあると思っているので、そういう窓口はきっちり品川区独自で作っていかなければならないだろうと考えていますが、地域の影響について、独自での情報収集ということについてのご意見を最後にお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"そうしたところの新設ポストをホームページあるいは広報しながわで周知をして、そうした声を、いかに多く区民の声を国にしっかり届けていけるかというところは、態勢を整えてしっかりやっていきたいです。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"先ほどの質疑の中で、今新型コロナウイルスで減便になっている、今でも必要ないという立場には立たないというお話でした。国策のため国が判断すべきだということでおっしゃっていましたけれども、つまりは国の言いなりという形になってしまうと思うのですが、こうした立場で区民の安全・安心、健康を守れるのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"このコロナ禍の中での減便に対応する騒音環境の低減の取り組みについては、５月２０日に区長が国に要望として求めたです。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"国の判断ということですが、やはり中止を求めるという立場に立つことが区民の安全・安心、健康を守るということに深くつながってくるということになると思います。むしろ中止を求めないということになると、容認をしているということにもなりますので、ぜひ中止を求める立場に立っていただいて、品川区民の安全・安心、健康を守っていくという立場に立っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどから国に対する働きかけや要望をしていかなければといった話があったと思うのですけれども、区としていつ頃だったりとか、どのような事態になったら要望を届けるのかといったところをお知らせいただきたいというのと、あと、羽田のことに関する電話とかを受ける窓口ができたではないですか。","respondent":"鈴木都市計画課長","answer":"幹事会のほうは東京都が幹事の自治体ということでございまして、東京都、国あるいは品川区と大田区を含めて、この会が閉会あるいは休止中という認識はなくて、恐らくこの会の目的が沖合移転、その後の羽田の跡地活用というところで議論されてありますから、その方向。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"働きかけとか要望についてです。私がいつ頃どのような事態になったら要望書を届けるのかと質問をしたのは、前回この建設委員会で示された要望書の形、ああいった要望書の形での要望がどのような事態になったら次に出されるのかというところを確認したいです。","respondent":"鈴木都市計画課長","answer":"他区との連携につきましては、連携することによってより効果的であれば、当然効果的な形で進めていきたいとは考えてありますが、本格運用が開始される前に各関係区市の要望というのが一覧で出てあります。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"一つ答弁漏れでした。窓口での電話などの集計の状況についてをお知らせくださいというのと、これまでの文書による要望や連絡会での発言録というのですか、そういう要望も公開してほしいということも求めたので、それについても伺えればと思います。","respondent":"鈴木都市計画課長","answer":"要望のタイミングですが、これはもう適時適切に間を置かずに継続してということなのですが、例えば、先ほどの検討会の中身について注視しながら、その中身で確認が必要、あるいは要望しなければいけないところは、その機を逃さず要望していくというような考えです。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"現状の件数は分かりました。そういったときにも、検討会の中身で足りないと思った部分に対する要望書とともに、これだけ区民の声が、もう今現在コロナの関係で減便している中で必要ないということと、そもそも都心の上空に飛ばすのはやめてほしいといった声があるということも要望書の中ではきちんと示してほしいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"コロナに伴う、これは中止して従前に戻してほしい等々の意見、これが１３件。それから国への苦情、窓口の対応が悪いとかそうしたところが６件。それと区の対応に関する意見・質問というところで、区としても中止を求めてほしい等々の意見が８件等の数です。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問・要望","question":"これまでの要望についてです。やはりこれだけ区民の関心があることですので、分かりやすく、今までこれだけ要望してきたということが分かるように公開をしていただきたいと思います。そういったように、きちんと区民の声が反映される要望書を作成していただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"５月２０日の区長要望の中にも区民の声は要望として添えさせていただきましたが、今後も基本的には区民にいただいた声をその要望の中に反映して、国のほうにしっかり求めていきたいです。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"前回の要望書の中には、区民の羽田新ルートの撤回を求める声ということの記述はなかったので、ぜひそういった声もあるということを次の要望書では記述してもらいたいと思います。いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"前回同様、区民の声についてはしっかり添えて、必要な要望をしていきたいです。","id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々品川区議会自民党、また自民党総支部は、まず初めには品川区議会の固定化をしないという全会一致の決議を前提に、運用開始前の３月２５日に品川区議会自民党、自民・無所属・子ども未来、また品川区議会公明党、この３会派で国土交通大臣宛ての要望書を作成し、もちろん面接をしてそれを提出してということでありますが、そのとき大臣に会えなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"大沢委員","kind":"質問・要望","question":"私どももこの９件については継続をお願いしたいと考えておりますが、理由についてはすべて共通しますので、あとも関係してまいりますが、冒頭に、令和２年請願第３号についての意見を述べさせていただきたいと思います。先ほど来、活発な質疑応答があります。この中で、行政側からは国策であるということ。この事業は国の責任において行うべきであるということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"これはまた整理をした上で、当然こういう物事には区も私たちも、区議会としても具体化を当然求めているわけですが、次の具体化に向けてのステップというものも当然視野に入れて、それも前提に区におかれましては引き続き、冒頭にもありましたけれども、具体的な方策が示されるように、区には力強く、強く求めていただきたいと要望して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"この質疑の中でも出てきましたけれども、中止・撤回を求めるということは区民の安心・安全を守るということにもなりますので、ぜひ賛成をしたいということで、なおかつ、コロナで減便になっている中ですから、なおさら増便のための羽田新ルートは必要ないと思いますので、採択をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"前回出された要望書の中にもあった固定化しないというのは、上空を飛ばさないという意味だということは区もおっしゃっていましたし、今お話があったとおり、多分皆さんも上空を飛ばさないという意味だと思うので、請願と陳情にもあるように、この羽田新ルート、都心飛行ルートの中止・撤回というのはまさにそのとおりだと思うので、それを反対する理由にはならないかと。採択したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、前回の委員会で申し上げたように、所管事務調査として羽田新ルートについては項目を立ててほしいと、これだけいろいろ変わってきているので集中的に建設委員会で取り組むべきだという主張をさせていただきました。ただ、令和元年の陳情と一括でやるのはどうかと思っている部分があります。令和元年の、既に１年以上経っているものをまた引き続きやっていく……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは教室型の説明会を開くということで、運用も始まっており、状況は変わっていますから、教室型説明会をやっていただきたいと。結論を出すということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"田中委員","kind":"意見","question":"結論を出すで、採択をしたいと思います。先ほどの質疑の中でもあったように、本来の目的と羽田新ルートの目的が変わってきているので、それだけでも区民に対する説明義務というのが出てくると思います。ぜひ開催してほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問","question":"本日結論を出すで、採択をしたいと思います。先ほども話したのですけれども、説明会に関しては、多分皆さんも説明を受けたいと思っているのではないかと思うので、ぜひ採択にしていただけたら、皆さんでできたらいいなと思うのですけれども、いかがでしょうかという問いかけもしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、採択を主張します。再三申し上げておりますが、新飛行ルートの説明会については、目的が変わってきたということからも私たちはきちんと説明を受けなければいけないとも思いますし、ぜひ皆さんにも本日結論を出すで採択に回っていただければと思います。説明会は開催されるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"特に区役所に行けるように求めておりますけれども、区のお考えをお聞きしたいのと、あと、もう一点、率直にお聞きしたいのが、参考資料１の１４ページで、最寄り駅までの標高差による評価というところで、標高２０ｍ以上のところが西側に結構固まってあるのですが、評価としては１とか２になっていて、標高差の関係がどうなっていたのかと思ったので、お聞きします。","respondent":"鈴木都市計画課長","answer":"利便性を高めていくというところで、導入に向けた検討を開始しています。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"高低差のところは分かりました。それは分かりました。結局、使われずに廃止になってしまうということでは意味がありませんので、ぜひそういったことも検討していただきたいと思いますが、今後、試行運転をしていく中で、ルート変更をしていく、改善していくということもあり得るのかどうか、伺いたいと思います。ぜひ五反田駅まで延ばしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"試行運行の中でルートの見直しがあるかですが、先ほどご説明したように、１３地域の中でいろいろワークショップという形でご意見をいただきながらこれから３ルートの検討を深めてまいります。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"試行運行のところなのですが、そこでのルート変更は考えていないというお話と、期間によって、１年から３年というお話がありましたが、年度ごとに変えていくというようなことも言われた気がしたのですが、どちらなのかよく分からなかったので、そこのところを確認させていただきたいと思います。いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"そうした意味で、３ルートを結んでいくという考えはございませんが、当然ながら、先ほどの利便性を高めていくためには、大井町駅もそうですが、集客性のある武蔵小山駅ですとか、西小山駅ですとか、そうした駅を結んで乗り換えていただく。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"これから試行運行がされていくということになると思いますけれども、やはり地域の方々が利用しやすい、また、移動の保障をするというところで、より便利な改善をしていくようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問・要望","question":"その次に病院などで、３つ目に商店街だったりの商業施設の話になるのです。区として今回の目的が、区内の交通利便性のさらなる向上に向けコミュニティバスの導入について検討を行うといったことだったのですけれども、利便性を区としてはどう考えているのかというのと、区の考える利便性と住民が求めている利便性に少し差があるのかといったところがあるので、その辺についてお話を伺えればと思います。","respondent":"鈴木都市計画課長","answer":"現時点では決定したものではない、候補ルート案だです。それから、今ご紹介いただきました、区民の声として区役所、あるいは病院、商店街に行きたい、これは昨年６月に実施したアンケートでもそうした声は多く寄せられてあります。","id":"exchange-062"},{"speaker":"田中委員","kind":"質問・要望","question":"区役所に行けるバスがあれば、多分、区へ意見や声を届けたり、相談しやすさというのが上がるのかというのも思いますし、やはり必要とされているのは区役所へ行く道なので、ぜひそこは検討をしていただきたいというのと、あとは、ワークショップが１３地域で行われるということなので、ここでの意見が強く反映されると思っていいのでしょうか。そこを確認させてください。","respondent":"鈴木都市計画課長","answer":"ワークショップの区民の声の反映は、これ、まさに区内全域、１３地域を回ります。そこでどういう形でのワークショップかというのは今検討しているところですが、これからしっかり声をお聞きして、この候補ルート案等に反映していきたいと考えています。","id":"exchange-063"},{"speaker":"田中委員","kind":"質問・要望","question":"区への相談だったり、意見を届けるといった視点で、ホームページ等々のご説明があったのですけれども、それだとなかなか伝わらなかったり、例えば、手続きだったりに関しては難しかったりするので、窓口に行ってといった意見とかもあります。このワークショップについても、積極的に周知、町会だけにとどまらない、多くの方に知ってもらえる機会を求めたいと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ワークショップについては、これはどういう形で区民の参加を求めていくかということは今検討中でございまして、ただ、例えば、このルート３案が通る地域の方を重点的にということではなくて。","id":"exchange-064"},{"speaker":"田中委員","kind":"確認","question":"１３地域で行われたワークショップの結果だったり、ワークショップの状況というのが公表されたりするのか、確認させてください。","respondent":"鈴木都市計画課長","answer":"ワークショップの結果は、公表してまいります。","id":"exchange-065"},{"speaker":"田中委員","kind":"意見","question":"全地域の人が一遍に集まってという場が難しいのであれば、それぞれの地域がそれぞれの地域のことを考えられるというか、“あそこの地域ではこういう負担があるのだね”といったような共有ができるような、それでそれぞれが譲り合えるような感じができたらいいというのを思うので、ぜひそういった検討もしてもらえればと思います。","respondent":"鈴木都市計画課長","answer":"そういう意味では、ある意味、地域特性も踏まえて、一律の視点だけでのアンケート結果の公表の仕方ではなくて、クロス集計もしています。こうした結果も活用しながら、今、委員にご提案いただいたように、このワークショップの結果というのは広く周知をして、進めていきたいです。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"福祉的な目的なのか、何を一番目的とされているのかをお聞きしたいのと、それから、１日あたりの乗車人数。別に赤字だからだめだと言っているわけではなくて、結局、福祉目的であって、これぐらいのお金であったらカバーしてもいいのではないかと考えているのか、それとも、この路線というのはプラス収入という形として考えていくべきものだと思っているのか、その辺はいかがでしょうか。教えてください。","respondent":"鈴木都市計画課長","answer":"ただ、例えば、大崎ルートで１日あたりの利用率を１００円と２２０円で変えているのは、例えば、１００円にすれば当然それだけ乗っていただけるだろうということで、料金による差ですとか、あとはこの利用率の算出にあたっては、一定、国勢調査のメッシュデータを活用して。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"７時の段階なんてとてもとても。確かに今回の陳情の方々、南大井地区ということなのですけれども、ただ、大井ルートをこのように考えているのであれば、これ、事業者とも話をして、いろいろ意見を言われると思いますが、このルートは私は避けるべきだと、非常に危険性の高いルートになってしまうと考えていますので、それも含めて検討していただきたいと考えていますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"コミュニティバス導入にあたっての目的ですとか、ひいては品川区の公共交通のあり方的なところは、今日、資料には抜粋版としてお配りしていますから、添付してございませんが、昨年度３回の検討会の中で、地域公共交通基本方針（素案）ということをとりまとめてあります。","id":"exchange-068"},{"speaker":"西本委員","kind":"確認","question":"安全性について、いろいろと検討されているところだとは思います。私は大井ルートのほうはそういう形で見させてもらいましたけれども、ほかのところもあるかもしれませんので、ぜひ確認しつつ。目的のほうは、繰り返しになるので、最後の意見として聞いていただければと思うのですが、税金を使うわけです。コミュニティバスというと、さもすごく便利に聞こえる部分もあるのですが、実際どうなのだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここまでやったわけです。だから、これからワークショップに行ったときでも、やはりそれはきちんと説明してほしいと前にも言ったのだけれども、“ここはできません”ときちんと言ってください。だから、ぜひそこら辺のところを踏まえてやっていただきたい。そこの幅員で警察との交渉とか、地域に入ったときのワークショップ、特に３つの候補ルートのところ、そこのやり方を、少しそこだけは答弁してほしい。","respondent":"鈴木都市計画課長","answer":"ご意見をいただきました、検討案に対する地域への説明ですが、１回目、２回目、３回目と、１３地域を回って検討状況については説明をしてまいりまして、特に３回目、ルート案を具体的にお示ししたわけですが、コロナの関係で、まだ４地域にしか回れてございません。","id":"exchange-070"},{"speaker":"田中委員","kind":"確認","question":"すみません、確認させてほしいのですけれども、今のご答弁だと、この１３地域でのワークショップでの意見が出た場合に、その意見はあまり反映されない。今の出ている案をお願いする形のワークショップになるということですか。そこだけ確認させてください。","respondent":"鈴木都市計画課長","answer":"１３地域を回ってしっかり説明というのは、こういう１１指標で走らせたほうが効果が高い地域を選定しているというところと、さらにその３地域の中でこのルート決定にあたってはこういう視点でルートを決めているというところはしっかり説明するということです。","id":"exchange-071"},{"speaker":"田中委員","kind":"質問・要望","question":"ワークショップでの声も反映されるという理解で、分かりました。やはり関心が高いので、ワークショップにも多くの方が参加されるといいなというのと、あと、多く参加されて、意見がきちんと届いて、本当に皆さんから愛されるコミュニティバスになったらいいと思うので、ぜひその周知を。ワークショップで出た意見もきちんと反映できる形でといったことをお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択でお願いをいたします。その中で３候補案があって、その中で様々これから地域に入って、これを運行していこうという今の段階です。この中でいろいろ個人のお考えはあるのは分かるけれども、そういう意味では、我々はこの陳情については不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問・要望","question":"本日結論を出していただいて、不採択であります。均整のとれたということは、言葉を変えれば、住民要望、地域要望を十分にとり入れた、反映されたルートであると理解をしております。すると、この３つの選定の基準と１１の指標に基づかれて３ルートを決められたわけですから、この中で現状のところに瑕疵があるとは考えられないと考えています。よって、この３ルートについては非常に合理的なものと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"若林委員","kind":"提案","question":"結論を出すでお願いいたします。個別のルートのことについて、私どもはこの議会の場で結論を出すということはそぐわないと判断をしております。今後の事業者提案、それからワークショップ等、地域の声をまたしっかり反映されて、最善のルート設定になるようにお願いいたします。よって、不採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、区役所に行きづらいというのは、区内共通の課題ですし、便利なバスルートにすべきだと私も思いますので、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張したいと思います。やはり各地域では、区役所に行きづらいというのが大きな課題となっていますので、この陳情者の意見というのはとても理解できます。改善を求めているので、ぜひこの要望を聞き入れるべきだというのを思います。採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問・要望","question":"区役所に行けるようにするというのも一つなのでしょうし、３ルートをつないでという思いも分からないではないのですが、今進めている３ルートがあって、地域への説明があって、まず動かしてみようというのが今の段階なので、それを受けていろいろないい案が出てくれば、そこでまた変えられるということもありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"この請願の中に、令和元年７月に人身事故等があったと書かれておりますけれども、この人身事故や過去にあった死亡事故というのはどういうものだったのか、ご存じでしたら伺いたいと思います。併せて、駅周辺での基盤整備、まちづくり関連の事業推進ということが書いてありますが、このまちづくり事業というのはどういったものがあるのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"事故につきましては、過去５年間調査いたしました。事故の件数は合計４件、中にはホームでの飛び降り事故であったり、遮断機をくぐるなどの事故がございまして、２名の方が亡くなっておられます。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"事故については、過去５年間で４件あったということで、そうした事故がなくなるという面では、この立体化というものが安全なまちづくりに資するということであると思います。この基盤整備も、そういったことも含めて求めているということだと思うのですけれども、鉄道の立体化と再開発などを一体に進める必要があるのか。なぜそういうことになるのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"そうした立体化事業ができた暁には、駅前広場等々が整備され、交通結節点の機能の強化といったものが生まれます。そうした中で、地域が考え、また、まちづくりを考えたときに、市街地再開発事業といったものが生まれてくるのかです。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"直接的には立体化と再開発との関係性はないということでした。ですので、私はやはり立体化は立体化、再開発は再開発ということで、再開発は中止すべきなのですが、立体化は立体化で進めていただきたいと思いますので、そういったことで要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"田中委員","kind":"確認","question":"この請願の要旨だったり理由というのは、とてもよく分かります。けれど、項目の２にある駅周辺の基盤整備、まちづくり関連が一緒になると、ちょっとなという気がします。その理由の一つに、補助２９号線の問題で今、訴訟もあったと思うのですけれども、今、その訴訟の問題はどうなっているのかというところを確認したいのです。","respondent":"中道まちづくり立体化担当課長","answer":"補助２９号線の訴訟につきましては、東京都が所管しておりますので、こちらとしましては、そこまで確認をしているところではございません。","id":"exchange-082"},{"speaker":"田中委員","kind":"質問・要望","question":"今、都が所管ということだったのですけれども、まちづくりを、そういった計画も定まっていない中で単独で考えて進めてしまうのはどうなのかというところがあります。今年の３月２５日に、まちづくり協議会と区の連名で要望書を提出したということで、要望書も確認しました。この要望書を提出した経緯について伺いたいのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"平成２８年度に今のまちづくり立体化担当を新設いたしまして、重点的に地域とこの取り組みを行ってきたところです。そうした中で、地域からの要望を受けて、また、区も立体化を推進していくという立場から、東京都に対して連名で要望書を提出したところです。","id":"exchange-083"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほども話した補助２９号線の訴訟の問題がある中で、区民の中ではそうした訴えもしている中でこの要望書が提出されたということと、あと、タイミング的にコロナのことで、たしか３月２５日は東京都のほうで週末の不要不急の外出はあまりしないでといった要請が出されたときだったと思うのですけれども、そういったコロナの問題が起きている中でこの要望書が提出された理由についてお知らせください。","respondent":"中道まちづくり立体化担当課長","answer":"要望書を提出した経緯ですけれども、こちら、連続立体交差事業といたしましては、短期的な目的で物事を見ていることではなくて、中期、長期で物事を考えていくといったところでの要望書の提出です。","id":"exchange-084"},{"speaker":"田中委員","kind":"質問・要望","question":"都との関係の中でというのがいまいち分からなかったので、そこの説明と、あと、補助２９号線の訴訟がある中、区民の中で反対意見というか、訴訟が起きている中での要望書が出された経緯、コロナのこの時期というのと、訴訟がまだ解決していない中での提出について、この２点について伺っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"田中委員","kind":"意見","question":"法的な問題とかではなく、区としてどういう考えで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"田中委員","kind":"質問・要望","question":"しかし、それと一緒に駅周辺の再開発、まちづくり関連は、また別の話なので、少し違うのかというのを思うのと、要望書がなぜ出されたのか。なぜこの時期だったのかといったところを伺っていて、緊急事態宣言の前だったからではなくて、どういう意図で、どういう経緯でこの要望書を出すことになったのかということを伺っているので、そこの説明をお願いいたします。","respondent":"中道まちづくり立体化担当課長","answer":"要望書を提出した経緯としましては、地域の声と区の事業への推進といったところでの要望活動の一環です。","id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"要望書は地域の声が上がってきたために出したということだったのですけれども、地域の声をどのようにとられて、どういった意見を……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問・要望","question":"でも、この中にも、区と連名で要望書を出したことについても触れていますし、そこは大事だと思いますので、伺っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問","question":"今私が伺っているのは、日付ではなくて、なぜこの時期にというのを伺っているので……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問・要望","question":"なぜ連名で出すことになったのかということをお知らせいただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"今、戸越公園駅付近は事業候補区間に位置付けられております。地域といたしましても、また、区といたしましても、これを準備中区間のほうに格上げをしたいといったところから、両者の思いで要望書を提出したところです。","id":"exchange-091"},{"speaker":"田中委員","kind":"意見","question":"地域の声があり、連名で出したということだったのですけれども、具体的に地域の声はどういった声があったのかというところをお知らせいただけますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"田中委員","kind":"質問・要望","question":"今、まちづくり事業と一緒に出した要望書については、地域の声にどのような声があって、この要望書を提出したのかということを質問した、そのご回答が、まちづくり協議会の方たちとの意見ということだったのですけれども、そうではなくて……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"田中委員","kind":"質問","question":"それは分かるのです。地域のどのような声があったのかということを伺っているので、そこをお答えください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"田中委員","kind":"質問","question":"この請願にある立体化事業に対する意見というのは、とても分かります。ただ、それに併せたまちづくりに対しての地域の声というのを聞きたいのです。この「地元の悲願である鉄道立体化の早期事業化」については確かに分かると先ほどから言っているのですけれども、それに併せた駅周辺のまちづくり推進について、どのような区民の声があるのかというのを伺っているので、お答えください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"これまでの経緯というところで、要は、平成２６年に品川区に立体化の要望書を提出し、そして、半年後に都へ提出して、それを受けて都は事業候補区間にしたということですよね。今回、令和２年３月に連名で要望書を提出したということで、この４年間何もなかったのでしょうか。最後に、まちづくり協議会なのですけれども、そこの周辺で所属しない商店街とか町会とかというのはあるのでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"最後に、まちづくり協議会に含まれていない関係する町会等々があるかといったところですが、１つ、商店街がこの協議会の中に入ってはいないのですけれども、ここの町会で同じような取り組みでやっておりますので、そういった意味では、関係する町会長。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問・要望","question":"ありがとうございました。地域が変わりますから、いろいろな不安の要素もあるかと思います。それは、私はマイナスには捉えてはいなくて、これだからこそ今の商店街をどう活性化していくかという前向きな形でこういう協議会の皆さんに話し合っていただければ、非常にありがたいと考えていますので、今後もいろいろアドバイスをしていただきながら、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。採択でお願いをいたします。先ほど来いろいろな話があって、立体化というのもありますけれども、立体化をやると、駅前広場というのがあるけれども、多分これは駅前の交通広場だと思うのです。ぜひそういうことも含めて、今、準備中区間にいち早くということであれば、それに対して議会でも一緒に協力をしていくべきだと考えていますので、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"大沢委員","kind":"質問・要望","question":"本日結論を出していただいて、採択でお願いします。立体化に伴う踏切の除却、これは都市基盤を整備する、あるいはバリアフリー化する、都市としてのあるいはまちとしての広がりを醸し出す重要な要素であります。近々では、東急目黒線の立体化によって、いい例も、私、間近で見ておりますので、これについては大いに賛成をさせていただきたいと思います。よって、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"若林委員","kind":"質問・要望","question":"このまちづくり協議会の皆様、大変に熱意のあるお話も伺う機会がございました。今ようやく事業候補区間に指定をされたというところで、この請願の記書きにもありますとおり、連続立体交差事業の早期事業化をぜひ図っていただきたい。２つ目の駅周辺の基盤整備、まちづくり関連の事業推進も、都としてもしっかりと取り組んでいただきたい。こういう思いで採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"のだて委員","kind":"意見","question":"１つ目の項目は、安全なまちづくりに資する鉄道立体化ということで賛成ですけれども、２つ目の基盤整備やまちづくり事業の件は、住民を立ち退かせる補助２９号線ですとか、住民の望んでいない超高層の再開発、大体５階建てぐらいのまち並みに２３階、８５ｍのものが建つというものですので、これに賛成することはできないということで、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"田中委員","kind":"意見","question":"この請願については、継続をお願いしたいと思います。理由は、立体化事業については、区民の方たちの意見もあることですし、理解するのですが、項目２のまちづくりについては、先ほどの質疑同様です。現在、コロナ対策について、東京都も、品川区でも対策がされている中で、今これを進めるべきなのかといった課題を感じます。ですので、継続にしたいと主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論をお願いいたします。採択でお願いいたします。連続立体交差事業、これは早急に進めていただきたいということと、基盤整備につきまして、まちづくりなので、これからいろいろとまちの変化も出てくる可能性はあります。なので、関係者がほとんど入っているまちづくり協議会ですから、皆さんのいろいろな意向、それから社会情勢を踏まえて議論をして進めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"田中委員","kind":"質問・要望","question":"継続がだめだということなので、残念ながらなのですけれども。本当に趣旨、鉄道立体化については理解をしています。しかし、この事業が今本当に必要なのか。今はコロナ対策が喫緊の課題だということを感じておりますので、不採択とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"幾つか質問させていただきたいのですが、今回、防災生活道路にかかる公園ということで、ほかにもかかるところがあると思うのです。そこの道路にかかるところの、まだ買収できていないところ、関係権利者ということで、土地の所有者やアパートを借りている人など、それぞれ何人いるのか、伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"先ほどご説明したとおりでして、本件のところが一番狭いところになっておりますので、本件については優先度が高いと認識しております。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"こうした中で公園を整備して、桜が切られてということになれば、やはり住民の皆さんの思いはやり切れないのではないかと思うのですけれども、いかがでしょうか。すぐに道路整備ができるというわけではない状況だと思いますので、陳情項目にもあるとおり、最終段階に延ばしていただいて、できるだけ桜、木蓮を残していくべきではないかと思いますが、いかがでしょうか。","respondent":"佐藤木密整備推進課長","answer":"今回、桜の木を切るということにつきましても、地域の方にはご説明をして、桜に関しては残念だというお話は聞いておりますけれども、それでも地域の防災性の向上を優先していただいて、今回ご協力いただくことになりました。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり町会でも、この桜を残してほしいという声と、近隣の方は、虫が来るというので、やめてほしいという声もあるみたいですが、やはりそういった様々な声がある中で、今、拙速に真っ先に切っていくということはすべきではないと思います。ぜひ考え直していただきたいと思います。仮にこの陳情審査で採択となった場合は、工事を止めるということになるのか、区の判断を伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"地域の防災性の向上のためにも、ぜひ今回実施させていただきたいと考えております。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"私も、近くを通って桜を見ていますけれども、やはりこの間もきれいに桜を咲かせているのです。そういった中で、切っていくということは、やはり住民の皆さんとして忍びないという思いがあると思います。できるだけ最後にしてほしい、桜を残してほしいというささやかな願いだと思うのです。これを叶えていくということが、区の、行政としてやっていくべきことだと思いますけれども、いかがでしょうか。","respondent":"佐藤木密整備推進課長","answer":"繰り返しになりますけれども、地域の防災性の向上のために、予定どおり事業を進めさせていただきたいと考えております。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"ここの部分が最後に残されたところだというお話ですが、まだ住んでいる方がいらっしゃいますし、そういった方々は、ここに住み続けたいということで住んでいるわけです。公園を整備すれば緊急車両が通れるということではないと思いますので、こうした住民要望をしっかりと叶えていくということで、強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問","question":"委員会資料の中で、樹木診断を実施した際に、移植が不適であるとの診断結果だったということなのですけれども、これはあくまでも移植が不適なだけで、樹木の状態についてはどうだったのかというところを伺いたいのですが。","respondent":"高梨公園課長","answer":"樹木の診断関係ですが、今回の公園を削る工事に関しましては、木密整備推進課から公園課のほうに依頼がございまして、公園課で実施をしておりますので、樹木診断の結果と併せて、私からお答えします。樹木診断の結果で、外観等です。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"例えば、ベンチを作るとか、何かここに桜がありました、木蓮がありましたみたいなものができたらいいなというのと、この陳情の中にも、いろいろと戦争時の犠牲者が流されたところの鎮魂を含めたという意味もあるということになると、多少何らかの記念碑までいかなくても、何かそういうものも公園の中に作ってあげられるといいのかと思うのですけれども、木の有効活用と、それから、この鎮魂というところは。","respondent":"高梨公園課長","answer":"それと、この公園は２３２m2の非常に狭い公園で、さらにそれが１０m2弱削られるということで、現在も小さなお子さん中心に滑り台等で遊んでいただいているのですけれども、既に子ども、遊具、今ある公園の施設関係で手いっぱいの状況ですので。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"そんな大きなものを想定しているわけではないのですけれども、何か有効活用をぜひしていただきたいと思っているのと、この由来的なところ、今のご答弁だと、深い意味があったのかどうかよく分からないというところがあるのですが、若干、地域の方に聞いていただいて、そういう経緯があるのかどうかだけの確認をしていただきたいと思うのです。ぜひ少しで結構ですので、よろしく検討をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"若林委員","kind":"質問・要望","question":"そういういわゆる品川上水に関連して、当時の区民、市民の方々が、そういう思いやりの心をもって、その象徴としてここに上水が通っていましたという表示とか、そういうものがもし事実であれば、それは品川区の青史としてそれはどこかに残すべきであろうし、もしかしたらここのところに、残念ながら防災上、どうしても広げなければいけないということであれば。","respondent":"佐藤木密整備推進課長","answer":"ほかのところも、６ｍのところでいきますと、５ｍ以上道幅はあるのですけれども、何か建替えの際に下がっていただくという形で整備を行っていただく必要はありますが、緊急車両の進入という意味では、ここが最後と言ってよろしいかと考えます。","id":"exchange-113"},{"speaker":"若林委員","kind":"意見","question":"少し聞きたいことと違ったかもしれないのですけれども、平面図を見ても、一つのボトルネックになっていて、防災上、客観的に好ましくないと感じると思います。桜をできるだけ長い間切らないでくださいということについて、品川区のほうもその意を酌んで今年は桜を切らなかったという真摯なご努力は、私はこれは認めなければいけないのかという感想をもっております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-114"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。やはりそこは、先ほど若林委員も言いましたけれども、１年間待たれたということもあって、地域の方ともよくお話をして、これでいくということになっていると。ただ、桜なのです。例を２つ言います。台場小学校の校舎建替えのときに、切った木を１ｍぐらい学校に転がしてもらいました。それはそれだけお願いをしておきますが、基本的にはこの陳情については不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"大沢委員","kind":"質問・要望","question":"本日結論を出していただいて、不採択です。結論と特に関係ありませんけれども、品川上水なるものはありません。品川用水です。そこら辺の確認をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出すで、先ほど意見も要望も含めて申し上げました。これについては、不採択ということで、判断をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"のだて委員","kind":"質問","question":"地域に愛されて、親しまれているこの桜と木蓮の木を切らないでほしいというのはささやかな願いですから、道路も早急に進むものではないので、できる限り地域の方を癒やしてほしいと思います。結論を出す、採択で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、採択を主張します。先ほど質疑であったように、寿命がまだ来ていないということで、地域の声もあることですし、木をまだ生かせてあげられたらと思いますので、採択したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-119"},{"speaker":"西本委員","kind":"確認","question":"本日結論を出してください。不採択でお願いいたします。先ほども意見を言いましたけれども、石田秀男委員も言っておりましたが、何か地域の方々に思い出となるようなものとか、あとは、事実かどうか分からないのですけれども、少し確認をしていただいてということで、その配慮をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503098?Template=document&Id=4294#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":71857,"voices":335}},{"id":"r02-20200629-9","meetingId":"r02-cm06","date":"2020年6月29日","dateIso":"2020-06-29","committee":"文教委員会","time":"午前１０時００分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"区のご答弁は、不明確で定量的に示すのは困難、という感じだったのですけれど、文科省の指針などもある中で、なぜ困難なのか、どこが不明確なのか、区の現在や過去の待機児数のカウントの仕方の変遷ですとか、あるいは分かる範囲での他自治体の動向ですとか、国の指針の内容なども併せて、教えていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"６月２６日の中塚議員ならびに松本議員から、学校の校則についての質問が出ました。ご答弁もあったのですけれども、ちょっと不明な点もありましたので、改めて教育委員会の学校の校則に対する現状の把握と、今後の考え方についてお伺いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"第４３号議案、品川区立児童センター条例の一部を改正する条例および品川区立保育所条例の一部を改正する条例の一部を改正する条例","agenda":"第４３号議案、品川区立児童センター条例の一部を改正する条例および品川区立保育所条例の一部を改正する条例の一部を改正する条例","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"コロナの関係で工事が遅くなるというのは、大変理解はするところです。細かい区切り方で、当初の２２日後、約３週間後ということなのですけれども、これの竣工そのものというのは何日になっているのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"竣工ですけれども、当初は令和２年８月３１日でございましたが、今回、令和２年９月１８日の予定です。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"こういう細かい移し方をしていると、ちょっとその辺が大丈夫なのかなという、揮発していないままに急いで使い始めるということにならないかという、その辺、いかがお考えでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"浮遊物の検査を含めまして、９月１８日の竣工予定です。前回も当初の予定が８月３１日ですけれど、その際も、浮遊物の検査が終わって引渡しという予定で進めていたところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"新型コロナウイルス感染症対策の影響で工事の一部休止ということなのですけれど、具体的にはどういう状況で休止になってしまったのかというのが分かれば、お伺いしたい。併せて、建替え・改修を終えて現在地でこの保育園と児童センターが開園する時期というのはいつ頃を予定しているのかも伺います。","respondent":"吉田保育施設調整担当課長","answer":"他の工事への影響ですが、保育園関係では特に影響が出ているところはございません。それから、建替え・改修後は、９月１９日から２２日までの間で児童センター、保育園の引っ越しを行いまして、９月２３日から新しい場所で稼働する予定です。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"学校のほうではコロナの影響はどうかなということと、あと最後のところは、一旦仮移転してまた戻ってきて、元の場所で建替えするではないですか。その建替えが終わって、こちらの元の場所で児童センターと保育園が開園するのは大体いつ頃なのかなというのが分かれば。","respondent":"有馬庶務課長、吉田保育施設調整担当課長","answer":"それからもう２つぐらいの大手の会社で、やはりゴールデンウイーク前後に３日ほど休業要請がありましたので、それについては認めたということですけれども、全体の工期としては今のところ影響はないというふうに考えているところです。東大井公園を利用して建替えが終わり、戻ってくる時期ですけれども、予定としましては２０２２年の１０月を目途としています。","id":"exchange-006"}]},{"id":"topic-03","title":"第４４号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第４４号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回の基準の改正の理由について、ちょっと伺いたいのと、それと、この資格研修の主な研修内容と、研修回数や時間というのはどれくらいなのでしょうか。併せて、その研修の内容ですが、今回、中核市の長が実施主体として追加されましたけれども、その中核市の長の方が実施する研修の内容が、ほかのものと変わるということはあるのでしょうか。伺います。","respondent":"廣田子ども育成課長","answer":"主な内容は、課目が大きい区分で６つほどあるのですけれども、この事業に対する理解であるとか、子どもを理解するための基礎知識、放課後児童クラブにおける子どもの育成支援について、保護者、学校、地域との連携・協力について、安全・安心の対応について。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"これ、２３区、特別区が加わるという話というのはなかったのでしょうか。例えば品川区の場合、中核市が加わってもあまり関係がないわけで、むしろ、今だったら都道府県ということで都ということになると思うのですけれども、人口からいうと２３区もこうした権限を持ってもいいのではないかと思うのですが、そうした議論があったかどうか教えてください。","respondent":"廣田子ども育成課長","answer":"現時点で特別区が入るということはないのですけれども、東京都で実施している研修が、年間１１クール開催されておりまして、おおむねこの５年間で、現在勤務している人はもう全て受けてしまっていて、新たに勤務した、異動等で来た者であるとか。","id":"exchange-008"}]},{"id":"topic-04","title":"第３９号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３９号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"現在感染者もじわじわ増えてきているのですが、今後の供給体制とか確保の見通しというのはどのように、楽観できるのかどうか、ちょっと伺いたいなというのが１つ。こういった同様の衛生用品の配付というのは、区立保育園には現金支給の形でやったと思うのですけれど、認証を含む私立保育園ですとか幼稚園のほうにはされたのかどうか、すみません、確認させてください。","respondent":"三ッ橋子育て応援課長、若生保育支援課長","answer":"今後の供給につきましては、子ども食堂ネットワーク事務局と連携を取りながら、何かご要望がないか、随時聞いていくところです。私立保育園等に関する、マスク等衛生用品の配付に関してですけれども、こちらは区立等と同様、国ですとか都のほうから配付されている分を、各園のほうに配付するという対応を行っております。","id":"exchange-009"},{"speaker":"安藤委員","kind":"確認","question":"併せて、ひとり親世帯臨時特別給付金のほうなのですが、これはなるべく早く漏れなく確実に、対象の方に届くということが大切だと思うのですけれども、この資料があるところの基本給付というところの（２）の1)、2)、3)とあるのですけれど、それぞれの対象世帯数というのはどれぐらいいるのか伺いたいと思います。","respondent":"吉田保育施設調整担当課長、三ッ橋子育て応援課長","answer":"オリンピック・パラリンピックの保育園における来年度の予定ですけれども、これは来年度の予算編成の中でまた決めていくものと予定しております。3)につきましては、これは想定することが非常に難しいのですけれども、実際の児童扶養手当の対象よりは少ないと見込んでおりまして、約１,５００世帯と見込んでおります。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと確認なのですが、今回の給付金で支給される最大金額ですけれど、ふだん児童扶養手当を受けている1)の世帯の方で、さらにコロナで家計が急変している世帯の場合は、基本給付は５万円で、２番目の追加給付が５万円で計１０万円になって、さらに子どもが２人以上いれば第２子以降１人につき３万円ずつ加算という理解でよろしいでしょうかということを確認させていただきたい。","respondent":"三ッ橋子育て応援課長","answer":"金額につきましては委員の発言のとおりです。次に、収入の見込額、急変された方の申請はどのようにするのかという部分ですけれども、まず新型コロナウイルス感染症の影響により、収入が減少したかどうかのチェック、こちらは自己申告になります。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと併せて、学校給食費のほうにも行きますけれど、事業費支援の対象となる事業者というのは、大体何事業者ぐらいいらっしゃるのか分かれば、ざっくりでもいいのですけれど伺いたいのと、主にどういう食材をどういう規模のお店に発注しているのかというのも、イメージをつけるために教えていただきたいと思います。","respondent":"三ッ橋子育て応援課長、篠田学務課長","answer":"対象となる方、児童扶養手当以外の方につきましては、非常に難しい周知だとは思うのですけれども。主にその食材ですけれども、今回、２月の末に急遽学校を閉めるということで、３月の頭からということでしたので、主に生鮮品、肉、魚、野菜。周知について補足いたしますが、広報紙なども使って周知してまいります。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"周知のほうですが、ホームページと広報紙というのは、それは当たり前だと思うのですけれど、やはりふだんは児童扶養手当を受けていないような方でもがくんと収入が減ってしまって、そういう方が対象になっているわけですから、それはぜひしっかり、こういう制度あるんですよということを届ける工夫はもっとしていただきたいので、そういう方が足を踏み入れるような。","respondent":"三ッ橋子育て応援課長、篠田学務課長","answer":"委員ご指摘のように、周知につきましてはアプリやツイッター、そして民生委員協議会にお知らせするなど、様々な工夫をしてまいります。この形はまだ、コロナウイルスの感染状況が落ち着いたものではないので、当面はこの７月いっぱいまで、この形での提供を続けていくことを予定しているものです。それから、食材の量が少なくなっているのではないかというご質問です。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"給食のほうは、今回時数を取り戻すために７時間というのが連日あったり、２年生でも７時間ということで、大変な事態ですよね。すみません、最後、タブレットの件ですが、２万４,０００台ということで、区立校の児童・生徒数プラス教員数だと伺っているのですけれど、今までモデル校に先行配付していたタブレット台数というのは幾つだったのか、それらの活用というのはどうなるのか伺いたいと思います。","respondent":"篠田学務課長、工藤指導課長","answer":"特にＩＣＴ活用推進校以外の学校というのは、現在配備されているのがパソコン教室用の、１つの学校で４０台しかございませんので、そういった学校のほうに持っていけば、ある程度平準化して使えるものというふうに考えているところです。それらの先行事例なども踏まえながら、教職員の研修も含めて効果的な活用の仕方を進めていくのですが、その上では委員からご指摘ございましたように、児童・生徒に対して負担にならないようなというところでは。","id":"exchange-014"},{"speaker":"あべ委員","kind":"質問","question":"引き続き幾つかお伺いしたいと思います。現段階でこれを配付することの意味と狙いを教えていただければと思います。医師会ともう話がついていると思いますけれども、いつ頃の予定か教えてください。同じく共通ですが、オリンピック・パラリンピック、ちょっとごめんなさい、私、予算のほうと見比べ損ねているのですけれども、これ、減額はするのですが、残りの金額というのが少しあるのでしょうか。","respondent":"三ッ橋子育て応援課長、若生保育支援課長、吉田保育施設調整担当課長、篠田学務課長、工藤指導課長","answer":"委員のご指摘のように、今開催している子ども食堂は全部ではない状況ですので、まずは全体の数を予算として見込んでおりまして。区としましては、こういったところに対しても今後、保護者に対しての支援というのは引き続き行ってまいりたいと思いますけれども、今回。健康診断についての質問ですけれども、通常は年に２回、おおむね４月と１０月に健康診断をやっているところです。ただ、現実には学校医に診ていただく部分がかなりあるのですが、それぞれの先生方のお考えで、なるべく遅くにと。","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問・要望","question":"健康診断も別に不要不急のものではもちろんないものですから、やはりどこかの段階では、特に新入学生などについては見落としのないようにしていただきたいと思います。それから給付金に関する質問に移らせていただきたいと思います。給付対象なのですけれども、この（２）の2)、公的年金受給者のうち、とあります。ひとり親で公的年金受給者という、これは障害年金などをイメージしたらいいのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"公的年金を受給している方の場合は、例えば遺族年金、障害年金などの方が対象となります。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"遺族年金と障害年金がほとんどのイメージかと。その中で、６月分手当支給が全額停止される方というのは、その中で所得が基準を超えた方というイメージなのですか。","respondent":"三ッ橋子育て応援課長","answer":"全額停止された方というのは、公的年金のほうが児童扶養手当よりも多くもらっているので、全額停止となっております。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"とすると、この方々というのは、行政のほうで横の連携を取れば、対象者が確定するということになるのではないかと思いますが、この方々もやはり申請しないと受け取れないということなのでしょうか。年金関係の部署と連絡を取れば、申請が必要であっても少なくともその対象者全てにご案内を送ることぐらいはできるのではないかと思いますけれど、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"先ほど周知につきまして、（１）の児童扶養手当の方には直接周知と申しましたが、確かに委員おっしゃるとおり、公的年金の方も把握はしておりますので、先ほど触れたのですけれども、分かる方に関しては、全額停止されている方に関しては周知していく予定です。","id":"exchange-018"},{"speaker":"あべ委員","kind":"確認","question":"確認をさせてください。とすると、少なくともここに申し込んでいる方のうち、ひとり親の家庭というのは皆さん対象になるのではないかと思うのですが、教育委員会のほうに伺いますけれども、就学援助は今どのくらいの方が受けていらっしゃるのか。それから、特に今年の収入激減で、昨年度の所得に関わらず新たに就学援助の対象になった方はどのくらい今、いらっしゃるのでしょうか。","respondent":"三ッ橋子育て応援課長、篠田学務課長","answer":"公的年金の部分ですけれども、公的年金を受給されていて児童扶養手当を全額停止されている方については把握できておりますので、その方には通知してまいります。現在はちょうど集計中なものですから、具体的な数字はちょっとまだ上がってきてないような状況ですので、こちらのほうはまた、その辺が確定した時点で改めてお答えさせていただけばと思います。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"これはひとり親ですからお子さんがいらっしゃいますので、少なくとも学校、幼稚園、保育園、ここの全員に、今の就学援助とセットにして１枚で構わないと私は思っているのですけれども、今年収入が激減した方についてはこういう制度があります、１つには就学援助、さらにひとり親の方については特別給付金もありますと。５万円と書いてあったら結構目を引くと思います。いつ頃までに申請すればいいのですか。","respondent":"三ッ橋子育て応援課長","answer":"こちら、締切りというのが非常に難しいのですけれども、区が国に申請する関係上、３月３１日〔同日後刻に「２月末」と答弁訂正あり〕まで、年度内にきちんと申請してくださった方というふうに考えております。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"ひとり親家庭なのですけれども、実際にはそのひとり親状態、ひとりで子育てをしているけれども、法律的に離婚ができていないという方々は対象になると考えてよろしいのでしょうか。あるいは、離婚協議がまとまっていなくて、でも事実上はひとり親という、ここの層が結構手当てもなかなか出にくくて、一番生活が厳しいんですよね。ここの扱いはいかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"実際に離婚されている方、また調停中の方、いろいろといらっしゃるかと思いますけれども、その方に関しましてはご相談いただいて、そのときの状況で判断してまいります。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"学校のＩＣＴ活用についてお伺いしたいのですけれども、先ほどのご答弁の中で、タブレットは全て置き換えというふうな答弁がありました。ＩＣＴ活用推進校のほうは、今使っているものというのはもう老朽化で廃棄とかいう感じなのですか。それともダブルで持っているということでしょうか。ちょっと教えてください。","respondent":"篠田学務課長","answer":"その他の活用に関しましては、様々な意見もまだ整理がされてございませんので、どのようになるかという具体的な形はまだ見えていないのですけれども、そういった形で無駄のないように使うということを考えているところです。","id":"exchange-022"},{"speaker":"あべ委員","kind":"確認","question":"今、ＩＣＴ活用推進校等で持っている台数を確認させてください。もし、Ｗｉ－Ｆｉさえあれば使えるのであれば、今後その第２波が来年度までに来た場合に、これをＢＹＯＤ方式を採って、かつ貸与用にも使えるのではないかと思うのですけれど、いかがでしょうか。","respondent":"篠田学務課長","answer":"これは台数的には４５４台という形なのですけれども、ただ、残念ながらセルラーモデルではなくて、Ｗｉ－Ｆｉモデルが来ましたので、もしご家庭へお貸しするのであれば、セルラー対応をしていきたいと思っており、一部の部品等の取付けをすれば。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"新たに入れるものはセルラーモデルとのことなのですけれども、これは学校内で使うときもセルラーでということになるのでしょうか。何かあっという間に終わってしまって、もう今月は無理ね、みたいな話になってしまってはストレスですけれど、そこはどうお考えでしょうか。","respondent":"篠田学務課長","answer":"そうしませんと、今委員ご指摘のとおり、例えば動画等を見るとあっという間に上限使用量に到達してしまうということになりますので、校内ではＷｉ－Ｆｉを使う。それから外に持ち出して、ご家庭に持っていったときにはセルラー対応にするといったようなことを考えているものです。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"聞きたいことたくさんあるので、冗長にしているつもりはないのでご理解いただければと思います。ということは、休校になったときには動画で使える量というのはかなり制限がされるというイメージでよろしいのでしょうか。そういう学校外で、例えば自宅で授業を受ける、動画を見る、双方向というのはかなり絞って使うイメージですか。","respondent":"篠田学務課長","answer":"ですので、動画もかなり画質のいい形で流してしまいますと、確かに容量をかなり食ってしまいますので、例えば教育委員会から配信する際には少し画質を落としたものを配信するですとか、あるいは例えばＺｏｏｍなどを使ったりといったときは。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"ひとり親世帯臨時特別給付金について確認なのですけれど、これは厚生労働省の施策で、全額国庫負担ということで、実施主体は区で、そうした仕組みで品川区はその実施事務をやっているということでよろしいのかということと、区が出したこの補正予算額は、先ほど話に出ました世帯数などを逆算してこの額にしたのかということ。３点ほど質問させていただきたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"最初の２点に関しては、委員のご指摘のとおりです。最後の周知に関しまして、事務費という部分では、例えば児童扶養手当の方に申請のお知らせをしていくという費用も含まれております。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほど周知のことについて、ほかの委員からもいろいろなご要望がありましたけれども、ぜひ丁寧な周知をお願いします。次に、感染症対策についての衛生用品の購入についてなのですけれど、関連してその中に次亜塩素酸水の噴霧器というものは含まれているのか、もしくは既にもう所有などをされているのかを確認したいのですが、その点いかがでしょうか。","respondent":"吉田保育施設調整担当課長、篠田学務課長","answer":"次亜塩素酸水の噴霧器については、今回の予定の中には入っておりません。教育委員会での購入予定ですけれども、次亜塩素酸水の噴霧器については、予定はしていないです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"ではないということなのですけれども、次亜塩素酸水の噴霧器については、６月４日に文部科学省の通知で、使用しないでくださいということがあったのですが、６月１６日に学校における新型コロナウイルス感染症に関する衛生管理マニュアルで、有人空間に噴霧することができるというような通知というかお知らせを文部科学省が出したところなのですけれども、その点がかなり。","respondent":"篠田学務課長","answer":"現状は、通常の雑巾等による拭き取りのほうが確実にできるということがあるので、今のところは、噴霧器を使用して対応するということは考えていないということです。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問","question":"ひとり親世帯臨時特別給付金についてなのですけれども、こちらの周知方法のところに１、（２）、1)の対象者の方へは別途案内を送付というふうに書いてあるのですが、この別途案内については、追加給付についての案内も同封されるということでよろしいのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"はこの周知、今回のひとり親世帯臨時特別給付金のご案内をしまして、加えて辞退届を送付いたします。そして、段階を経て、追加給付のお知らせについてはまた改めて、現況届と同時の状況でお知らせする予定です。","id":"exchange-029"},{"speaker":"横山委員","kind":"質問・要望","question":"ですので、そういった方に改めて相談の支援ですとか、こういった子育て支援の対応がありますということを、コロナへの部分も含めてなのですけれども、通常の子育て支援の、どういったことをやっているかというような簡単な案内などもセットで通知していただいたり、ご案内していただくことによって、ふだん支援を受け慣れていない方というのは、そういったところに気づいていない可能性があると思いますので。","respondent":"三ッ橋子育て応援課長","answer":"委員のご指摘にありますように、ひとり親世帯の方は就労支援や、また子どもの学習支援など、区が様々行っている支援に気づけない方も非常にいらっしゃると思いますので、鋭意工夫しながら通知していきたいと思います。","id":"exchange-030"},{"speaker":"横山委員","kind":"確認","question":"ぜひ様々な工夫をしていただきながら、区民の方、今、大変厳しい、苦しい状況で、実際に今、大変な状況というときに自分からＳＯＳを出すというのはなかなか、通常頑張っている方こそ難しいと思いますので、様々な機会を捉えてこちらから発信をして、キャッチしたり、支援の状況を確認しながら対応していただくようにぜひお願いをしたいと思います。","respondent":"有馬庶務課長、廣田子ども育成課長、工藤指導課長","answer":"それからＰＴＡを対象に講演会なども行いますけれども、そういったものも６月の段階では中止ということで、集団で集まるようなものについては。子ども未来部関係に関しましては、やはり後半、３密になるようなものに関しては基本的には行わないような形で検討しています。ただ、やはり３密を回避しながら、また外部からの講師をどれだけ呼べるかというのは注意しながらというふうに考えてありますが。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"これからまた、状況がどうなるかというのも、まだ年度途中ですし分からないところがありますので、その都度見ていただきながら、オリンピック・パラリンピックに関しては延期ということが発表されましたので、そういった形で今回、６月の補正のほうに出していただいたのかなと思っているのですけれども、子どもや保護者の方のお考えですとか、そういったところを中心に捉えて。","respondent":"工藤指導課長","answer":"伝えていただく内容というのは、当然そういったことでも児童・生徒には伝わるところはありますので、そういうふうにできる限り、実施はするのですがその中身についてはやはり効率よくというところを、視点に持ちながら進めたいというふうに考えてあります。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"それから今、ひとり親世帯臨時特別給付金の質問が随分出ていましたけれど、先ほどのご説明の中で、追加給付については今年の２月以降、減少した１か月の収入を１２倍して、昨年１年間の分と比較し減少していれば対象になるというような感じで受け止めたのですが、仮に２月以降とすると、先ほど支給は年度内を目指すということになっていましたが、この２月以降どこまでの収入を見て。","respondent":"篠田学務課長、三ッ橋子育て応援課長","answer":"給食の関係ですけれども、今回対象となる６０事業者〔翌日「４５事業者」と答弁訂正あり〕につきましては、教育委員会のほうで３月分に各学校がどれだけの事業者に発注したかというのを把握していますので、今回この制度化を受けまして。私先ほど、あべ委員との質疑の中で、３月末までを申請の締切りといたしましたと言ってしまいましたけれども、ちょっと交付金の関係で２０２１年の２月末を給付金の締切りとしますので、訂正いたします。申し訳ありませんでした。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。よく分かりました。ぜひよろしくお願いします。ただ、心配なのは、一応コロナの影響によりと本当はなっているから、その先のことは分からないわけだけれども、なるべく早く出したいのだけれど、ただ、第２波で影響を受けたものも対応できるんだよというようなことが分かるようなニュアンスも含めて、いろいろ周知をしていただきたいと要望いたしまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"せお委員","kind":"質問","question":"すみません、１点だけお伺いしたいのですけれど、保育園、幼稚園や学校での健康診断のお話がたくさんあったと思うのですが、健康診断をする際の手順といったものというのは、校医とか園医に任せているという感じでよろしいでしょうか。","respondent":"吉田保育施設調整担当課長、篠田学務課長","answer":"ただ、今後３密を防ぐというところにつきましては、健診医と現場で調整いたしまして、なるべくよい方向で健診のほうができるやり方で進めていきたいと考えています。学校における健康診断ですが、通常はそれぞれの学校で用意した部屋の中で、やり方自体は、健診項目に関しては当然法律の規定があって、何をしなければいけないというのがあるので。","id":"exchange-035"},{"speaker":"せお委員","kind":"質問・要望","question":"コロナ前なのですけれど、というのも、ちょっと保育園の健康診断をのぞいたら、先生によって違うとは思うのですけれど、ちょっと昔のベースンに水を入れて手をすすいでいたりという先生がまだいらっしゃったので、さすがにコロナのことで、先生たちも気をつけてくれているとは思うのですけれども、しっかりしたマニュアルなどを再度確認していただいて、感染症対策、コロナだけではないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問","question":"すみません、１つ聞き損ねておりました。給付金に関係して、外国籍あるいは日本語が十分に理解できないご家庭への周知方法をどのようにお考えでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"確かに委員ご指摘のように、外国籍の区民の方もいらっしゃいますので、例えばホームページ上で工夫するなど、あとは問合せがあったときに対応していこうと考えています。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問・要望","question":"ちょっと足りないと思います。今のお答えでは不十分だというのは、多分所管のほうでもそう思っていらっしゃると思います。そこまですごい数字にはならないと思います。幼稚園、保育園そして学校、あるいは保健所などでも把握されているご家庭はあるかと思いますので、そうしたところとぜひ連携を取って周知をしていただきたいと思うのですが、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"関係する所管部署と連携しながら、外国籍の方にもきちんと申請していただけるように周知してまいります。","id":"exchange-038"},{"speaker":"芹澤副委員長","kind":"確認","question":"幾つか確認したいのですが、まず学校ＩＣＴのタブレットの活用についてで、２万４,０００台の基本的には同一機種を選ばれるということかと思うのですが、このうち１,０００台を取り急ぎ配備するというものも、これから残りの２万３,０００台と同じ機種を使っていって、どこかで返還するというものではなくて、一緒に使っていくのかということ。その場合どういったソフトになるのかを教えてください。","respondent":"篠田学務課長","answer":"ただ、予定ではそれまでには区のほうで１人１台の配備がされているという前提ですので、そちらの対応は大丈夫なのかなというふうに考えているところです。それから、ライセンス料の関係です。","id":"exchange-039"},{"speaker":"安藤委員","kind":"意見","question":"賛成なのですけれども、内容については区民にとっていい流れですので賛成なのですが、ちょっと若干意見を言いますと、ひとり親世帯の給付金の周知については様々な議論もありましたし、工夫をしていただいて、改めてしっかり行うことをお願いしたいと思います。感染症対応で今、学校現場が消毒や７時間授業の対応に伴う授業準備が大変になっているなど、現場の負担がかなりなものになっていると思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/329346?Template=document&Id=5006#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":36271,"voices":148}},{"id":"r02-20200629-5","meetingId":"r02-cm06","date":"2020年6月29日","dateIso":"2020-06-29","committee":"総務委員会","time":"午前１０時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件抜き出しています。","topics":[{"id":"topic-01","title":"案審査を行います。 予定表では、(1)第４０号議案からの審査でありますが、会議の運営上、順番を入替え審査を行います。 まず","agenda":"案審査を行います。 予定表では、(1)第４０号議案からの審査でありますが、会議の運営上、順番を入替え審査を行います。 まず","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"契約金が１１億円余から６００万円余の減額ということで、もともとの金額からしてみると、金額的には小さい変更だということなのですけれども、これは今までの進捗状況や今後の工事の見通しなどを立てて、適宜確認しているのでこういう変更も可能といいますか、対応ができるといいますか、ちょっとその辺のところをご説明いただけますか。","respondent":"松本河川下水道課長","answer":"この変更につきましては、各段階で確認をしています。そういった確認の中で、当初の設計と差異が生じたものについて変更しています。工期は、７月１６日までということで、来月完了となりますので、その前に終わっている工事全てについて、今回、変更した状況となっています。","id":"exchange-001"}]},{"id":"topic-02","title":"第４９号議案 第一日野小学校擁壁改修その他工事請負契約","agenda":"第４９号議案 第一日野小学校擁壁改修その他工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"私も第一日野小学校の歩道橋だったり、擁壁だったりを直接見てきましたけれども、結構な高さがあるなと思い、工事そのものは必要だと考えています。ただ、１８ページの資料で、左側に斜めに線が入っている、この線は放射２号線の計画線だと思いますが、この工事を行った後に、放射２号線計画に協力するため教育財産を都に売るという計画なのかどうか、その点だけ確認させていただきたいと思います。","respondent":"東野経理課長","answer":"こちら１８ページの左側の線は、委員がおっしゃるように放射２号線の計画線です。こちらの第二グラウンドの工事に合わせまして、計画地のところにつきましては、都へ売却を予定しています。こちらは本年の予算特別委員会でも審査を行っております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"放射２号線は、地元住民や大学も含めて強い反対の声があり、とても理解されている事業ではありません。その事業に品川区が協力をするというのはやめるべきだと思います。最後に１点だけ、放射２号線の部分と学校との境界線というのでしょうか、ここはあまり高低差がない部分だと思うのですけれども、どういう構造になるのでしょうか。","respondent":"小林（道）学校施設担当課長","answer":"工事内容につきましては、全てやり替えのときに、要綱に沿って、まず接道緑化があります。道路の接道緑化を行うということで、今現在、放射２号線の通りの面に、接道緑化、緑化帯を設ける予定で計画をしております。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"１７ページの工事内容で、北・東・南・西側擁壁改修とありますが、特に西側とか、あと南側は、フラットだと思うのですけれども、これもやっぱり擁壁というくくりで工事をするのでしょうか。それと、今回、これを改修するに当たって、セットバックを全方向でされると思うのですが、セットバックして、どれくらいグラウンドが小さくなるのか、もし分かれば教えてください。","respondent":"小林（道）学校施設担当課長","answer":"そのときに擁壁も一緒に築造したりとかしていきます。グラウンドの大きさにつきましては、多分、現状よりは、今言ったようにセットバックしていきますので、数字的には、約２割ぐらいは小さくなってくると思います。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"ごめんなさい、その接道緑化について、知識がなくて分からないのですが、学校の施設として道路と接するところは緑化をするという理解でよろしいのでしょうか。接道緑化ということで緑化はいいとは思うのですが、学校の施設として道路に接するところには接道のための緑化が必要ということで、今回はその土地をそのための空間に使うという理解でよろしいのでしょうか。","respondent":"小林（道）学校施設担当課長","answer":"そのために今回はそこの部分を除いて、二重投資を避けるべきだとも思いますので、そういうところでも敷地内で建設をするというところが妥当だと思います。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"そこを接道緑化のための敷地に使うのは大丈夫ということか、そういう感じなのでしょうか。","respondent":"小林（道）学校施設担当課長","answer":"都市計画道路放射２号線の部分は建築基準法上の道路になりますので、現状は周囲４面が道路に接しているという解釈です。その中で接道ということで、道路に面しているところについて、接道緑化が必要になってくる。これも基準で、何％とかいろいろ決まっています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"だとしたら、ここの部分は、特に老朽化した擁壁の改修というよりも、むしろ東京都に道路事業として協力するためにセットバックするという工事になるのでしょうか。先ほど、セットバックというお話があったので、その部分だけ工事しなければグラウンドの広さはその分だけ残ると、そういう考え方は技術的にもできないものなのか、その点を伺いたいと思います。","respondent":"小林（道）学校施設担当課長","answer":"擁壁の安全性について確認ができないというところで、教育委員会としては、擁壁を改修するということを決めたところです。その後に放射２号線とか、要綱に基づいたセットバックだとか、いろいろなものがありますので、法等に沿って工事を計画しています。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"ということは、放射２号線に接している擁壁もその老朽化が改修工事を行う理由になるのでしょうか。","respondent":"小林（道）学校施設担当課長","answer":"そのとおりです。周囲４面の擁壁は、低いところだと、３０cm位からあるのですけれども、ひび割れ等が確認できたので、周囲４面全てを改修するという判断をしたところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"反対したいと思います。理由は、工事自体は擁壁改修を含め必要なことだと思いますし、ぜひ安全に進めていただきたいと思いますが、一方で、やはり強い反対の声が挙がっている放射２号線整備に協力するものだと思いますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークとしては、やはり放射２号線のことはどうなのかというのはありますし、近隣からもそういうお声はたくさん頂いています。ただ、この擁壁自体は、私も見ましたけれども、結構危ないかなというようなところも、素人目に見てもありましたので、この工事自体は賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-03","title":"小学校校舎・幼稚園園舎改築その他工事請負契約、(8)第５１号議案 浜川小学校校舎・幼稚園園舎改築その他機械設備工事請負契約","agenda":"小学校校舎・幼稚園園舎改築その他工事請負契約、(8)第５１号議案 浜川小学校校舎・幼稚園園舎改築その他機械設備工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"事故なく、ケガなく進めていただきたいと考えていますが、この浜川小学校・幼稚園園舎改築その他工事は規模が大きいので、ここで伺おうかと思っていたのですけれども、コロナ対策と熱中症対策は契約金額にどのように反映されているものなのか、その点を伺いたいと思います。","respondent":"小林（道）学校施設担当課長","answer":"コロナ対策、熱中症対策につきましては、経費の中にそれぞれ含んでおります。それぞれのＪＶが責任を持って対応するというところになっております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"コロナ対策と熱中症対策が含まれているということですけれども、具体的にどのような対応をとるのか、ちょっとご説明いただきたいと思います。マスクも熱中症との関係で、それぞれ現場の安全第一で判断がされるべきだとは思いますけれども、やはり心配なところがあるのです。コロナ禍の下、初めての夏を迎えるという意味でも大切なことだなと思っているのですけれども、いかがでしょうか。","respondent":"小林（道）学校施設担当課長","answer":"そこで、まずはコロナ対策として、マスクは原則付けるのですけれども、ほかに医療従事者がフェイスガードを付けておりますけれども、マスクには、マスクガードといって、プラスチックのフェイスガードのマスク用というものがありますので。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろ対応をとられているということですけれども、現場の方とよく協議しながら、安全に、事故なく、ケガなく進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"工期が約５年間ですか、令和７年までで、すごく長いと思うのです。さらに付け加えれば、同じ業者がこういうふうに出てこなければいけないということは、品川区の入札に参加する業者が少ない、ということは、品川区は嫌われているのですかと逆に思ってしまうのですけれども、もっと入札に参加できるような方向性、仕組みは作れないのですか。","respondent":"小林（道）学校施設担当課長","answer":"ほかの区で不調ということもいろいろ聞いておりますけれども、品川区は不調にならずに、それぞれの業者がＪＶを組んでくれますので、そこら辺までは私のほうで把握はできませんけれども、不調にならずに済んでいるというのは、品川区の業者の力があってなのかと考えています。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"確かに仕事が終わっているからこっちへ関われるということもあるとは思うのですが、やはり我々も総務委員会で何度か確認していますが、できるだけ地元業者を育成する、それから、経営を継続してもらうというように育て上げるということがやはり基本理念にあるわけですから、できるだけ多くの業者が入札に参加できるように、そして、順番とは言い方が悪いか。","respondent":"東野経理課長","answer":"考え方としては、こちらの要綱に従った発注を今後も続けていきたいと思っているところです。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ。品川区は財源的にもありますし、支払いに前払い制度もあって、業者にとってはこの上なくいい仕事が受注できる環境にあると私は思います。そういう中でもっと多くの業者が参加しやすい、参加できるような仕組みにして、多くの区内業者を育成するような仕組み作りを今後も考えていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"何点か伺いたいのですが、最初に、こういう図面の見方が、私、よく分からないので教えていただきたいのですが、学校とか幼稚園、保育園の場合、もし何かあったときの避難経路というのがすごく私はいつも気になって、最低２方向の避難経路は確保されているということなのですが、昇降口と職員玄関で２方向というような感じでよいのでしょうか。それと、外の非常階段というのは、どうなのでしょうか。","respondent":"小林（道）学校施設担当課長","answer":"２方向避難につきましては、委員おっしゃるとおり、屋内階段、屋外階段を利用しての２方向避難等を検討しております。","id":"exchange-017"},{"speaker":"吉田委員","kind":"提案","question":"静電気の問題はどうしても聞こえてきます。それからもう１つ、前に環境課に伺ったら、学校によっては改築のときにトイレの水に雨水を利用できるような設備を付けるのですけれども、環境課としては提案するが、決めるのは担当の所管だということで、今回はそれは難しかったということなのでしょうか。給水設備というのはあるのですけれども、それは違うのか、その辺も確認させてください。","respondent":"小林（道）学校施設担当課長","answer":"それとあと、トイレでの雨水の利用につきましては、雨水をためて、ろ過、消毒をした後、トイレの洗浄に使用する計画で今現在進めております。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"太陽光発電と太陽熱利用の違いは知っているのですけれども、図面に太陽光パネルは出ているのですが、太陽熱はどのように、太陽光パネルとの一体型で熱利用もできるということなのでしょうか。その辺をもう１回お願いします。","respondent":"小林（道）学校施設担当課長","answer":"この装置はそれぞれ別々です。それを屋上に設置します。これについては、太陽熱のほうは、図面に全部書いてしまうとかなり細かくなります。１つの建物を造るわけですので、すごい細かくなってきますし、今回は入札の経過ということも含めて、概要ということで多少絞っております。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"再生可能エネルギーの利用がすごい進んでいることは評価したいと思います。再生可能エネルギーの利用が、実は品川区はすごい進んでいるということは、私、資料で確認していて、もうちょっと自慢してくれてもいいのになというぐらいですので、ぜひそれは今後も進めていっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"湯澤委員","kind":"質問","question":"それは仕方がないことかもしれませんが、この工事がどういったスケジュール感で行われるのか。この間に児童はどのような形で授業を受けて、また昼休み等はどういった形で過ごすのかということを教えていただければと思います。ちょっと細かいのですけれども、図面にサービス門とあるのですが、これは分からないので、サービス門というのはどういったものなのかも教えていただければと思います。","respondent":"小林（道）学校施設担当課長","answer":"最後に、グラウンド整備工事を行いまして、令和７年頃に全てを完了する予定で、現在、進めております。２点目のサービス門はバックヤードで先生方が使うところとか、給食の車等が入ってくるとか、学校のエリアと違うところについてサービス門という呼び名で記載しています。","id":"exchange-021"},{"speaker":"湯澤委員","kind":"質問・要望","question":"本当に学校は子どもたちのためのものでありますので、ぜひ子どもたちを最優先に考えて工事を進めていただきたいと思います。工期が長いので、工事に携わる方々の気のゆるみがないように、ケガ等なく安全第一の工事を行っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"松澤委員","kind":"確認","question":"人工芝のことで１件、確認をしたいのですけれども、先ほど、吉田委員からもお話がありました人工芝化はすごく子どもたちが喜んでいい反面、制約が多くて、荏原第五地区ですと、戸越小はおかげさまですごくいい人工芝を敷いていただいて、子どもたちも大変喜んでおりますが、荏原第五地区でやぐらを組む関係上、そこにやぐらを置けないので使えなくなってしまいます。","respondent":"小林（道）学校施設担当課長","answer":"委員おっしゃるとおり、やぐらを組むだとか、先ほども花火だとかいろいろありましたけれども、土ではないので、地耐力、どれだけ踏ん張れるかということがあるのですが、先ほども粉塵等で近隣にご迷惑をおかけしているというところも考えて、いろいろな方面から考えて。","id":"exchange-023"},{"speaker":"松澤委員","kind":"意見","question":"人工芝も、今はすごい技術が上がりまして、チップがなくてもできるようなものが今はできている中で、切れ端といいますか、人工芝がちょっと切れてしまうことで出るごみが問題になっているといった部分で、校舎の汚水を流す、雨水が出るようなところに、そういう網を設置するような、そういうようなものは学校施設の中で考えているものはありますか。","respondent":"小林（道）学校施設担当課長","answer":"それとあと、委員がおっしゃるとおり、何かで覆えないかということも含めて、今現在、検討しております。","id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。１点だけ確認します。今回、この浜川小学校は居ながらの工事ということで、長い工期になっております。この間に災害があった場合、ここは学校避難所として使用されているかと思います。ちょっと今回の論点からずれてしまうかもしれませんが、災害があったときの対応というのは、どのように連携をとられていくのかということだけ確認させていただきたいと思います。","respondent":"小林（道）学校施設担当課長","answer":"避難所としては、当然、体育館が壊れたときには避難所ではなくなりますので、これについては防災課とも綿密な打合せをして、建設中はそこから外してもらうというところで現在進めております。","id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"実際はないものなので、なくなってしまうところに避難はできないということになるかと思いますが、いつ起こるか分からない、豪雨もありますし、地震もあります。しっかりまたそこは連携をとって進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-04","title":"第５３号議案 マイスクール八潮空調設備改修工事請負契約","agenda":"第５３号議案 マイスクール八潮空調設備改修工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１点だけ。金額は１億７,０００万円余ということですが、八潮団地特有の熱供給システムと、この工事の内容や価格に何か関係があるのかないのか、そこを伺いたいと思います。ちょっと高いような気もするし、八潮団地には独自の熱供給システムがあるではないですか。それと今回の工事の関係だけご説明いただけますか。","respondent":"小林（道）学校施設担当課長","answer":"それとあと、基本的に、東京熱供給は、システム上、ワンフロア全てを使用しますけれども、時間外で個別に例えば５時とか、夜間だとか、部分的に部屋で冷暖房を使用する場合は、不経済になりますので、そこでは個別空調を部分的に付けております。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"そういう八潮特有の構造によって、価格はむしろ下がるのか、それとも上がるのか、そういう関係はどうなのですか。ぜひ下がってほしいとは思いますけれども。","respondent":"小林（道）学校施設担当課長","answer":"価格がどうなのかということは、工事自体においてそのプラスアルファのお金は出てきます。ただ、熱供給システムを使いますので、実際はそういう比較を私のほうでしたことはございませんけれども、そちらのほうで精査というか、それが考えられるのかです。","id":"exchange-028"},{"speaker":"新妻副委員長","kind":"提案","question":"すみません、ご説明ありがとうございました。今回、マイスクール八潮の空調設備改修工事ということで提案されております。ここは元八潮北小学校で、現在、明晴学園も入る施設になっているかと思います。今回、ここのマイスクール八潮だけでなく、明晴学園のほうの空調設備も併せて改修されるのかというところを確認させてください。","respondent":"小林（道）学校施設担当課長","answer":"ここの建物全体が、できてから３７年間、空調関係については、部分部分に手は入れているところではありますけれども、３７年間使っているということで、不具合が生じ、今現在も部分的に改修して、３７年間使用していたのですけれども。","id":"exchange-029"}]},{"id":"topic-05","title":"令和２年陳情第２０号 庁舎建て替えを住民参加で進め情報公開することを求める陳情","agenda":"令和２年陳情第２０号 庁舎建て替えを住民参加で進め情報公開することを求める陳情","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"前回の事務事業概要のときも、Ｄ案がいつどのように決まったのかと伺いましたが、今と同様、経理課で議論して行財政改革特別委員会に報告した。これでは全くいつどこでＤ案が決まったのかという問いに答えていないのです。なので、改めて、Ｄ案がいつどこで決まったのか伺いたいと思います。そもそもこのＤ案が、課長はいつどこで決まったということを知っているのか、そのことについても伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"今のＤ案のことですが、Ｄ案につきましては、現状、最良の位置であるということで区として考えております。今はまだ決定したということではなく、適地であるというふうに考えて検討を進めているところです。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"８月の経営会議で決められたということですが、どのような経過で８月の経営会議で決められたのか、しっかりとご説明いただきたいと思います。併せて、区とＪＲ東日本との間でまちづくりについての協定書を結んでおりますけれども、この協定書が結ばれてから、いわゆる４候補、そしてＤ案の検討が始まったと、そういうスケジュール感になるのかも併せてお伺いしたいと思います。","respondent":"濱中庁舎計画担当課長、多並都市開発課長","answer":"経営会議は、候補地検討の視点や候補地の位置、また候補地の評価等を総合的に勘案して、Ｄ案でいきたいというところでご報告をして了承を得たところです。区としましては、広町地区において区が持つ土地の再編も含めて、この中で検討していくということですので、新庁舎の建て替えとも連動が高いということで、そういう意味では、連携しながら進めていくべき内容という認識であります。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"全くかみ合っていないのです。庁舎は区民のものですから、その検討過程も含めて、しっかり区民に公開して議論を進めるべきだと思います。この間、非公開の理由を、議論がまだ未成熟のものを公開すると区民が混乱するからとか、あと、ＪＲ東日本の利益に関わるものだからとか、こうしたことを理由にしてきましたけれども、なぜ混乱するのか、区民にどのような混乱が想定されているのか伺いたいと思います。","respondent":"濱中庁舎計画担当課長、多並都市開発課長","answer":"区民への情報提供ですが、庁舎の機能検討がまさに今年から始まっておりまして、庁舎機能検討委員会では、今後、公募区民や関係団体等の方から多くのご意見を頂きながら、また、庁舎機能検討委員会の結果につきましては。そのようなまだ公開していない情報をお出しできないのと、あとは、いろいろな法令であったり、協議先がある、そのような先との協議がまだ未成熟の段階でお出しするということは、非常に混乱を生じるだろうと。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"非公開の理由、それはもう前から示されているのです。だから、政策形成過程の情報と言えばいいのでしょうか、それが公開されると、一体区民にどのような混乱が出るのか。私は、区民のための庁舎ですから、検討過程を明らかにして、よりよい意見、またアイデア、取り入れれば取り入れるほどいいものができると考えていますので、ぜひその姿勢を変えていただきたいと思いますが、いかがでしょうか。","respondent":"濱中庁舎計画担当課長、多並都市開発課長","answer":"今年度予定されます庁舎機能検討委員会では、委員の方に現状と課題や経緯等も知っていただいて、これから求められる庁舎機能について広くご議論をいただきたいと考えています。もう１つのＪＲ東日本の利益のところですけれども、いわゆる情報公開する前の情報、要するに、外に公開しないことを前提に情報を頂いて一緒に検討していくということですので、それが前提となるものです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"区民に具体的にどのような混乱があるのですかと聞いても、結局、何も答えられないのですね。何も区民は混乱しません。最後に、先ほどから言っている庁舎機能検討会ですけれども、やはり質疑を充実させるためにも、委員への資料提供、開催前に資料の提供があると思いますけれども、少なくとも１週間前には提供して、資料を読み込む、そうした時間を保証すべきだと思いますけれども、いかがでしょうか。","respondent":"濱中庁舎計画担当課長、多並都市開発課長","answer":"庁舎機能検討委員会では、現状と課題や経緯等を整理して議論をしていただきます。事前資料に関しましては、配付時期等を委員会でも検討いただいて、適切な時期にお示ししていきたいと考えています。先ほどのＪＲ東日本との協議の件ですけれども、この広町地区のまちづくりを考える上で、やはり品川区の土地、区有地が分断している状況、また、ＪＲ東日本の土地も駅舎との関連性ということであれば、やはり全体的なまちづくりの中で。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひＤ案に至った検討経過をしっかりと明らかにしていただきたいと思います。庁舎機能検討委員会のほうですけれども、適切な時期に資料を渡したいということですが、もう開催通知が届けられておりますけれども、私は１週間前に提供すべきだと思いますが、この点についてはっきりとお答えいただきたいと思います。だから、１週間前の提供をぜひやっていただきたいのですけれども、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"委員からご提案ありました資料の事前提供ですが、今、資料作成中ですので、できる限り、委員の方々が審議しやすいように、配付資料の事前提供等を検討してまいりたいと考えています。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"できる限りとか、事前検討とか、では、まだ決まっていないということですか。決まっていないのだったら、１週間前に提出できるように準備していただきたいのですけれども、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"配付資料等は、委員の方々が議論しやすいように、今、作成中ですので、今後、資料作成に努めてまいりたいと思います。","id":"exchange-036"},{"speaker":"中塚委員","kind":"提案","question":"先ほどからの答弁は、やっぱり説明としては不誠実だと思います。決まっていないのだったら、決まっていないと言えばいいのです。それで私が１週間前はどうですかと提案しているわけですから、いずれにしても、この陳情に書かれているとおり、Ｄ案の経過や情報公開、これはしっかりと進めていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"この陳情に関しては、全く同じ考えです。生活者ネットワークも情報公開を求めました。非公開の理由が、もう少し丁寧に、私、持ってくればよかったですけれども、持ってこなかったのですが、丁寧に理由が書かれていたかと思います。それは、全て納得できるものではありませんでしたので、不服申立をしました。不服申立に対して弁明書が来ました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"その段階です。いつまでに出すようにというのが４月末の日程が指定されていて、月末まではいっていなかったか、日程が指定されておりましたので、その日までに出しました。そこから既に２か月たっています。再弁明の余地がないということでしょうか。それに対しての再弁明書が、私たちは１か月弱の日程で出すように求められて、その期日を守りました。２か月たっています。それを私たちは求めております。","respondent":"多並都市開発課長","answer":"再弁明書または審議会への手続を含めて、新型コロナウイルス感染症の関係があって、少し中断した期間もありましたけれども、今、それは広報広聴課が主体となりながら、その時期も含めて検討している段階であります。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"多分そうだろうなということで催促しなかったのですけれども、せめてそういうご説明は、どんなに忙しくてもあってしかるべきだったのではないかというふうに思います。やっぱりこの姿勢は、この陳情に限らず、改めていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問・要望","question":"このたびの情報公開することを求める陳情ですけれども、先ほどからお話を聞いていまして、情報公開するにも難しさがあると思うのです。そして、陳情の項目で、庁舎建て替えについて、Ｄ案はどのようにして決められたのですかと、これは私も行財政改革特別委員会に在籍しておりまして、いろいろ案が示されました。それに対して、何しろとりあえず進むのだと、ただ、今後、どういう方向になるか分からない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"簡単に済ませます。思い出しました。反論書です。この陳情の方がどのような記録を求めておられるかは、これだけでは分からないのですけれども、生活者ネットワークとしては、議論の経過が分かるものを出してほしいというふうに言っています。だから、区としてこういう議論の経過をたどりましたというようなものが分かれば、何も逐語録を出してほしいというところまでは求めておりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"湯澤委員","kind":"質問","question":"結論を出すでお願いします。ただ、細かな交渉内容においては、双方が信頼関係の下に情報公開をしておりますので、企業が自社情報を公にしないことは当然あるかと思いますが、庁舎建て替えというのはやはり区民のために行っているプロジェクトでありますので、公開できるものに関しましては、丁寧な説明とともにしっかりと示していただき、多くの区民が納得して喜ばれるものを造っていくべきだと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問","question":"本日結論を出すということで、不採択でお願いいたします。理由は、これから庁舎計画がある中で、庁舎機能検討委員会の中でこういった議論をしていただければと思いますので、今回の態度としては不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ただいまご説明がありましたとおり、平成３０年、経理課で検討された、議論もしたと。その後、令和元年８月の経営会議で承認を得た。今後に関しまして、しっかりと誰もが閲覧できる状態にしていただく中で、どういう形で庁舎の建て替えが進んでいったのかということが分かるように公開をしていただきたいということを求めて、今回の陳情に関しましては不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"本日結論を出すということと、採択でお願いします。理由は、先ほどから述べていますけれども、Ｄ案に決定された経過があまりにも不透明だということと、示されている情報が黒塗りと、これはやはり問題だと思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問・要望","question":"私も本日結論を出すということと、不採択でお願いしたいと思います。相手に相当配慮しなければ、なかなか事は成就しないと思います。ただし、今後、庁舎機能検討委員会も含めて、しっかり決まったこと、そして共同事業者の了解の下で、報告していいことがありましたら、それはやっぱり正確にしっかりと区民に報告を逐一していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"生活者ネットワークとしても、この公開を求めておりますので、もしかすると、公開の中身については、逐語録を全部出せというふうにもおっしゃっているのかもしれませんけれども、そういうことではなく、経過が分かるものをちゃんと区として記録に残し、それを公開するということであれば、事業者の利害にも決して反するものにはならないと思います。ぜひ採択をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-06","title":"第４０号議案 職員の特殊勤務手当に関する条例の一部を改正する条例","agenda":"第４０号議案 職員の特殊勤務手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"きっと法律の縛りや関係性もあって、こういう仕組みにならざるを得ないのかなとも察しますけれども、様々な感染症がパンデミックとかになったときに対応できるような、そういう仕組みも考えていくことが必要ではないかと思うのですけれども、その点についてのご見解も伺いたいと思います。","respondent":"黒田人事課長","answer":"国が検疫等を始めた時期が１月の下旬ということで、１月２８日から適用という形をとっておりまして、今回、区では国のいわゆる検疫業務の後に、様々な保健所での業務が発生しということで、実際には２月以降にそういった業務に対応してきているという中では。","id":"exchange-049"},{"speaker":"中塚委員","kind":"意見","question":"いずれにしても、遡及して適用ということですので、これはもちろん賛成したいと思いますけれども、感染症対策は第２波への備えというところで、全体像の解明やワクチンの開発などもまだ大分時間もかかりますけれども、常設の感染症対策というものも必要なのかなと、意見だけ述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"先ほどご説明ありましたが、３番の支給対象となる業務については、具体的には条例制定後に規則で決められるということなので、そちらを待たなければいけないのかもしれないのですけれども、上の欄と下の欄で言うと、具体的に、例えばこういう業務がこれに当たるというようなことがあれば伺いたいと思います。","respondent":"黒田人事課長","answer":"項番３の表の上段の作業１日当たり４,０００円に該当する業務として現在検討しておりますのは、区内で患者が発生しますと、その直接対応ということで、区内でも直接的な疫学調査ということで、現地でいろいろ調査をしたりということであれば、要するに。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"こういうお仕事はストレスもすごくかかると思いますので、３,０００円と４,０００円の線引き、あまりにもお金のことばかり言うようですけれども、どこでどういうふうな判断をされるのでしょうか。いろいろ出てくるではないかと思うのですけれども、規則を定めるに当たって、今検討されているようなことがあったら、お話を伺いたいと思います。いかがでしょうか。","respondent":"黒田人事課長","answer":"今、若干変わっていますけれども、そういった中で検査で陰性化確認に対応したということで、ややリスクが下がった場合については３,０００円の区分というふうに考えてあります。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"具体的には、また規則とかで確認させていただきたいというふうに思いますが、質問の意図としては、なるべく、いろいろなこういうことに関する手当などについては、どうしてあの人には手当が付いてと、自分も同じぐらいリスクが高いのにという人がどうしても出てきてしまうようなところはあって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"須貝委員","kind":"質問","question":"すみません、ちょっと聞き逃していたら恐縮なのですが、今回の職員の特殊勤務手当に関する条例ですけれども、これはウイルス名ごとに別々に、そのたびに条例を定めないと駄目なのですか。細菌性とかウイルス性とか様々種類があると思うのですけれども、そういうものを１つの条例で全部包括できるという、そういうことではないのでしょうか。教えてください。","respondent":"黒田人事課長","answer":"それに応じて同じように対応していくというふうに考えているところです。","id":"exchange-054"},{"speaker":"須貝委員","kind":"質問","question":"そのときそのときに新たなものをまた作り出して、条例を作らなければいけないというのは不思議な気もします。インフルエンザ等とか等を付ければ、毎回こういうふうにしなくてもいいのでしょうけれども、ただ、金額や条件等がいろいろ変わってくるからこうなるのでしょうか。包括的なものはないというふうに考えていていいわけですね。","respondent":"黒田人事課長","answer":"そういった意味では包括的に対応されるというふうに考えております。現時点では、国も特例として定めておりますので、区も同じように定めているです。","id":"exchange-055"},{"speaker":"湯澤委員","kind":"質問・要望","question":"４,０００円、３,０００円の手当額の違い、考え方について、先ほど陽性と分かっている人と接しているかそうでないかというご説明がありましたけれども、きちんと、この方だったら手当が４,０００円となる、３,０００円となるというのが明確に分かれているのかということも教えていただければと思います。","respondent":"黒田人事課長","answer":"これまでの実績ですけれども、２月から５月の末までのところの実績については、既に陽性、陰性の区分も出ておりますので、上段に当たる方が約９０件、下段に当たる方が１６件ということで、現在おおむね１００件程度というふうに把握してございまして、今回。","id":"exchange-056"},{"speaker":"湯澤委員","kind":"意見","question":"ぜひ感染リスクがある職員の方が意欲を持ってこれからも勤務に当たれるように、そういった施策を取り組んでいただければなと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"}]},{"id":"topic-07","title":"第４６号議案 東大井保育園・児童センター改築その他工事請負契約","agenda":"第４６号議案 東大井保育園・児童センター改築その他工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"２方向避難をどういうふうに確保されているのか、それを伺いたいと思います。それから、園庭は、どれぐらいの広さなのか。先ほど、学校施設は今はみんな人工芝生化の方向と伺いましたけれども、保育園に関してはどうなのかということと、それから、一般的に保育園とかを見に行くと、いろいろなことへの配慮が進んできていると思うのです。","respondent":"小林（剛）施設整備課長","answer":"そういった中では、今ご指摘ありましたように、コンセントの位置とか、あるいは子どものいたずら防止、例えば柵を作るとか、ガードを付ける、そういったことも逐次知識というか、情報を蓄えながら、今、設計を進めているところでございまして。","id":"exchange-058"},{"speaker":"吉田委員","kind":"確認","question":"この北側というか、上のほうにあるこの階段は、屋上から外階段ということで、一方向としてはここから逃げられるようになっているということで、確認させてください。それから、人工芝は流れとしてしようがないのでしょうか。さっきの外階段のことだけ教えてください。","respondent":"小林（剛）施設整備課長","answer":"階段ですが、ご指摘のとおり、屋外階段が北側に１か所、それから東側に１か所ありますので、そちらを使っていただいて避難していただくことになるかと思います。","id":"exchange-059"},{"speaker":"須貝委員","kind":"質問","question":"参考にお聞きしたいのですが、今、新型コロナウイルス感染症が問題となっております。その中で、今回、新型コロナウイルス感染症対策を施したのかどうか。今まで、従来の建物の建て方、構造、様々あると思うのですが、今回３月から様々な問題がありましたけれども、新型コロナウイルス感染症対策のために、構造の一部を変更しましたとか、建て方に何か変化がありましたとか、そういうことはあるのでしょうか。","respondent":"小林（剛）施設整備課長","answer":"換気設備につきましては、この新型コロナウイルス感染症に関係なく、関係法令に基づきまして、必要に応じて設置が義務付けられておりますので、本施設につきましても換気設備と併せまして、各保育園の保育室には、これは各保育園、従来からもそうなのですが。","id":"exchange-060"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"開園に向けてその影響が抑えられているのかどうかというところの確認が１点と、あと、この地図にありますとおり、区役所側からいきますと、第一京浜を渡って旧東海道のほうに向かう左側のところに園があるわけなのですが、非常に狭い通りの中で、工事をするときの工事車両がどこに止まって工事をしていくのかというところ、片側の車線が止められてしまうようになってしまうのか、または。","respondent":"吉田保育施設調整担当課長、小林（剛）施設整備課長","answer":"そちらは先ほど文教委員会で報告したところです。１８日に延びたことによる、こちらの本園舎の計画についての影響はないものと考えております。工事説明という観点ですが、まず昨年の９月に建物の計画に関する説明会は実施させていただきました。この後、議決後、８月中に近隣の方々を改めて対象にしました、今度は工事に関する説明会を開催する予定です。","id":"exchange-061"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。去年だったでしょうか、一旦ここは水漏れか何かで、工事が行われていたときに、やはり地元のご近所の方から、工事の音がちょっと気になるというようなお声も頂きましたので、ここだけに限らず、工事を行うときにはどこでもそういうような音が出てしまうことはやむを得ないことでありますけれども、丁寧な説明をぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ご説明ありがとうございました。１点だけ確認なのですけれども、先ほどの屋外階段は北立面図を見ると、屋上から１階まで通じているのですけれども、これは、避難階段という認識でいいのでしょうか。","respondent":"小林（剛）施設整備課長","answer":"北立面図にかいてある階段の部分ですが、これは屋上にあります児童センターの屋上広場から来る階段と、併せて３階からの児童センターの階段、両方ともこれは屋外階段という考え方で避難階段として使われる階段です。","id":"exchange-063"}]},{"id":"topic-08","title":"第４７号議案 八潮西保育園大規模改修工事請負契約","agenda":"第４７号議案 八潮西保育園大規模改修工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１点だけ。大規模改修の理由ですけれども、この間、八潮地区内の保育園をいろいろ改修してきましたが、老朽化ということですか。大規模改修の理由を伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"内装以外にも、空調設備、それからトイレ等の給排水設備、厨房等も老朽化が進んでいたところから、平成２９年の八潮わかば幼稚園を皮切りに、八潮地区を順繰りに改修工事を進めているところです。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問","question":"大規模改修ということで、内部も随分改修を行うようなのですが、いつ頃、どういう形で工事をされるのか伺いたいのと、それから、床、壁、天井、建具、家具などの更新も行われるようなのですが、材質といいますか、子どもたちの安全面とか、それから環境配慮とか、そういうことがどういうふうになるのか伺いたいのと、それから、遊具の更新ということですが、既存と同じような遊具を入れるだけなのか。","respondent":"吉田保育施設調整担当課長、小林（剛）施設整備課長","answer":"特に、今、議案として提案している工事において、その工事と子どもたちが重さなるということは一切ございません。安全に工期が終わりましたら、また今年度中に工事が終わった場所に戻ってくる予定です。扉の材質等につきましても、挟まれても痛くないような形になっているかどうかも含めて、そういったところを配慮しながら進めているところです。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろな床とか壁についても、フローリングとか、そういう配慮はされているように伺いましたので、ぜひそれで進めていっていただきたいですし、その辺についても、ここをもうちょっとこういう工夫があればという、まだこの契約上、余地があるのであれば、保育士が一番子どもたちのことも分かっていると思いますので、そのご意見とかを伺いながら工事を進めていっていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけ言わせていただきます。できるだけ多くの地元業者に落札していただくということは、これからも考えていただきたいし、多くの区内業者を育成して存続させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"というのは、建物の２階から上は住居になっておりまして、日常的には住んでいらっしゃる方がいる中での工事になるかと思いますので、そこへの配慮等をどうされていくのかということを確認をさせていただきたいと思います。それともう１点、最後に、園庭のところで区道に面する部分が崖地になっております。この崖地のところの確認というか、調査をしていただけるのかを確認させていただきたいと思います。","respondent":"小林（剛）施設整備課長","answer":"２点目の説明会ですが、新しい建物を造るのと違いまして、基本的には、今回はこの上に住んでいる方々を対象とした説明会を、まず計画に関する説明会は今年２月に行っておりますが、施工業者が決まったこともありますので、７月中に開催することで、今現在。","id":"exchange-068"}]},{"id":"topic-09","title":"第４１号議案 品川区特別区税条例の一部を改正する条例","agenda":"第４１号議案 品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"大きく９項目の変更でありますが、(6)の区民税の執行猶予について伺いたいと思います。新型コロナウイルス感染症の影響で仕事を失ったり、収入を失ったりで、区民の生活は本当に今、厳しい状況が続いていると考えています。その中で、国民健康保険料の場合は、今回、同様のケースで免除という形をとっておりますが、区民税は、免除でなく猶予とした理由は何か伺いたいと思います。","respondent":"伊東税務課長","answer":"税制全体の部分ですので、それ以上踏み込んでの改正はされなかったというふうに認識しています。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"法改正に基づく条例改正だということが前提なのですけれども、やはり今、苦しい区民の実態をしっかり見る必要があるかと考えています。今回の新型コロナウイルス感染症による経済への影響はすごい深刻ですから、来年になれば回復するというような見通しは誰も持てないと思うときに、来年度以降の支払いについて、分納や何らかの支援が必要ではないのかと思うのですけれども、区のお考えを伺いたいと思います。","respondent":"伊東税務課長","answer":"その時点の状況にもよりますけれども、鋭意、今も分割納付とかの対応は、個々、そのケースに応じて対応させていただいているところですので、そこに関しては今後の推移を見極め、その方なり、その会社なりの状況も詳しく相談を受けながら対応していこうかと思っているところです。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、今年分が猶予されて来年の支払いのときには、これが今年分です、これが来年分ですというふうな形になるのか、それとも合算して幾らですという形になるのか。延滞金のことを考えると、額が大きいほうから返したほうが延滞金はかからなくなるわけだけれども、合算して支払うことになるのか、それとも、これは今年分、これは来年分と、そういう形になるのか、その仕組みをご説明いただきたい。","respondent":"伊東税務課長","answer":"なるべく早いほう、先のものを順次支払っていただくというのは、今もそうやっているのですけれども、それは延滞金もなるべく発生しないような形での納付をお願いしていくというところで進めているところです。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言、せめて猶予は今後とも延ばしていただきたいと思うし、免除も含めて検討していただきたいと思います。私は常日頃、延滞金はおかしいと思っていますけれども、こういうときこそ、せめて延滞金はやめるとか、そういう判断はされるべきだと。区独自でやるかの議論もありますけれども、ぜひ国に対してもいろいろ意見を述べていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問","question":"幾つか言葉の説明というか、伺いたいと思います。低未利用土地を市場に出すことによって、あわさって使える土地になってというのは分かるのですが、(4)のほうを教えてください。","respondent":"伊東税務課長","answer":"ですので、優良住宅地造成と、言葉ではそういう言葉ですけれども、様々な事業、先ほどちょっとお話しした良質な住宅ストック云々というのは、それに向けての事業を行う者に対しての譲渡の場合は、これを適用していくということで、これは期限の延長ということですので。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問","question":"言葉上はそれですごくそう思うのですけれども、優良な住宅を増やしていくという。ただ、その優良な住宅地はどこに基準があるのかが分からないのです。それは、何か変な言い方で、誰がどう決めているのでしょうか。伺いたいことが分かりますか。どういうふうに決まっているのでしょうか。ごめんなさい、その辺の知識が全然ないので教えてください。","respondent":"伊東税務課長","answer":"その流れのところまではちょっと把握していないところですけれども、多分、その事業がなぜ優良住宅地造成ということを、都市計画ですとか、そういうところが判断をし、というのは、さっき申し上げたとおり、開発許可だとか、土地区画整理事業だとか。","id":"exchange-074"},{"speaker":"吉田委員","kind":"意見","question":"非常に高い所得税になってしまう。今回は、期限の延長ということですので、今まで進められてきたことが延長になるということで必要な措置かなというふうに思うのですが、その辺のことだけちょっと気になりましたので、意見だけ申し述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"湯澤委員","kind":"質問","question":"特に(2)にあります未婚のひとり親に対する税制上の措置および寡婦（寡夫）控除の見直しについてで、これもひとり親の現状に沿ったものであると考えていますが、今回、５００万円の所得制限がかけられることによって、これまで補助が受けられていたのに、条例改正によって受けられなくなる人もいるのではないかというふうに思いますが、どうでしょうか。","respondent":"伊東税務課長","answer":"それぞれ、今回いろいろと広範囲になりますので、今言った未婚のひとり親に関するところに関しては、扶養申告とかというところで申告を出していただく、会社勤めの方であれば、今年の１２月ぐらいまでに出していただくことになりますけれども、それにも解説といいますか。","id":"exchange-076"},{"speaker":"湯澤委員","kind":"質問","question":"本当に、ひとり親家庭では、少しの控除によっても、家庭の負担が軽くなるところもあるかと思いますので、ぜひその辺の周知は強くしていただければと思いますのと、それからあと、(7)にあります寄附金控除の適用というところですけれども、資料に文部科学大臣が指定したイベントのうち区長が指定したものと書いてあると思うのですけれども、区長が例えば指定しない可能性があるということなのでしょうか。","respondent":"伊東税務課長","answer":"それをもって、では、品川区が指定しないかということではなくて、その指定されたものは、そのまま品川区としても適用させるという形でいるものです。","id":"exchange-077"},{"speaker":"須貝委員","kind":"質問","question":"１点目は、(1)で、軽量な葉巻たばこの課税方式の見直しですが、これをすることによって、例えば事業者の製造メーカーは、やはり収入減になるのかと思うのですが、品川区の場合は税収、たばこ税としてどれぐらい増えるのでしょうか、教えてください。(6)、(8)、(9)は意見ですけれども、(1)の件はお答えください。","respondent":"伊東税務課長","answer":"逆に、区としては、それが１本分とかとなれば、少しは税収が上がるという理屈にはなろうかと思います。ただ、ほかのたばこの売渡し具合、いろいろあるので、難しいところです。","id":"exchange-078"},{"speaker":"須貝委員","kind":"意見","question":"本来、この時期に逆に税が上がるものなので、いろいろな政策がアンバランスで、片一方は柔軟に対応して徴収猶予とか、様々適用期限を延長しようという軽減策をとって、片一方はこうやって税が上げていくというのには、違和感を覚えたので、できるだけ多くの区民を助けていただけるよう対応していただければありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"}]},{"id":"topic-10","title":"令和２年請願第６号 政府に消費税減税を求める意見書提出に関する請願","agenda":"令和２年請願第６号 政府に消費税減税を求める意見書提出に関する請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"政府に消費税減税を求める意見書提出に関する請願ということですけれども、ぜひとも各委員におかれましては、採択をしていただいて、区民の暮らし、地域経済の力に我々が尽くしていこうではないかと賛同を私も呼びかけたいと思います。ぜひご賛同いただきたいと思います。もともと政府は１０％に上げるときに、リーマンショック級の出来事がない限り予定どおり行う、安倍首相はそう述べていたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"須貝委員","kind":"意見","question":"今回の請願ですが、私なりにも、私の会派のほうでも、どうなのかと悩みました。続いて、それによって解雇が増えて失業者も増えている。それが第一だと思うので、私は、今回の消費税減税に関しては、仮に期間を絞ってでも、今回はしっかりやるというふうな方法しかないと思いますので、皆さんにこういう請願にご賛同いただき、何とか企業を守ってほしい、そして支えてほしい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"吉田委員","kind":"質問・要望","question":"生活者ネットワークとしても、ぜひ消費税率の引き下げを品川区議会として求めたいというふうに思います。失業した人への直接的な支援というのは、この間、一般質問で求めましたけれども、なかなか難しいということのようですので、やっぱり区議会としても、この消費税の引き下げ、廃止ではなくて引き下げですから、こういう意見書は出してしかるべきではないかというふうに考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"湯澤委員","kind":"質問","question":"ただ、私、個人的にも税金を払わなくて済むならばそうしたいというふうに思っておりますが、ただ、高齢者、そして低所得者を支えたい、また自分の家族や病気になったときに助けられるためにも必要なものだと思い、税金を支払っている納税者の一人でもありますので、国は財源確保のために増税をしたのであるならば、ぜひ納税の義務を負っております私たちに対しまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"高橋（伸）委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。２０１９年末に８％から１０％になった。そのような中で国も８％の軽減税率を導入しました。そういった中で、財源の確保も重要かと思いますので、よって、国に意見書は行わず、不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"公明党は、結論を出すでお願いいたします。そして、不採択です。ちょうど前回、消費税を上げないよう求める請願が出されたときも、私もこの総務委員会に所属しておりまして、議論もさせていただきました。今後の生活の充実を図っていくためには、この消費税を活用していくというところも大事な視点であると考えておりますので、公明党といたしましては、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということと、採択でお願いいたします。今、ご意見を伺いましたけれども、様々支援事業をしているというのは事実だと思います。本来、税制度がどうあるべきかは、今回の意見書提出とはまた別の議論だとは思いますけれども、今回の意見書は消費税減税を求めるものでありますので、ぜひ一致できたらなと改めて呼びかけたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"須貝委員","kind":"意見","question":"これは百年に一度とよく言われますが、国家としては相当の打撃になっていると私は思います。もう国も都もどうしようもない、何をしていいか分からない状態に陥ります。今、社会保障費は、生活保護の方も多いですが、本当に増えていますし、これからますます増えていく、そういう危険をはらんだ状況なので、もうあとは国民の消費喚起をするしかないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"吉田委員","kind":"意見","question":"そのときも例に出しました。２割のままだと思います。もちろん利子自体がすごい少ない中で、２割とられるというのは、本当に大きな負担ですけれども、でも、それは利益が出る人、利益に対しての負担です。ほかにも本来であったらここで税金をかけるべきだろうというところにかかっていないものがたくさんあると思います。それが１０％ということで、小さな事業者にとっては本当に大きな負担です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=2172#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":63907,"voices":296}},{"id":"r02-20200630-6","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"区民委員会","time":"午前１０時００分～午前１０時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","topics":[{"id":"topic-01","title":"」を聴取いたします。 「令和２年国勢調査","agenda":"」を聴取いたします。 「令和２年国勢調査","exchanges":[{"speaker":"小芝委員","kind":"確認","question":"少し確認をしたいのですけれども、「回答確認チラシ」や8)の「提出確認状の配布」というのは、単純にポスティングという認識でよろしいのですか。","respondent":"川島地域活動課長","answer":"回答をお願いする、促すような書類、それから、また追加で提出をお願いしますというものにつきましては、ポスティングをしていただければいいと、こちらでは準備しています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"調査時期が１０月１日ということですけれども、本来いつだったけれども、コロナの関係でずれたということではなくて、最初から１０月だったのかということ。いろいろあるでしょうけれども、どれくらい配られて、どれくらい回答があるのかという平均がわかれば、前回のものを教えていただけたらと思います。","respondent":"川島地域活動課長","answer":"基準日ということです。どうも会計年度の中央の時期であるとか、一定の基準日を決めることによって、統計調査の比較をしやすくするといった理由があるということです。それから、回収率のところですけれども、国で公表している数が、ざっくり７割程度の回収率です。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうなのですね。そこら辺の見通しを教えていただきたい。調査員の方は町会、自治会の皆様のご協力のもとでということですけれども、コロナのさなかなので、集まりづらい状況だったりするのでしょうかというのを伺いたいと思います。","respondent":"川島地域活動課長","answer":"調査員の方の協力ということですけれども、説明会等でどうしても集まっていただかなければならないものについては、先ほどご説明させていただいたとおり、説明会の時間をかなり短縮しまして、コマの数を増やして、少ない人数で集まっていただくように工夫しているところです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"調査員の皆様への配慮はわかったのですけれども、調査員の皆様が応募してくる数というのは、今までと余り変わりない。コロナなので、余り外を回るとか、不安みたいなものもあって、集まりが悪かったりするかどうか。","respondent":"川島地域活動課長","answer":"失礼いたしました。私、質問の趣旨を取り違えてございましたが、調査員の数は、前回、平成２７年のときと比べますと、残念ながら町会推薦の方が８４人くらい少なくなっているところではありますが、何とか頑張って推薦していただいたということで、大変感謝しています。","id":"exchange-004"},{"speaker":"大倉委員","kind":"確認","question":"１個だけ確認で、先ほど調査員の訪問回数。そこだけ少し確認で教えていただければと思います。","respondent":"川島地域活動課長","answer":"今までの調査ですと、少なくとも３回行って、それでも面接できない場合はポスティングしてくださいという指示が国からあったところですが、今回、最低でも２回はインターホンを押していただきたいというのが区からのお願いです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"私は、これは制度だからしようがないかなという思いがあるのですけれども、ずっと国勢調査をやっていて、５年置きでしたか、１０年前置きでしたか。伺うのは、１０年置きのほうが大きくて、５年置きのものはそうでもないみたいなことを伺っているのですけれども、その辺についてをお伺いします。","respondent":"川島地域活動課長","answer":"１０年置きのほうが本調査という位置づけで、調査項目が２項目増えるという形になっております。今回の資料では調査項目が１９項目ということですが、前回は１７項目ということで、その辺の変更があるというものになります。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論なのですけれども、区がどうしようという話ではないと思うのですが、会えなかったらポスティングするというのだったら、最初から対面ではなくて、郵送して戻してもらうという形をとる方法もこれからはあるのではないかという思いが１点と、品川区においてはどのぐらいのお金がかかるのですか。","respondent":"川島地域活動課長","answer":"今回の予算ですけれども、予算書上の金額で言うと２億３,４８３万５,０００円という形で予算を計上しています。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"たしか１０年前の記憶なのではっきり覚えていないのですけれども、私の個人的な気持ちなのですけれども、結構細かいところまで聞いてくるな、調査してくるなという思いがすごくあったのです。やはり人それぞれだから、調査項目において話したくない、言いたくない、個人情報を全部言ってしまうのは躊躇するという思いが１０年前にあったのです。今回の調査用紙にも罰則や何かというのは出てくるのでしょうか。","respondent":"川島地域活動課長","answer":"調査票には書いてございませんが、記入の仕方のところに、委員は義務とおっしゃいましたが、統計法に基づく報告義務がありますということで、法律の関係部分を抜粋したものが記載しています。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"難しいことを聞いているのではなくて、罰則があるということは書いてあるのですかと質問しているから、今回は書いていませんか、書いてありますか。","respondent":"川島地域活動課長","answer":"統計法に基づきます罰則の条文が記載されております。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"私は１０年前に思った。うわ、怖いなと思いました。しつこいけれども、結構細かい質問もしてくる。私が一番思うのは、例えば、小選挙区等の選挙区の割当てに使うというのはよく伺うのですけれども、もう少し行政のお願い、アンケート、調査において、余り罰則ということを過剰に言っても、こうやって国から来てしまうからしようがないと言われてしまうと思うのだけれども、私はいかがなものかと。","respondent":"川島地域活動課長","answer":"より多くの方に回答していただくことが正確な統計につながるということで、このように法律も定められているのだと思います。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"先ほどご回答があった回収率です。全国で７割とおっしゃっていましたけれども、こちらの回収率を上げるために１０年前、５年前等々のノウハウを活かして、品川区独自でこういったことをやって回答率を上げていこうという施策はありますでしょうか。","respondent":"川島地域活動課長","answer":"先ほど説明がございませんでしたが、区民の方にお知らせするということで、広報も力を入れてやっているところでございまして、広報しながわへの掲載、ホームページ、それから、地域ニュースへの掲載、それから、成人式でＰＲしたり。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"私がこれで１点伺いたかったのが、結局、国から非常に豊富なマニュアルをそれぞれの自治体が渡されて、このやり方に沿って周知してください、このやり方に沿って回収してくださいということがあると思うのです。この地域では返答率が何％でした、回収率が何％でしたというのも、ある意味１つの統計として標準化すれば、国の中でここはこういう地域なのだという特性が把握できると思うのです。","respondent":"川島地域活動課長","answer":"ですので、広報をいろいろ工夫して、今も少し考えておりまして、例えば、TwitterやFacebookなども使っていきたいなというところで、新しい媒体なども使いながら、多くの方に回答していただける工夫も、少しずつですがやっていきたいと考えています。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問・要望","question":"ですので、インターネット回答という部分を、ぜひともいろいろな広報手段や、先ほどおっしゃったTwitter、Facebook等々も含めて、国勢調査のインターネット回答にぜひご協力をお願いしますと強く打ち出していただきたいなという要望があります。そちらに関していかがお考えでしょうか。","respondent":"川島地域活動課長","answer":"Twitter、Facebookといった新たな媒体を含めまして、インターネット回答が伸びるということは、多分調査員の方の負担軽減につながりますし、回答する方も回答しやすいということですので、何とか力を入れてやっていきたいと考えています。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問・要望","question":"ぜひともインターネット回答の部分、今後、５年後に向けてもそうですけれども、さまざまな部分で品川区の行政が区民の方にアプローチする手段としてインターネットを活用していただけるようにアピールしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645301?Template=document&Id=2874#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10089,"voices":43}},{"id":"r02-20200630-7","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"厚生委員会","time":"午前１０時００分～午後 ２時２９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)令和元年度品川区介護保険制度の運営状況","agenda":"はじめに、(1)令和元年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"総合事業についてお伺いいたします。それから、予算の推移を見ますと増えているような増えていないような、最近は頭打ちなのかなというような印象もこの事務事業概要を見ますと抱いたりするのですが、その辺の事業の伸び具合、あるいは実際にこれを利用されている方の評判が寄せられていると思うのですけれども、その辺のことをお教え願えればと思います。","respondent":"菅野高齢者地域支援課長","answer":"昨年度は平塚ゆうゆうプラザが開設しましたので、その分利用者が少し伸びているということと、今年度、東品川ゆうゆうプラザが９月にオープンする予定ですので、そうしましたらそこでも地域ミニデイ事業を始めたいと考えていますので。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"地域ミニデイについて、具体的なイメージは機能訓練というような感じなのですか。","respondent":"菅野高齢者地域支援課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それと、利用者の具体的な評判というものがもしあれば、少しでも伺えればと思います。","respondent":"菅野高齢者地域支援課長","answer":"こちらはあるゆうゆうプラザのプログラムなのですけれども、まず１０時にお迎えをして、オリエンテーションをして健康チェックということで、血圧と心拍数の測定や体組成チェック、あとはセルフモニタリングや簡単な各種健康情報の提供などを行った後、スクエアステップ。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"だから、１.３倍ぐらいになっているということですね。この数字から見ても、昨日の審議でも言いましたが、やはり作りさえすれば、特別養護老人ホームへの申請者が毎年５００名近くいるということからも、またこの有料老人ホームに対する需要の伸びからしても、在宅介護だけではなくて、老人ホームに対する需要も極めて多い数あることが示されているのではないかと私は思うのですけれども、いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"後期高齢者の人口も増えていまして、要介護度も上がっておりますので、全体としてサービスのニーズが増えているということは言えると思います。それから、この表の見方を改めてご説明しますと、サービス開始年度を１００としての指数になっております。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"今おっしゃった平成１８年を基準にしましても、平成１８年は指数で７５７ということですから、３倍程度に伸びているわけですね。だから、昨日申し上げた、毎年必ず５００人近くの申請者が特別養護老人ホームに集まっているという実態を見れば、やはり在宅介護だけではなく老人ホームに対する需要が確実に多数あるのだということは言える。そのこと自体はお認めにならざるを得ないのではないでしょうか。","respondent":"寺嶋福祉計画課長","answer":"ニーズがあるということは先ほども申し上げておりますので、認める、認めないではなくて、認識は持ってあります。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"私としては、とにかく在宅ではなくて、老人ホームに対するニーズが確実に非常に多くあるということが、この特定施設に対する需要の伸び、あるいは特別養護老人ホームに対する申請者数が減らない、申請者が毎年５００人いるという実態からも非常に強く推測できると言えると思うのです。その点、いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"施設サービス、それから在宅サービス、地域密着型も含めまして、それぞれにニーズがあるということは真正面から受け止めてあります。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"要介護３以上というところがさらに少ない状況になっているのです。今、特別養護老人ホームも要介護３以上でないと入れないという制約になりましたので、ここのところで本当に対象にすらならないという認定の状況があると思うのですけれども、この点について、区としての認識を伺いたいと思います。課題は何かというところも改めて伺いたいと思います。","respondent":"宮尾高齢者福祉課長、菅野高齢者地域支援課長","answer":"この違い、ずれですが、下の要介護認定状況に記載されている８万２,９０２人という方は、先ほど説明の中でも触れましたが、住所地特例と言いまして、品川区に元々住んでいた、住民票を置いていた方が。そういった形で、現在は新型コロナウイルス感染症の関係で、この事業が２月末ぐらいから休止しておりまして、やっと７月から始めるという形になっているのですけれども、こういう事業をしばらくお休みしたということが初めてなので。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは総合事業と介護給付のほうと合わせてということなのですけれども、ここら辺はどのように区として考えられているのかということ。それと、そのホームヘルプサービスにしても、総合事業のところでのホームヘルプサービスも、高齢者のニーズが増えている割には増えていないのではないかという思いがしているのですけれども、そこのところはどう評価されているのか伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"私のほうから、デイサービスとホームヘルプの実績のニーズに対しての伸びですが、私どもとしましては、特に介護報酬を区が低く抑えているせいで利用が抑えられているという認識は全くございません。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ありがとうございました。もう一つ教えていただきたいのは８ページなのですが、介護医療院というのが平成３０年からできた制度だというところなのですけれども、これの令和元年が１２人ということですけれども、療養型との違いがどのようなものなのかということと、これは区内に施設があるのかどうなのか、ちょっとその点についてお聞かせください。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"具体的に何が違うのかというのを実際に康済会病院の方にもお聞きしたのですけれども、一般の方にご説明する方法としては、特に大きな処遇が変わるということがあるわけではなく。まだ現時点では予定というところで、変更の要素というのは多分にありますが、基本的にはこちらの策定委員会を中心に準備を進めていきたいと考えています。","id":"exchange-009"}]},{"id":"topic-02","title":"新型コロナウイルス感染症の影響により収入が減少したこと等による第一号被保険者の介護保険料の減免","agenda":"新型コロナウイルス感染症の影響により収入が減少したこと等による第一号被保険者の介護保険料の減免","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"２、概要の2)のアなのですけれども、収入減が１０分の３以上、３割以上減った人ということになると思うのですけれども、この３割というのは、例えば持続化給付金だったら、３カ月のうちの１カ月でも半額以下になれば対象ということがあると思うのですけれども、この３割減というのは、そういうところではどこで判断をしたらいいのかということを教えてください。","respondent":"宮尾高齢者福祉課長","answer":"これは、今実際に申請を頂く時点で昨年と比べて減っている、その減っている状況がこれからも続くというふうに想定をして、算定をしていくという仕組みになってあります。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"仕事によって毎月同じ収入ではない場合は、３割まで減らなかったけれども、この月は３割以上減ってしまったとか、そういうことがあると思うのですけれども、そこのところは１カ月でもいいのか、それとも２月から申請までの月のトータルで３割減ることが必要なのかということと、その時点では３割以上減っているということで申請したとして、その後またちょっと持ち直して仕事が増えて１割ぐらいの減になって。","respondent":"宮尾高齢者福祉課長","answer":"これは申請していただいた時点で見します。あくまでも令和２年中の収入見込額で見するので、例えば委員がおっしゃったように、その後急に状況が改善をしてという場合でも対象にはなってきます。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"申込みの段階で、２月から３割以上減っているということが条件ということで捉えていいのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"そこは委員のおっしゃるとおり、２月の時点から申請を頂いた時点でまずは見させていただいて、その時点で３割以上減っているということであれば、こちらの減額の対象であるというご理解でよろしいと思います。","id":"exchange-012"}]},{"id":"topic-03","title":"令和元年度品川区障害福祉計画実績","agenda":"令和元年度品川区障害福祉計画実績","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"表を見ながら気づいた点、分からなかった点を質問します。数があるので、幾つか区切りながらお願いいたします。２ページ、最初のところですけれども、一番上の（１）ですが、２年連続で実績がゼロになっているのですけれども、これはどのようにお考えになって、どうなさるおつもりなのでしょうか。そこをまずお伺いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"施設としてももちろん努力して地域生活等への移行に努めているところではあるのですけれども、実態としてなかなか難しい方が多くいらっしゃるというところが現状です。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問・要望","question":"続きまして、５ページの4)と5)、計画書では４４ページ・４５ページです。これはそもそも見込みが記載されていないです。これはなぜなのですかということが１つ。それから、７ページの自立訓練ですけれども、上段下段、両方とも実績が減少傾向になっているのですが、これはなぜなのか、一体周知されているのか、そこら辺がちょっと引っかかりました。どうしてなのか教えてください。お願いします。","respondent":"築山障害者施策推進担当課長","answer":"３点のご質問ですけれども、まず１つ目の５ページ、4)行動援護と5)重度障害者等包括支援の記載がないということですけれども、これは当初の計画の段階でも見込みがないだろうということで、計画には入れておりませんでした。","id":"exchange-014"},{"speaker":"おくの委員","kind":"質問","question":"続けます。次に１５ページです。令和２年度の見込みが１になっていますけれども、計画では見込みが２になっているのですが、これは２の間違いではないかと思いますが、いかがでしょうか。これは一つの解釈ですけれども、事業所の定員枠を見込みよりも多い人数で分け合った結果、結局利用できる日数が限られたというようなことだったのではないかと思ったのですけれども、その点はいかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"大変失礼いたしました。１６ページについてですけれども、児童発達支援につきまして、月間利用者数は前年度と比べて大きな伸びは特にございませんが、月間利用実日数のほうは伸びておりますので、むしろ１人あたりの利用日数が増加しています。","id":"exchange-015"},{"speaker":"おくの委員","kind":"質問","question":"１７ページと１８ページです。居宅訪問型児童発達支援、それから医療型児童発達支援とあります。これを区内で実施している事業所はそれぞれ何カ所あるのでしょうか。これをお伺いしておきます。","respondent":"築山障害者施策推進担当課長","answer":"2)居宅訪問型児童発達支援について、区内にはございません。平成３０年度の利用については、他区の事業所を利用された方の実績になっております。それから、5)医療型児童発達支援についても、区内にはございません。","id":"exchange-016"},{"speaker":"おくの委員","kind":"質問・要望","question":"ヘルパーが増えないと利用も増えないということで、移動支援や同行援護の利用時間数のほうは、利用者が増えていると思うのですけれども、この点どうお考えになるかということをお伺いしたいと思います。それから、２７ページ。それをお願いしたいと思います。最後にもう一つお伺いしておきます。その見極めはどうするのか、どうされているのか、そこら辺のお考えを伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"最後の見込みより少ない場合の、事業者が少ないことによるものなのか、利用のニーズによるものなのか等の見極めということなのですけれども、こちらについては計画策定委員会等で基礎調査も実施しておりますので。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それともう一つ、計画書のほうでは２９ページから３８ページにわたって、今期の福祉計画における主要テーマと今後の取組みということで、相談支援の充実と適切な情報提供や、障害者福祉サービスと介護保険サービスの適切な運用、保健、医療との連携など、そういう形で７つのテーマ、この３年間の間にこういうことでやっていきますよという方針が書かれているわけですけれども、これに対しても。","respondent":"築山障害者施策推進担当課長","answer":"２９ページから３８ページの件につきましても、これは３カ年の取組みということで掲げたものですので、これも同様に計画策定委員会において分析等の検証、次期計画の策定につなげていきたいと考えております。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ＰＤＣＡは３年間に一回だけそういう形で評価するということでしかしないということなのでしょうか。それからあと、１７６件中、区の障害者福祉課で立てている件数は何件ぐらいあるのかについても教えていただきたいと思います。","respondent":"築山障害者施策推進担当課長、松山障害者福祉課長","answer":"評価についてですけれども、３年に１回しか評価しないということではなく、今回につきましては、実績ということで１年間の実績をご報告させていただいたところですが、この報告は、今年実施する計画策定委員会ですとか。新しい事業所は５事業所できましたけれども、品川区の障害者福祉課が立てているということで、大人とは異なりまして、民間から民間への移行はスムーズに進んでいるのですが、どうしても区が立てておりますと。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう一つなのですが、前回は自立支援協議会で計画を立てたのが、今回は計画策定委員会を立ち上げるということですが、ほかの自治体は策定委員会をずっと継続していて、この策定委員会で、ＰＤＣＡもそうですけれども、この計画に対してどう評価をしてこれからどうしていくかというところも継続して見ていくという形でしているところが多いのではないかと思うのですけれども。","respondent":"松山障害者福祉課長","answer":"今回、自立支援協議会とは別に計画策定委員会を設置するにあたりまして、やはりそれぞれのやるべき役割というのを整理したいと考えております。つきましては、計画策定委員会については、今後各年に１回開催することを考えております。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そうしましたら、計画策定委員会は策定したら解散というのではなくて、ずっと継続して、この計画の実績評価というのもその計画策定委員会でしていくということで、確認させていただいていいでしょうか。それともう一点だけ、３１ページに障害者差別解消支援地域協議会というのを設置しましたということであるのですけれども、これのメンバーはどのようなメンバーなのか。","respondent":"松山障害者福祉課長","answer":"計画策定委員会につきましては、今後年に１回ということを考えております。ＰＤＣＡサイクルに基づきまして、計画策定委員会が今後計画について評価していくというのが適切かと考えています。","id":"exchange-021"}]},{"id":"topic-04","title":"では、次に(4)ピックアップ型フードパントリー事業の開始","agenda":"では、次に(4)ピックアップ型フードパントリー事業の開始","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"これは対象者が区内在住の生活困窮者となっているのですが、ちょっと抽象的なので、もう少し詳しい要件としてはどのようなことですか。例えばホームレスの方とか、ひとり親家庭の方とか、あるいはネットカフェ難民と言われるような方とかいろいろいらっしゃると思うのですけれども、今挙げたような方を例に挙げながら具体的に説明してくださいますか。","respondent":"櫻木生活福祉課長","answer":"例えばひとり親世帯や、生活がギリギリの方を想定しております。ホームレスの方等につきましては、当然いらっしゃったときにお渡ししないということはないのですが、自立を目指すような制度ですので、その趣旨に沿った対応ということになるかと思います。","id":"exchange-022"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、収入が何円以上とか、そういう具体的な額で決めているのではなくて、柔軟にというようなことでよろしいですか。","respondent":"櫻木生活福祉課長","answer":"基本的な要件としましては、相談の中で食の支援が必要と判断された方ということになっております。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問","question":"フードバンクの最寄りの駅が浅草橋、秋葉原ということなのですけれども、そこへたどり着くまでの交通費などはどうなっているのでしょうか。","respondent":"櫻木生活福祉課長","answer":"交通費ですが、都営浅草線を利用すると片道２８０円、秋葉原ということですと、大井町から２２０円程度ということでございまして、ピックアップに伴う交通費を支給する予定はございませんが、もしその交通費に困窮されているという状況であれば、それはこの制度というよりは。","id":"exchange-024"},{"speaker":"おくの委員","kind":"質問","question":"予算２７万円で委託料ということになっているのですけれども、これはどこへの委託料で、何に使うというようなことなのでしょうか。","respondent":"櫻木生活福祉課長","answer":"こちらはセカンドハーベストジャパンへの委託料になっておりまして、費用としましては倉庫保管料や運搬料等の各種管理費用の実費に近いところの経費ということで聞いております。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"それと、先ほどの電車に乗るのかなという話、これは私も質問しようかと思ったのですけれども、１カ月分を配布すると、複数回に分けて受け取ることも可能と書いてあるのですが、その世帯１カ月分というと相当な量になるのではないかと思うのですけれども、そうした場合に、先ほど電車代片道２８０円のところを複数回にわたって受け取らなくてはいけないのではないかと思うのですが。","respondent":"櫻木生活福祉課長","answer":"仮に身体的な状況とかでピックアップが非常に難しいような方がいらっしゃった場合は、ご相談いただければ何らかの対応を考えていくということは検討していきたいと考えています。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"分かりました。いきなり暮らし・しごと応援センターに行くパターンもあるのでしょうけれども、うまく連携ができるのかなというところがやはりちょっと心配なところがあって、そこのところをしっかりやっていただきたいということがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"そうですね。とりあえず。ごめんなさい、まだ質問終わっていないので、いいですか。","respondent":"櫻木生活福祉課長","answer":"周知の方法としまして、特に品川区として掲載していただくことに不都合は感じておりませんので、いずれ掲載されるものだと考えています。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"この事業についてはそもそも周知はされるのでしょうか。","respondent":"櫻木生活福祉課長","answer":"この事業につきましては、基本的にはホームページ等で掲載をするのですが、内容的にはご相談を受けたベースで判断してご案内するという組立てになっておりますので、ひとり親世帯等の所管とは連携して周知はいたしますが、そういう形でやっていこうと思っています。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ということになると、暮らし・しごと応援センターに行かれても、子育て応援課のほうに行かれても、この事業の周知漏れがあると知る由がないということになってしまいますので、そこのところは重ねてのお願いになりますけれども、せっかく１５キロもこういう食料を頂けるということですから、周知をお願いしたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"西村委員","kind":"質問","question":"１点だけ、すみません。ホームページを拝見していまして、食品を受けとれる場所一覧マップという中に一番近いところで大田区があったのですが、こういったところで受け取るということはイレギュラーになるので難しいのでしょうか。","respondent":"櫻木生活福祉課長","answer":"品川区の方がそちらに行って受け取ることは、ひとり親世帯の方については可能となっていると認識しております。これもちょっとほかの所管ではありますが、その大田区のほうが事業を開始する際には、品川区のひとり親世帯の方に周知をされたと聞いております。","id":"exchange-031"},{"speaker":"西村委員","kind":"質問","question":"グッドネイバーズジャパンとこのセカンドハーベストジャパンの関係性というのはどのようなものですか。両者の関係は。","respondent":"櫻木生活福祉課長","answer":"セカンドハーベストジャパンとグッドネイバーズジャパンの関係についてのご質問ですが、どちらも独自に活動されているＮＧＯで、同じような趣旨で活動されている団体と認識しております。","id":"exchange-032"},{"speaker":"西村委員","kind":"質問","question":"ホームページから検索して、セカンドハーベストジャパンのところから飛べましたので、何か連携されていたり関係があるのかなと思ったのですけれども、そうではないですか。連携はあるのですか。","respondent":"櫻木生活福祉課長","answer":"正確に申し上げますと、グッドネイバーズジャパンは、セカンドハーベストジャパンから食料を受け取って、それをパントリー型の事業として、大田区を中心に拠点で配布されているということになっておりますので、大本になるのはグッドネイバーズジャパンが企業から食料等を集めて。","id":"exchange-033"},{"speaker":"西村委員","kind":"質問・要望","question":"ひとり親家庭の方は受けとれる方向性でというお話かなと思ったのですけれども、浅草橋はやはり遠いかなと思いますので、順次でもなるべく近いところで受け取れるよう要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それと、これは５０世帯ということですけれども、５０世帯を超えて希望が増えてしまった場合は、それでも５０世帯ということで限定されるのか。これは５０世帯を６カ月ということですけれども、５０世帯が６カ月だったら、その次はまた５０世帯が６カ月ということで、１年間で考えると１００世帯ということになるのか、その点についても教えてください。","respondent":"櫻木生活福祉課長","answer":"それと、５０世帯の話につきましては、基本的には対象となる世帯が５０世帯で、最大６カ月までという予算組みになっておりますので、その予算の範囲内で対応するということです。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"食の支援を受けることで自立ということであれば、今ギリギリでも自立してやっているという方は対象にならなくて、イメージとしては、例えば離婚したばかりでこの先どうしようかという方だったり、生活保護を受けているけれども、この支援を受ければ仕事を探して生活保護から抜けられるとか、そういう形での対応になるのでしょうか。ちょっとそこの点についても、イメージが持てるようにお願いします。","respondent":"櫻木生活福祉課長","answer":"それと、子ども関係所管というのは、子育て応援課以外にも子ども家庭支援センター等がありますので、そのあたりについては関係所管、子ども未来部ほかとこれからお話をして、協調関係を作っていきたいと考えています。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この食の支援は、暮らし・しごと応援センターの役割という趣旨でやるということですものね。そういうことで言えば、多分子どもだけではなくて、失業してしまい仕事を探す間のすごく困窮している状況だったり、結構そういう方が暮らし・しごと応援センターにご相談に行かれていると思うのですけれども、そういう方も対象になるということで考えていいのでしょうか。","respondent":"櫻木生活福祉課長","answer":"基本的にはお仕事をされていても困窮に至って、食の支援があれば自立に向かっていくという意味合いでは、委員がご指摘されたような方も対象になってくると思います。","id":"exchange-037"}]},{"id":"topic-05","title":"新型コロナウイルス感染症の拡大にかかる国民健康保険料の減免","agenda":"新型コロナウイルス感染症の拡大にかかる国民健康保険料の減免","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"午前中に高齢者福祉課の介護保険の説明を聞いたのですけれども、今、話を聞いて、レジュメを見ていて思ったのですけれども、大体似たような感じなのですね。だとしたら、これからでもいいので、何とかそこは窓口に３回行くことになるかもしれないですけれども、手続きはこれもあります、あれもありますと言ってほしいという気がするのですけれども、その辺だけ教えてください。","respondent":"池田国保医療年金課長","answer":"申請自体は原則、郵送で受付ということになっておりますので、申請を受付けた方につきましては、決定通知等を送る際にこういったものもありますよということでご案内するとともに、国保と後期高齢者医療につきましては、国保が先に受付等を行っておりますので。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"裏側の減免の計算式ですけれども、これは所得が減った場合ということになるのですけれども、元々給与控除だったり税金控除だったりとかして、所得の均等割りだけで、しかも均等割りの７割減免とか５割減免とかいう方は基本対象にならないということで考えられるのかなと思ったのですけれども、そこら辺の目安だけ教えていただけないでしょうか。","respondent":"池田国保医療年金課長","answer":"ただいまお話がありましたように、基本は新型コロナウイルス感染症の影響によりまして収入が減った方ということでこちらの制度を作ってありますので、既に減額になっている方についてはそちらのほうで既に減額になっておりますので、ならないということと。","id":"exchange-039"}]},{"id":"topic-06","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ご存じでしょうけれども、厚生労働省から特別区宛てに業務連絡があります。「新型コロナウイルス感染症に関するＰＣＲ等の検査体制の強化に向けた指針」というものなのですけれども、これを読ませていただきました。このようなことが書いてあるのですが、こういうことを品川区でもされているのでしょうか。こういう数字や対策が明らかになっているのか。こういう点をお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"その検討部署につきましては、大枠、相談、受診・調整、それから入院調整、医療連携に関しては私ども保健予防課で実施していますが、特にＰＣＲ検査センターにつきましては、５月より、舩木保健体制整備担当課長とともに、対応について検討しています。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問","question":"１点だけ教えてください。北海道も出ていますけれども、そういう中で、毎月１０名ずつくらい出ている品川区の今の状況というのは、保健所としてどのように分析されているのか。そもそも分析ができるのか分かりませんけれども、落ち着いている状況ということで、いわゆる感染が拡大しているということは言えないのかどうか、おっしゃっていただける範囲で教えていただければと思います。","respondent":"鷹箸保健予防課長","answer":"非常に重要なご指摘、ありがとうあります。今、毎週ホームページの更新をしている中で、確かに４月の終わりから５月の終わり、６月の終わりまでは、おかげさまでなだらかな患者数の増加だったと考えています。","id":"exchange-041"},{"speaker":"あくつ委員","kind":"確認","question":"お問い合わせは、やはり区民の方から来るのですけれども、例えばお店、スナックをやっている方、絵画教室をやっている方、どのような形で再開をすればいいのでしょうかというところで、個人のご判断ですよと申し上げるのですけれども、参考にすべきものは例えば区有施設の再開状況であったり、また区内の感染者数であったりというところでご紹介はするのですが、最後は本当に未知の世界なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、先ほどの厚生労働省からの指針について、区としても様々検討されているということなのですけれども、ここの検査需要の見通しで、最大ピーク時１日何件かというのを点検するようにということで書かれているのですけれども、ここの想定というのは、最大ピーク時１日何件を想定されているのか、そこもありましたらお聞かせいただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"それはあくまでもＰＣＲ検査センターで、それ以外にいわゆる区内の病院の外来がありますので、そこで例えば６０名ぐらいできれば、合わせて１２０名ぐらいではないかと想定で出していますが、今回国に出した数では、やはり直接対応できる数だけ出していますので。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう一つなのですが、先ほど、今度唾液でＰＣＲ検査ができるようになるということで、医療機関でできるようになるということ、発症後９日以内の有症状者に対して可能になったということですけれども、この唾液の検査というのはどこの医療機関でも、ドクターが判断したら普通のインフルエンザみたいな形でやれるというのではなくて、保健所が今の帰国者・接触者外来みたいな形で。","respondent":"鷹箸保健予防課長","answer":"検査の受け方ですけれども、まず、検査実施可能な医療機関については、基本的には、検査に行く人と一般の診療の人の動線がかぶらない、要するに同じ外来で待つのは困るというような前提が元々ありまして、最低限、診察室が２つ以上あるということが原則になっておりまして、今。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それと、唾液検査はそのようにこのクリニックだったら動線が確保されているし、診察室も２つあるから大丈夫という形で、東京都が認めて許可をするという形になっていくということですね。おおよそいつぐらいからそういうのが可能になるかというのは、見通しがもしもできていたら教えてください。","respondent":"鷹箸保健予防課長","answer":"民間検査機関の受入れについてですけれども、たくさんある検査機関で毎日何件可能という情報が我々のところに来るのですけれども、これだけ唾液検査のほうが始まったということは、我々が関与するところではありませんが。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/334734?Template=document&Id=3572#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":46624,"voices":136}},{"id":"r02-20200630-8","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"建設委員会","time":"午前１０時００分～午後 ２時５４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を78件抜き出しています。","topics":[{"id":"topic-01","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"昨日も私の意見は述べさせていただきました。立体化についてはいいと思うのですけれども、駅周辺の整備ですとかまちづくり関連の事業推進というのは、補助２９号線ですとか駅前での再開発と、そういうことが含まれているので、私の意見としては、このまちづくりのところは入れるべきではないということで、言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"田中委員","kind":"意見","question":"品川・生活者ネットワークとしても、１の東急大井町線戸越公園駅付近の連続立体交差事業の早期事業化に関しては理解をしますが、２のまちづくり関連の事業推進に関しては、今は時期ではないのかなということは、昨日も申し述べましたが、思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"令和２年７月区営住宅入居者募集","agenda":"令和２年７月区営住宅入居者募集","exchanges":[{"speaker":"西本委員","kind":"質問","question":"募集住宅は７戸ですけれども、場所は教えていただけますかというのと、少し基本的なことで申し訳ないのですけれども、申込みは７戸だけで、順番待ちとか、そういうものはないのですか。それから、障害者は有利なのかとか、その辺の優先順位をもう少し具体的に知りたいです。","respondent":"森住宅課長","answer":"募集住宅の場所、住宅名といいましょうか、それにつきましては、７月３日の募集冊子を見ていただければと考えています。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"そうすると、場所については、７月３日以降ではないと公開できないということですか。分かりました。それと、当選者は７人なのですか。それとも補欠とか、そういうのはとる予定があるのか。いかがですか。","respondent":"森住宅課長","answer":"補欠につきましては、各住宅で５名まで、抽選のときに設定をするという形にしております。それで、１番の当選の方が辞退された、あるいは審査に不適合ということになりましたら、補欠の１番の方から順次ご案内していくという形になります。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"すると、ほかも区営住宅はありますよね。何か所あるか分からないですけれども。その場合、途中空きがあったという場合には、それはもうずっと空きの状況ということの理解でよろしいですか。それとも、補欠の人が、“ここでいいですか”と聞いて、そっちに入れるということはないのでしょうか。","respondent":"森住宅課長","answer":"今現在、住宅につきましては１６棟４３９戸というのが、定員といいますか、全部の戸数になりまして、５月末現在ですけれども、そのうち４３１戸に入居されていて、８戸が空室ということになってあります。このうち７戸を今回募集すると。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"すみません。仕組み、本当は知っておかなければいけないことなのですけれども。要は、７月に募集がありますよね。そこで７戸の入居者が決まります。途中で空く場合があるではないですか。その場合は、今待っている優先順位の高いところからやっていくことなのですか。それとも、またそこで抽選になってしまうのか。","respondent":"森住宅課長","answer":"その１月募集のときに、７月から１月の間で空いたものにつきましては、その時点で募集をかけられれば募集をかけて、１月の募集で当選された方からご案内していくという形になります。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"今の質疑の中で、１月に募集をした方を現在も審査中ということだったのですけれども、それだけ時間がかかるということなのですか。","respondent":"森住宅課長","answer":"１月の時点でも７戸募集しているのですけれども、残り６戸につきましては、もう入居済みというような状況です。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"通常なら２か月以内で入居ができるということが確認できたので、安心しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"募集時期というのは、増やしたりというのはできないのでしょうか。やはり望んでいる方が多くいらっしゃるので、適宜入っていけるようにできたらと思うのですけれども、いかがでしょう。","respondent":"森住宅課長","answer":"募集時期については１月と７月ということで毎年やらせていただいておりまして、基本的には退居の申出があって、実際に退居の手続きをし、引っ越しの期間を決めて、その後、原状回復工事をして、それから募集冊子を作っていくという形になりますので。","id":"exchange-009"},{"speaker":"田中委員","kind":"確認","question":"すみません、聞き忘れてしまったのですけれども、毎回の募集のときの倍率というのを確認させていただいてもいいですか。","respondent":"森住宅課長","answer":"倍率につきましては、１月募集のときにつきましては、単身の方で８７％、世帯持ちについては全体で３２.５％という形になっております。","id":"exchange-010"}]},{"id":"topic-03","title":"二葉四丁目地区要請型従前居住者用賃貸住宅建設計画説明会","agenda":"二葉四丁目地区要請型従前居住者用賃貸住宅建設計画説明会","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"この９か所のところと、今、開放広場になっているところを交換するということでよろしいですか。そこの確認と、区として購入した開放広場と交換するということになるので、どういった基準、等価交換というのか、面積ですとか、あとは価格とかもあるとは思うのですけれども、そういったところがきちんと保証されているのか、そこのところを伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"手続きにつきましては現在進めておりまして、協定に基づいて、大体めどが立ちまして、あとは細かいところを詰めていくところですので、今回、説明会の開催に至ったというところです。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"分かりました。空いていなければ、入れないということになってしまうというのがあると思うのですが、そこの考え方を伺いたいのと、あと、配置図を見ると、横のところがII期公共施設予定地と書いてあるのですが、それが何かほかのことに使っていくということなのか、この活用方法などが今ありましたら、伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"これらは今現在、１１室空いてあります。それに加えて、今般２５戸を整備して、その上で必要な分、ある程度見込みを立てて、借り上げて運用していくということを予定しております。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"借上げのほうですが、既に埋まってしまったときの、事業協力者をどう入れるかというところでお聞きしたので、先ほどの答弁だと、ソレイユ戸越とかソレイユ中延のほうに入れるということなのか分かりませんが、そこの借上げが埋まっていたとき、確保できないのではないかというところがあるので、そこを伺いたかった。そこのところを、また改めて答弁を頂けたらと思うのですけれども。","respondent":"佐藤木密整備推進課長","answer":"今回説明会を行う新しい従前居住者用住宅について、完成した後で、順次、必要性をこちらでＵＲと協議して、借上げ戸数を決めていくという運用になると思うのですけれども、今までの事業の進んできている経緯を考えますと。","id":"exchange-013"},{"speaker":"のだて委員","kind":"確認","question":"見込みということで。途中で入るという方が、もうＵＲの賃貸として貸していた場合に、入れないわけではないですか。そこのところを伺いたい。建て替えの支援の活用という隣りの土地のところは、そうすると、空地があれば建て替えられるということで、安全通路を確保して、共用部みたいな形で隣地に確保してあげて、建て替えられますよという形ということでよろしいですか。そこの確認。","respondent":"佐藤木密整備推進課長","answer":"先ほどの施設の隣地の部分の活用については、他の木密事業で取得している空地と同様という形だと思いますので、手段としては、交換用地にするですとか、その空地を通路としまして、建て替えを促進するですとか、そういった手法があろうかと思いますので、ここはＵＲと。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"すみません、最後に。借上げのところで、先行事例、定期借家でやっているということのご説明でしたけれども、そうすると、ＵＲから借りている人が、逆に追い出されてしまうということになると思うのです。それはそれでまた問題な気がするのですが、そこのところは、補償というか、支援というのはあるのですか。","respondent":"佐藤木密整備推進課長","answer":"ご懸念のところは、そういった運用でクリアされるのではないかと考えております。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"すみません。全然この事業が分からないので、いろいろ教えてほしいと思うのですけれども、まず、補助２９号線の事業が今どのくらい進んでいるのかといったことを、伺いたいです。","respondent":"佐藤木密整備推進課長、鈴木都市計画課長","answer":"補助２９号線の整備につきましては東京都で進めておりまして、私どもでは、沿道の不燃化ということで、１０年プロジェクトに基づいて不燃化を進めているという形になろうかと思います。補助２９号線、特定整備路線の今の進捗状況ですが、東京都には最新の情報の提出を求めているのですが、平成３１年３月３１日現在で、補助２９号線、幾つかの区間に分けていますが、おおむねで言いますと。","id":"exchange-016"},{"speaker":"田中委員","kind":"確認","question":"この補助２９号線の事業に関わる方たちが、この賃貸住宅にということではないのですか。そこだけ確認したいのですけれども。","respondent":"佐藤木密整備推進課長","answer":"従前居住者用住宅につきましては、協定に基づいてＵＲも一緒に進めておりますけれども、品川区で木密事業にご協力いただいた方で、住居に困窮される方を対象にして、入居していただいております。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"そうですね。木密事業に協力いただいた方が、ここに優先的にというか、賃貸住宅に住むということですよね。それで、その協力いただける数というのがこの２５件となっているのか、先ほども根拠について少し触れていたとは思うのですけれども、この地域で協力された方が、ここに住めるといったことなのかどうかという確認をさせていただきたいというか、２５件の根拠も知りたいです。","respondent":"佐藤木密整備推進課長","answer":"今回、２５戸といたしましたのは、これまでの事業の進捗とこれからの事業の進捗から、入居希望がどのぐらい出るであろうかということが１つと、また。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"別の質問です。対象範囲の中にある「電波障害を受けると認められる者」について、この「電波障害を受ける」というのが、少し意味が分からなかったので、そこの説明をお願いいたします。","respondent":"佐藤木密整備推進課長","answer":"今回、ＵＲのほうで、電波障害を受ける範囲については、専用の予測ソフトを使って予測しておりまして、最初に申し上げた、建物の２倍の範囲の方を対象としておるのですけれども、電波障害の方についてもその範囲内で収まると聞いておりますので、その方たちについては、今回。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"そういった説明とかは、まだ、これから７月１３日が第１回ということだったのですけれども、前もって早めの説明とか、説明資料とかの周知といったところをぜひしていただきたいと思うのですが、いかがでしょうか。","respondent":"佐藤木密整備推進課長","answer":"今回、コロナ対策に注意しながらということですので、事前にビラを配布して当日ご案内いたしますのと、同時に、説明会が終わりましたら、同じ説明会の資料を同一の地区に配布するということを考えておりまして、その後でも、ＵＲのほうになりますけれども。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"その説明会についてですけれども、資料は配布されるということですよね。それで、やりとりの議事録の公開というのはどうなっているのかということを確認させていただきたいのと、今、ＵＲが取得している２から９のところというのは、今はどういう状態になっているのか、お知らせください。","respondent":"佐藤木密整備推進課長","answer":"もう１点、交換用地のところですけれども、予定しております交換用地については今現在ＵＲが取得しておりまして、現況としましてはすべて更地という形になっております。","id":"exchange-021"},{"speaker":"田中委員","kind":"確認","question":"ＵＲの取得している土地については了解しました。説明会についても、説明会に参加できない方たちもいると思うので、そういった方たちが、説明会でどういう説明があったのかといったことを確認できるように、説明会に参加できない方たちにも、説明資料であったり、そういったものを渡していただけたらと思いますが、いかがでしょうか。","respondent":"佐藤木密整備推進課長","answer":"説明会につきましては、周辺の方々に分かりいいような形で、工夫したいと考えます。もう１点、何でしたか……。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"私の理解が正しいか、間違っていたら指摘してください。資料２の図です。２番から９番のところは更地になっています。そことの金額相殺の話は、ＵＲとは決着がついているということでの理解でよろしいですか。それも含めると、今後、地域はやはり木密地域に限定されると思うのですが、その地域の限定と、今どのぐらい進んでいて、どのぐらいの目標という形で考えておられるのか、教えてください。","respondent":"佐藤木密整備推進課長","answer":"１つ目は、今現在、交換を予定しております土地についてのお尋ねですけれども、今現在更地になっているというのは、先ほどご案内のとおりでして、権利関係につきましては、既にＵＲで所有権を取得しているという形になりますので、住んでいらっしゃった方からお譲りいただいて。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"そうすると、もう既にいろいろ宣伝されているのだと思うのです。それはいつ頃から始まって、現在どういう形で進んでいるのでしょうか。まだまだ希望者がいる、大体８０戸ぐらいは必要だろうとは思ってはいるのですけれども、今現実として、いつ頃からやって、申込み者がどのぐらいいらっしゃるというか、今の状況はいかがでしょうか。","respondent":"佐藤木密整備推進課長","answer":"それで、委員が最初におっしゃったとおりで、“こういった住居があるのでご協力いただけませんか”という１つの手段として、選択肢として、協力者の方にお選びいただけるという形で事業を進めてまいりまして、もちろんほかの地域、あるいは同一の地域に建て替えたり。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"広くなる分については、今住んでいるところよりも、平米数にしても広くなってきた場合には、プラスアルファのお金がかかってくるのかとか、では、今度小さくなってしまった場合にどうなのかとか、結局、“その土地をください。それと、これにあたっては、補助金とかはあるのでしょうか。品川区独自のお金でやっていくのか、国とか都とかのお金がどのぐらい入ってくるのかということを教えてください。","respondent":"佐藤木密整備推進課長","answer":"ただ、従前居住者用住宅自体が、協力いただいたことで住居に困窮される方を対象にしているという形になりますので、協力者の方から見れば選択肢の１つとお考えいただいて、ご自分で探されるという方も多くいらっしゃいますが、区では。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"そうすると、建てるときの建設費用は、ＵＲのほうでということですか。それで、あと、借上げとかをするわけですよね。そこのお金の仕組みというのが分かれば。お金が発生する場合、品川区独自の予算から出さなければいけなくなっているのか、独自事業になってしまうのかという、そこのお金の関係で、流れを教えてください。","respondent":"佐藤木密整備推進課長","answer":"そのところで、精算というところはありますけれども、経費については大きいところではないかと考えます。今回、従前居住者用住宅の建設については、都からの要請を受けて、ＵＲと協定を結んだ上で、ＵＲが建設するという形になっておりまして、その建設の経費についてはないです。","id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"確認です。では、建物については、ＵＲの建設費でやっていくということが分かりました。それで、そこに入っていただく。そうすると、土地を買うお金、例えば５,０００万円で買いました。その５,０００万円は、こちらの住宅は５,０００万円だから、５,０００万円引く５,０００万円でゼロだということは、品川区の負担で、その土地を買うお金は出てくるのですよね。私、少し理解が間違っていますか。","respondent":"佐藤木密整備推進課長","answer":"その際には、ＵＲが入って、ＵＲがお支払いしてという形もありますし、区で直接土地を購入するという形はあろうかと思います。その際は、等価というか、その価格で購入するという形で進めております。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、１点だけ要望なのですけれども、この２から９までの点在しているＵＲの土地について、先に調べに行きたいと思ったときに、住所の記載がなかったので、迷子になるというか、分からなかったので、次、こういった形で出てくるときに、資料にも住所が載っていると調査がしやすいかと思うのです。そこのところをお願いしたいのですが、いかがでしょうか。","respondent":"佐藤木密整備推進課長","answer":"すみません。今後、資料の作成に関しては、そのような観点からも考えて、ご提供するようにいたします。","id":"exchange-028"}]},{"id":"topic-04","title":"京浜急行本線連続立体交差事業および北品川駅駅前広場整備事業に関する用地補償説明会","agenda":"京浜急行本線連続立体交差事業および北品川駅駅前広場整備事業に関する用地補償説明会","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、新型コロナウイルスの対策のためということで、説明会ではなく書面開催ということなのですが、この近くの方が高齢ということもあって、１人で聞くのが心配だということが多分あると思うのですけれども、説明会をやってほしいということで声がありました。密を避けてやることができるのではないかと思うので、そこのところをぜひ検討して、開催していただきたいと思うのですが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"８月から開始いたします個別説明につきましては、このビラを配布いたします権利者の方々全員に対して、行っていくところです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"個別説明は全員対象になるというご説明だったので、借家人とかも対象になるということでいいかということで、確認させていただきたいと思います。その場合、この書面の文言も、そこまで気にされている方は少ないかもしれませんが、“自分は対象ではないのだな”と思う方もいると思うので、そこら辺は少し文言を、気をつけて記載していただければと思いますが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"書面につきましては、委員のおっしゃるとおり、再度検討いたしまして、今後、内容につきましては柔軟に対応していきたいと考えています。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"これ、用地測量は終わったという前提でいいのでしょうかというのが１つ。それから、今お話があったように、これ、補償という形が出ているのだけれども、借家人の補償というのはないわけです。民・民の。ですから、そういうことを、逆にここは補償がありますみたいなことを、行政から一言でも言える話ではないと思う。","respondent":"中道まちづくり立体化担当課長","answer":"分譲マンション等につきまして、そこの部分につきましては、東京都の事業と区の駅前広場の事業との、重複地権者の方もおられます。そうした形で、基本的には大部分が都市計画区域の中に入りますので、除却という形で物事を進めていくというところで、今、検討しています。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"もう白抜きでいいのではないかと思うのと、そういった工夫、「必ず読んでください」といった文言とかがあったほうがよいのではないかなというのと、意見用紙もあるので、お問合せも、“ここまでお問い合せください”ということも書いてあるのですけれども、そういった、“いつでもこちらは答える姿勢があるよ”といったことも、もう少し分かりやすく書いていただけたらと思うのですが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"そういった２回にわたっての周知といったところで、地権者の方には丁寧にご案内をしていくといったところです。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"二段構えで送付して、必ず見てもらう工夫というのは了解しました。ただ、その１枚目から、絶対見なければ、読まなければいけないのだ、自分たちに関わることなのだなということが分かるように、目を引くような工夫をしていただきたいと思うのですが、そのところはいかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"こちらを配布する際には、封筒等ではなくて、ビニール袋等に入れまして、それで、品川区からのおたよりといったところがポストの中等、または郵送等でもすぐに分かるように、そういった工夫はする予定です。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"読みやすさ、目にしやすさをぜひ工夫していただいて。とにかくこの青色の背景というのは……。手に取る方のことを考えて、目に入れてもらえるような工夫を再度求めます。","respondent":"中道まちづくり立体化担当課長","answer":"委員の言われることを踏まえて、また検討してまいります。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、６３名のマンションの問題です。地域の中でかなり議論されていることなので、ある程度は理解されているのだろうという思いはあるので、あとは条件整理なのかなという感じはするのですが、今どういう状況なのでしょうか。できれば、やはり全員が納得いく形で進めていただきたいという思いがあるのです。現状はどういう状況なのか、教えてもらえますか。","respondent":"中道まちづくり立体化担当課長","answer":"先ほどの集合住宅６３名のうち、借家人の方は４９名になります。こちら、マンションが２棟ございまして、１つは権利者お持ちの分譲住宅、１つは借家人の方がいらっしゃるマンションです。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"ということは、借家人の方々、企業が介入してということなのですけれども、そこはうまくいっているのか、スムーズにいこうとしているのか、感覚でもいいので、教えていただけますか。","respondent":"中道まちづくり立体化担当課長","answer":"今の企業の方とのお話し合いの中では、否定しているわけではございません。今後の補償内容について、どういうふうに取り組んでいくのかといった、具体的な話になっているところです。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、丁寧に。なので、８月上旬から個別説明実施となっているので、ここである程度カバーできるかなと思うのですけれども、やはり見ただけでは、特に役所の資料というのは難し過ぎて、何か分からないというような方々も多くいらっしゃるのが事実だと思うのです。なので、この８月からの個別説明実施というのは、本当に丁寧にやっていただきたいということでお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-05","title":"木造住宅の耐震診断助成額の変更","agenda":"木造住宅の耐震診断助成額の変更","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、東京都建築士事務所協会から要望があったということで、助成額の増額ということですけれども、この要望があった内容というのがこの資料に書かれておりますが、それ以外に何かあったり、さらに詳しく説明できることがあれば、伺いたいと思います。そして、今回の増額によって、区としては診断件数が増えていくと見ているのか、その見方も伺いたいと思います。","respondent":"長尾建築課長","answer":"建築士事務所協会からの要望の背景に関わる部分ですけれども、先ほどご説明した内容のほか、消費税が、平成１６年度は５％でしたけれども、現在は１０％というところも、話としては出ておりました。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"耐震化ですとかを進めていくために、そういったことが必要だと思うのですが、いかがでしょうかということと、この耐震診断の受付というのが通年で申請できないという話を聞いているのですが、通年申請ができるようにしていただいたほうが、やはり受けやすくなるのかと思うのですけれども、いかがでしょうか。","respondent":"長尾建築課長","answer":"診断の申し込みをいただく時期につきましては、できる限り申請者の方の今後の耐震改修に向けてのスケジュールなども総合的に確認しながら、手続きができるだけ円滑に進むように、窓口でも対応しています。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"当然円滑にやってほしいのですけれども、通年申請も併せてご検討いただきたいと思いますし、個人所有のために２分の１の補助率というお話でしたけれども、耐震化というのはやはり地域の防災のためにも必要なものになりますので、当然、公共性があるということでこの補助をしていると思いますが、そういった中で耐震化をさらに進めていくためにも、全額補償をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つか伺いたいのですが、まず１つは、これは数が分からなくてもいいのですが、品川区内でリフォームを、戸建てとか長屋でも結構ですが、マンションリフォームとかではなくて、普通にリフォームが何件ぐらい行われていると大体把握をされているのか、分かれば教えていただきたい。それでも、ここで耐震診断にいって、１３件から何件補強工事をやったのか、耐震でリフォームをしたのか。","respondent":"長尾建築課長","answer":"無料の簡易耐震診断を受けていただく中で、委員おっしゃるように、大体どのぐらいの補強が必要になりそうかとか、あと、事務所協会では、耐震性のお話だけではなくて、建物のリフォームに関わる部分であるとか、相談者が気になるところは。","id":"exchange-041"},{"speaker":"石田（秀）委員","kind":"質問","question":"本当にありがとうあります。大変ご苦労されているのだと考えていますけれども、ぜひそこら辺のところを。ですから、そういうことも含めて、やはり全体をどこかでぜひ業界の方々ともいろいろ話をしていただいて、少しでも前へ進むようないい方法をもう探る時期だと、すごく私は思っているので、ぜひそこら辺はお願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません、議題から外れたら指摘していただきたいのですけれども。災害道路というのがありますよね。品川区に災害道路があって、そこの周辺は耐震化を進めなければいけないというふうになって、なかなか応えられないところは公表するみたいなことを事業の１つでやっていたと思うのです。ただ、やらねばならぬというところがあったと思うのですが、それはいかがですか。","respondent":"長尾建築課長","answer":"委員お尋ねの道路、避難に関わる道路ということで、建築課で、緊急輸送道路の道路沿いの建物に関して、今、ご説明した木造住宅の耐震化支援とは別の制度で、緊急輸送道路沿道も、耐震診断から補強工事まで支援をしております。","id":"exchange-043"},{"speaker":"西本委員","kind":"意見","question":"災害道路というのは非常に大切な避難道路になっているところがあって、なかなかそれも、同じような傾向ですよね。診断してもどうなのだと。建て替える気持ちがなければ、建て替えもしないし補強もしないだろうという。なので、やはり全体的な考えの見直しを図るのか、あとは、強制をどれだけ働かせるのかみたいなところも必要になってくるのかと思いますので、これは今後検討していただければと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]},{"id":"topic-06","title":"東京都屋外広告物条例におけるプロジェクションマッピングの取扱い","agenda":"東京都屋外広告物条例におけるプロジェクションマッピングの取扱い","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"併せて、道路際でプロジェクションマッピングをすると、非常に光を当てることになるので、運転手への幻惑作用というのですか、そっちを見てしまう、交通上の危険性があるという話もあるのですが、その辺の安全性の担保というか、それをどのようにしていくのか、伺いたいと思います。","respondent":"稲田土木管理課長","answer":"３つ目のご質問で、公益行事であれば届出だけでいいというような話のことですが、先ほども申しましたように、これは東京都がいろいろと検証をしまして、東京都のまちづくりにおいて、活性化やにぎわい創出のためにはこういうものが必要である。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"この幻惑作用のことについては、都の条例でいろいろ指摘がされているということで、それに則ってということでしたけれども、区としては何か基準というのはあるのでしょうか。安全性というのはやはり大事なことだと思うので、そこをしっかりやっていただきたいと思うのですが、いかがでしょうか。","respondent":"稲田土木管理課長","answer":"そういうところですので、各現場をしっかりと区は把握して、申請者に対しての、どういう状況での設置の仕方とか角度とか、いろいろあるとは思いますが、そういうのを総合して、申請とか許可を出す段階、そういう中においてチェックをしていきたいと考えております。","id":"exchange-046"},{"speaker":"田中委員","kind":"確認","question":"今の質疑のところなのですけれども、申請が出されたときに、区として影響がないかどうかのチェックをしに行って、例えば“ここであったら反射する”とか、そういったものをチェックして判断するといったところでしょうか。この確認だけさせてください。","respondent":"稲田土木管理課長","answer":"とにかく事故があってはならないという観点で見ていきます。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"過去に天王洲ではあったということですけれども、これからいろいろな場所で、どこで行われるかもまだ決定はしていないけれども、様々な状況、様々な場所がこれから出てくるとしたときに、やはり初めてやることとかだと、慎重に、事故が起きないようにという状況を見なければいけないと思うので、なるべく現地に行って、本当に安全性を確かめてほしいと思うのですが、いかがでしょうか。","respondent":"稲田土木管理課長","answer":"過去に品川区では天王洲で２回、区が許可を出したものがあるという状況ですので、まだまだ区としても、どういう場面があるかというのは分かりませんけれども、先ほど来言うように、事故があってはなりませんので、その辺のチェックはしっかりしていきたいです。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"例えばこの資料にあるように、天王洲で２回ほどやったということですけれども、これは有料だったのでしょうか。その有料だったとき、まだこの条例がなされていないので、金額がどうだったのかと思うのですけれども、区で許可するものについては無料なのか、あと、民間事業者がやるとすると、この金額がかかってくるということなのか、区の後援をもらえば優遇してくれるのかとか、それはいかがですか。","respondent":"稲田土木管理課長","answer":"ということは、３,２２０円掛ける５m2の６０単位ということで、１９万３,２００円ということで、手数料はいただいているという状況です。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"それとはまた別なのですか。道路に何か光みたいなので映し出していくという、あれもこのプロジェクションマッピングの範疇になるのでしょうか。あれこそきちんと取り締まらないと、ただで区道とか都道とかを使ってやっているという部分もあるので、それこそ、それはきっちりと指導していかなければいけないことだと思うのですが、それはこれに関わってくるのでしょうか。","respondent":"稲田土木管理課長","answer":"公益性の話です。やはりまちづくりで、にぎわいとかそういうものが非常に重要だというところで、プロジェクションマッピングも項目が新しくできたですので、そういう公益性のあるものに対しては、その状況を考えながら、ということで考えております。","id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つかお聞きしたいのですが、これは許可申請なので、例えばこれは今キャナルフェスの夏バージョンで、たまたま２日間だけれども、１週間バージョンとか３日間バージョンとかがあると思うのです。それから、１回の許可だけど、その期間中に中身を変える場合があるではないですか。交渉は民間の人たちがやるからいいけれども、その許可申請でどう捉えるのかという考えを、まず教えていただきたい。","respondent":"稲田土木管理課長","answer":"許可申請、あるいは届出だけで済むというものもありまして、届出というのはお金がかからないというところなのですが、もちろん届けは出しまして、チェックが必要なのですが、表示期間が３か月以内、企業広告等の占める割合がおおむね３分の１以下、面積ではなくて、流している間。","id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"質問","question":"今の話だと、夏、挑戦していたけれども、オリンピックがなくなってしまったから、やめてしまったのだけれども、オリンピック期間中、例えばどうしようというのが必ず出てくるではないですか。だけど、これ、来年やるとしたら、そういう今言った、メインスポンサーが「うん」と言ってくれないと映像自体が流せないというのも、どういうふうに考えるのかというのを改めて教えてください。","respondent":"稲田土木管理課長","answer":"ただ、去年でしたか、広告が入っていない部分についてはお金をもらっていないというようなことを、担当が言っていたような気がしますし、その内容とか表示の仕方、あるいは期間をどうするかというのは、やはり個々のその内容によって相談していきたい。","id":"exchange-052"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"条例の審査については区民委員会でしょうから、そこには触れないですが、ぜひこういうものはどんどん推し進めていただいて。来年に延びたので、それはぜひ来年またそういう機会があれば、お話をさせていただきたいと思います。港区とかで。あのトランスの上は全く議論にならなかったのですか。実験は相当やっていますよね。","respondent":"稲田土木管理課長","answer":"プロジェクションマッピングの実証実験というのをやっているのです。これが２０１９年３月１５日から同年８月３１日までです。トランスの上の広告物については、私のほうは今把握しておりませんので、また、その辺、少し調べてみます。","id":"exchange-053"}]},{"id":"topic-07","title":"第二弾マンホールカード配布","agenda":"第二弾マンホールカード配布","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"幾つか確認させていただきたいのですけれども、配布開始日ということで７月２日ということだったのですけれども、私、これを見たとき、７月２日だけで終わるのかと思ったら、開始日ということなので、いつまでなのかということをお伺いしたいのと、枚数の制限があるのかということ。","respondent":"溝口道路課長","answer":"今回、カードの中に書いてあります説明文につきましては、実際、このカードを申請する際に、品川区から写真ですとか説明の内容、そういったものを併せて申請することによって、今回、カードの発行というのができましたので、説明文につきましては。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問","question":"大井町での第一弾も今現在続いているということなのかということと、あと、このカードについてですけれども、ＱＲコードがどこにつながるのかというのはご説明があったのですが、下水道広報プラットホーム、ＧＫＰというところにつながるのですかというのと、あとまた、そのカードの記載内容ですけれども、品川区といったことなのですが、品川区の担当はどこですか。","respondent":"溝口道路課長","answer":"あくまでも今回はデザインの中身、マンホールの蓋のデザインをどのような形で描いていくのか、どういうイメージをしたのかというところで、説明を入れするような形になっております。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問","question":"マンホールカード発行の目的について、下水道広報プラットホームのほうを読ませていただいたときにも、下水道を気に留めていなかった方々にも興味関心の入り口としていただくために、このカードを活用してほしいといった趣旨で書かれているので、マンホールに関心が行くことに加え、下水道の重要さというのを、今後もまたカードを新しく購入するときなどに。","respondent":"溝口道路課長","answer":"そうすると、要はほかの自治体もカードを発行したいというところもあって、なかなか応募しても希望が通らないということもある中、品川区については、もう既に２つのマンホールカードを発行しているという実績もありますので、そこはなかなか難しい部分もあるとは思いますが。","id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"では今後もまた、新たに作成されるということになった場合には、ぜひ下水道の事業についても、１文を添えていただくように。ほかの自治体のマンホールカードを見てみても、１文添えている自治体もあるので、マンホールだけではなく下水道事業にももっと関心がいくように、ぜひお願いしたいと思います。要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"これ、ＰＲ方法はどうするのかと思うのです。設置場所が武蔵小山駅前、それで、配布先がスクエア荏原。遠いなという感じなのですけれども、どういう形で誘導するのか。その宣伝をどうするのですかということ。せっかくこのかわいい品川紋次郎で、それも品川区の特徴の１つという形になるので、全国的に広めたいという思いもあるのですけれども、その仕掛けはどうするのでしょうか。","respondent":"溝口道路課長","answer":"今回の全国のマンホールカードの考え方でいきますと、無料で、かつ郵送等は一切対応しないというのがルールになっておりまして、やはりそのご当地、あるところに行っていただいてマンホールを見ていただく、またはそこのまちを歩いていただきながら。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"知っていただくということなのですが、配布場所は、多分ホームページではお知らせするのだろうと思います。大井町は、あそこに観光案内所があるのですけれども、ここは結構分かりづらいという感じがあるものですから、そこが少し心配です。迷われる。一応地域を見ていただくという１つの方法はあるにせよ、やはり動線というのは考えてあげないといけないかと思うのですが、何か工夫はできないのでしょうか。","respondent":"溝口道路課長","answer":"ホームページでは設置場所、またはカードの配布場所、それも併せてＰＲしていきたいと考えておりますので、それを見ていただければ分かるような形になっております。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"今後第三弾、第四弾はないですか。これ、増やしてほしいという思いがあるのです。なので、年に１回、１か所とかという形でやっていただければうれしいと思うのですが、いかがですか。","respondent":"溝口道路課長","answer":"カードを２枚発行しております。そういったものをうまく育てていくといいますか、それを活用しながら、まずはしっかりＰＲをしていきたい、区の観光に寄与するような取り組みをしていきたいと考えているところです。","id":"exchange-060"},{"speaker":"田中委員","kind":"確認","question":"すみません、先ほど確認し忘れてしまったのですけれども、予算はどうなっているのか、お知らせください。","respondent":"溝口道路課長","answer":"そのほか、マンホール等を設置する場合には、５０万円ぐらいかかったりしますので、もろもろにすると結構費用はかかっていますが、カードの発行だけでいきますと、カードの購入費用の税抜きで４万円というのが、費用としては実際にかかるというものです。","id":"exchange-061"}]},{"id":"topic-08","title":"みどりの実態調査の結果","agenda":"みどりの実態調査の結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"本来、公園ができたら、整備されたら、みどりが増えるという気がするのですが、そこのところを少し伺いたいのと、あと、みどり率と緑被率の２つあるのですが、この２つある意味というのですか、教えていただきたいと思います。","respondent":"高梨公園課長","answer":"整備したての部分が特にしながわ区民公園等にはありますし、大井ふ頭中央海浜公園についても、オリンピック施設の建設によって整備がされたところで、一時的にみどりが減っている部分があろうかとは思いますけれども、樹木が育ってまいりますと、５年後。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"公園整備の中で減ってしまった原因というのは、分かりました。そういった整備で減ってしまうということもあるということだと思いますが、やはり緑被率を上げていくということが重要だと思います。指標の中ではみどり率を見ているということですが、緑被率のほうも見ていくべきではないかと思うのですが、いかがでしょうかということと、みどり率で見ている理由を伺いたいと思います。","respondent":"高梨公園課長","answer":"みどり率だけでなく緑被率もといったところなのですが、まず、従前から緑被率も計測をしてまいりましたので、しっかりと緑被率のほうも継続して見ていくということは、今までと変わらずに行ってまいりますが、加えて、先ほどの答弁の繰り返しになりますが、水面であったり。","id":"exchange-063"},{"speaker":"のだて委員","kind":"意見","question":"各区でスタンダードになっているので、みどり率で見ていくということでしたが、計画の中にもみどり率の目標しかないですよね。なので、やはり緑被率の目標をもっていく必要があるのではないかと思います。今後、計画の見直しを検討されていくと思いますので、そういったところでも、ぜひ緑被率の目標ももつような形で検討していただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"田中委員","kind":"質問・要望","question":"細かなところで少し分からないところがあって、お知らせいただければと思うのですけれども。みどり率調査の中の水面（公園以外）のところが少し下がった理由というのが、どういう意味なのかというのを知りたくて、お知らせいただきたいのと、あと、今年度より水とみどりの基本計画・行動計画の改定作業が行われるということで、そのスケジュール感を伺っていきたいです。","respondent":"高梨公園課長","answer":"今の予定としましては、年度末までに素案のとりまとめといったところを、１つのコントロールポイントで考えているところです。その後、来年度に入りまして、年度当初からパブリックコメントを実施し、年度中盤ぐらいで計画の改定公表といったところが、現在のスケジュールです。","id":"exchange-065"},{"speaker":"田中委員","kind":"確認","question":"水とみどりの基本計画・行動計画の改定作業について、了解しました。この建設委員会でも、この素案の作成だったり報告だったり、これからきちんと上がってくるのですよね。では、これから確認していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問・要望","question":"この品川区のゴールは何かというところ、何を求めているのだろうか。そうしたら早くみどりになりますよね。それに対して、では、いろいろな指標があるにせよ、品川区がどういうまちをここから、水とみどりの計画の中では描いているのだろうか。多分、計画の改定作業の中では、当然それが入ってくるのだろうと思いますけれども、品川区の現状として、どういう方向性にもっていきたいのかを教えてください。","respondent":"高梨公園課長","answer":"みどりの総量といったところに行かないまでも、皆さんの暮らしの中でみどりが息づく、潤いのある暮らしが実現できるいい手法を、今後、計画改定の中でしっかりと議論していこうと考えています。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"でも、結局、倒木になってはいけないから、伐採をして、そこをまた整備しなければいけないというと、またそこはゼロからスタートになるわけですよね。それは仕方がないことだと思うのです。では、どういう品川区のみどり環境というか、みどり率というのを求めていくのかとなってくると、全く新しい視点も含めて、何のためにこれをやっているのかということですよね。これは意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけお願いと考え方を。今、我々は少し、このみどりについてはいろいろ議論をしています。このみどり率でも緑被率でもいいのだけれども、評価を少し変えていったほうがいいかと。例えば水辺千本桜計画、これは１,０００本やって、３月の終わりから４月ぐらいにあそこへ行けば桜がきれいだね、と。今なら、例えばアジサイ。東京都は、赤というのが少ないから。そこら辺の感覚は少し教えていただきたい。","respondent":"高梨公園課長","answer":"今、ヒントをいただきましたので、検討委員会の中では、要素としてしっかり議論をさせていただきたい、このように感じているところです。","id":"exchange-069"},{"speaker":"田中委員","kind":"確認","question":"そのみどり率だったりの数値目標について、先ほどお話があったと思うのですけれども、数値目標は、全くなくすといったわけではないですよね。いろいろな所管課とのまちづくりのバランス、そういったこともあると思うので、何というのだろう、数値目標は目標としてもっていてもいいのではないかと思ったので、そこの部分だけ少し確認させてください。","respondent":"高梨公園課長","answer":"そういった他区の状況の違い、立地の違い等を含んだ上での、品川区に合った、例えばみどり率の目標、あるいはみどり率ではない、先ほどご意見をいただきましたけれども、ほかの指標、色であったり、そのほかの要素、まちの中から見えるみどりであったり。","id":"exchange-070"}]},{"id":"topic-09","title":"第二戸越幹線整備工事（下水道本管立坑整備）","agenda":"第二戸越幹線整備工事（下水道本管立坑整備）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"いろいろな変更内容があるということは分かりましたが、これは事前に分からない内容だったのでしょうか。途中のいろいろな変更点は致し方ないというのは理解するとしても、４項目あるわけです。この４項目は、やはり事前の調査の中では分からなかったという内容のものなのでしょうか。突発的なことで、通常よりは特殊な状況だったという理解でよろしいのでしょうか。","respondent":"松本河川下水道課長","answer":"ほかの３つにつきましては、実際に今回、立坑整備する際の位置が若干変更になってございまして、これは、第１回目の変更のときにお示しさせていただいてはいるのですが、その変更に伴って、場所が変わったことによる仮囲いの位置の変更であったり。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"この工期については長くなったのですか。それとも、変わらずこの期間でやるということでしょうか。工期の変更はあるのでしょうか。","respondent":"松本河川下水道課長","answer":"工期につきましては、今回の変更内容につきましての変更はございません。","id":"exchange-072"},{"speaker":"西本委員","kind":"意見","question":"変更がないということにおいて、あとは金額の問題とか、いろいろ絡んでくるところだと思いますけれども、あそこは区営の公園であるので、あそこを使っていた人たちも、今ほかのところでいろいろな活動をされているというところもあって、延びると、また説明が必要なのかと思ったのです。そういうものがなければ、このままで進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"工期のところで、今回７月１６日までということですが、その後に西品川公園は使えるようになるということですか。いつから使えるのかというところで、伺いたいと思います。","respondent":"松本河川下水道課長","answer":"この第二戸越幹線整備工事につきましては、今、一応、令和６年までを予定しておりますので、西品川公園につきましては、一応、令和６年度まで使用するという予定です。","id":"exchange-074"}]},{"id":"topic-10","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"少しご説明があったのですが、連続立体交差事業というのが、前回の委員会の中では出ていなかったように思うのですが……。出ていましたか。ほかの意見もいろいろあったと思うのですが、この２つの項目になった理由というのをもう少し詳しくありましたら、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"「まちづくりに関すること」というように入っているのですが、これは、連続立体交差事業とその周辺ということではなくて、もっと広い意味での、例えばマスタープランとかも含めての「関すること」ということの理解でよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"田中委員","kind":"確認","question":"私も確認です。この「コロナ禍における避難所のあり方について」ですけれども、コロナ禍における避難所でもありつつ、ウイルスであったり細菌であったりの対策も一緒にといった、いろいろな可能性があると思うのです。新型コロナウイルス感染症に限らず、細菌であったりウイルスの発生とかに対する避難所のあり方だといいなと思って、今、確認をしたいと思ったのですけれども、いかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは建設委員会だから、今のは非常に微妙で、そうすると専門的な方を呼ばなくてはならない。所管事務調査になると、“ウイルスがこうだ”とか、“これがこういうことだから、ウイルス対応でこうだ”というと、建設委員会の枠を超えていく。危機管理みたいな部分だと行財政改革特別委員会とかもあるから。お任せしますが、ぜひそこら辺は考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503098?Template=document&Id=4296#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":55606,"voices":213}}]);
